--------------------------------------------------------------------------------
-- ОБУЧЕНИЕ v7 — ДИАЛОГОВЫЙ ПРОЛОГ.
--
-- ЧТО ЗАМЕНИЛО. Старый 12-шаговый гайд жил целиком внутри
-- CustomCartUI.client.lua (одна функция на ~1560 строк) и разошёлся с игрой
-- после двух переделок подряд:
--   • шаг 1 ждал атрибут CarryingCart — но с v12 у нового игрока тележки
--     физически нет, у него в рюкзаке лежит УПАКОВКА (см. Config.CartPackage);
--   • шаг 2 ("поставь тележку в зону шахты") проверял атрибут MineActive,
--     который в новом MineService означает просто "у игрока есть тележка со
--     свободным местом" — шаг засчитывался где угодно на карте;
--   • шаг 3 ("жди 12 капель руды") ждал авто-добычу, которой больше нет:
--     руда добывается ТОЛЬКО экспедицией (см. Config.MineExpedition).
-- Прогресс при этом хранился на КЛИЕНТЕ и обнулялся при каждом перезаходе.
--
-- ЧТО СТАЛО. Шаги — данные (таблица Steps ниже), а не код. Состояние ведёт
-- сервер (TutorialService), пишет его в профиль (Data.TutorialStep) и сам
-- проверяет условия. Клиент (TutorialUI.client.lua) только рисует
-- диалоговое окно и стрелку к цели — подделывать ему нечего.
--
-- ФОРМА ПОДАЧИ — диалоговое окно снизу экрана (плашка имени + портрет +
-- посимвольная печать), которое ПОСЛЕ реплик сворачивается в однострочную
-- плашку-задание и разворачивается обратно на следующем шаге. Один элемент
-- на экране в любой момент времени.
--
-- ЧТО ТУТОРИАЛ СОЗНАТЕЛЬНО НЕ ТРОГАЕТ: жеоды, острова, подиум, сейф,
-- гоблины, динамит, сундуки, престиж, PvP. Всё это объясняется по одной
-- механике за раз через Config.Tutorial.Hints — ровно в тот момент, когда
-- игрок впервые сталкивается с ней сам.
--------------------------------------------------------------------------------
Config.Tutorial = {
