	-- игрока просят подойти, потом остаётся его постоянной точкой входа в
	-- добычу — не одноразовый персонаж "только для тутора".
	SpeakerName = "MINER",
	-- Портрет в диалоговом окне. Тот же крот-маскот, что на загрузочном
	-- экране (см. Config.UI.TutorialMoleImageId) — 0 отключит картинку,
