	--   Short  — заголовок в свёрнутой плашке-задании (КАПС, 2-4 слова).
	--   Task   — сама задача одной строкой.
	--   Goal   — условие перехода, см. TutorialService:_goalProgress:
	--              { Kind = "Ack" }                     — просто "Далее"
