--------------------------------------------------------------------------------
-- ПОДСКАЗКИ ПОСЛЕ ГАЙДА (не часть основного туториала).
--
-- ЗАЧЕМ ЭТО ОТДЕЛЬНО ОТ ГАЙДА ВЫШЕ. Основной 12-шаговый гайд (Config.
-- Tutorial) ведёт по КОСТЯКУ игры (шахта → тележка → банк → жеода →
-- кристалл → сейф → бой) — и специально НЕ включает вторичные механики,
-- иначе стал бы длиннее и утомительнее для ребёнка на первой минуте. Но у
-- игры есть механики, которые ИНАЧЕ игрок может вообще никогда не открыть
-- сам, потому что ничто на экране не намекает на их существование:
--   - Подарить кристалл другому игроку (RockService:GiftCrystal) — промпт
--     появляется, только если стоишь рядом с игроком, НЕСЯ кристалл в
--     руках — то есть по чистой случайности.
--   - Разбивать валуны по карте ради бонусных кристаллов (Config.Boulders)
--     — они просто стоят в мире без единой подсказки, что их можно трогать.
--
-- Каждая подсказка — один тост NotifyService, ровно один раз за профиль,
-- через фиксированную задержку ПОСЛЕ завершения основного гайда (см.
-- QuestService:_scheduleTips, вызывается из CompleteTutorialRequest и при
-- заходе игрока, который уже прошёл гайд раньше). Задержки специально
-- РАЗНЕСЕНЫ по времени — если бы обе подсказки выпадали разом сразу после
-- гайда, это выглядело бы как ещё один экран текста, который никто не
-- читает, а не как естественная подсказка "в моменте".
-- ПУСТО — обе прежние подсказки (подарить кристалл, разбивать валуны)
-- теперь объясняются ВМЕСТЕ через Config.Quests.Starter.FirstBoulder.
-- OnActivateTip (см. QuestService:_maybeShowQuestActivationTip) — этот
-- тост всплывает РОВНО в момент, когда квест про валун реально становится
-- активным (после апгрейда кирки до тира 2), а не по слепому таймеру
-- после тутора, который мог сработать заметно раньше или позже того, как
-- игрок физически дошёл до этой точки прогрессии. Оставлена как рабочий
-- механизм — новые тайминг-подсказки, не завязанные на конкретный квест,
-- по-прежнему можно добавлять сюда.
Config.Tips = {}

-- Промокоды — вводятся в меню настроек (Discord и т.п.). Каждый код
-- разово на аккаунт (DataService:RedeemCode проверяет и запоминает).
-- Ключи — ВСЕГДА заглавными без пробелов (сервер сам нормализует ввод).
Config.PromoCodes = {
	-- Имя ключа может быть любым. Регистр/пробелы при вводе игнорируются.
	-- ExpiresAt: nil = бессрочно, Unix timestamp ИЛИ дата "YYYY-MM-DD" (UTC).
	-- Суммы подняты ×1.6 вместе с денежными паками: промокоды получают на
	-- РАННЕЙ стадии игры, а цены первых тиров выросли именно во столько раз
	-- (см. Config.MineChain). Без этого награда за код незаметно
	-- обесценилась бы вместе с ребалансом.
	-- Суммы промокодов пересчитаны вместе со сменой масштаба экономики (÷100,
	-- см. Config.Crystal_BaseValue) — та же ранняя-стадийная доля прогресса,
	-- что и раньше, просто в новых числах.
	DISCORD = { Money = 600, Enabled = true, ExpiresAt = nil },
	LAUNCH = { Money = 300, Enabled = true, ExpiresAt = "2027-01-01" },
	["RELEASE<3"] = { Money = 350, Enabled = true, ExpiresAt = nil },
	MINEMOLEHUNTER = { Money = 350, Enabled = true, ExpiresAt = nil },
	-- v16: код с табло лайков (Config.LikeGoals). RequiresLikes — код
	-- работает только когда Config.LikeGoals.CurrentLikes ≥ этого числа.
	-- Chest — вместо/вместе с деньгами выдаёт сундук этой редкости.
	LIKES50 = { Money = 0, Chest = "Rare", RequiresLikes = 50, Enabled = true, ExpiresAt = nil },
	OLDLAUNCH = { Money = 150, Enabled = false, ExpiresAt = nil },
}

