		RepairCost = 120,
		RepairCostDuringTutorial = 0,
		Color = Color3.fromRGB(12, 12, 16),
		-- Neon намеренно, а не SmoothPlastic: чёрный неон читается как
		-- "выключено/обесточено", а не как "тёмная текстура".
		Material = Enum.Material.Neon,
		RepairFadeSeconds = 1.2,
		-- Что НЕ обесцвечивать — служебные детали, которым внешний вид
		-- задаёт другой код (дверь красится по редкости руды в
		-- MineService:_applyDoorRarity, Zone невидима и так).
		SkipNames = { Zone = true, MineDoor = true },
	},
	SpawnInterval = 2.0 / 1.15, -- ровно на 15% быстрее прежних 2 сек на кристалл
	SpawnSpeedBonusPerTier = 0.05, -- каждый тир шахты ускоряет следующий спавн на 5%
	-- "Тележка у шахты?" теперь проверяется по РЕАЛЬНОЙ площади части Zone
	-- (см. MineService/PlotService), а не по радиусу от центра — отдельного
	-- числа тут больше не нужно.
}

--------------------------------------------------------------------------------
-- РИТМ-МИНИ-ИГРА ВО ВРЕМЯ ДОБЫЧИ — по прямому запросу, чтобы не было
-- скучно стоять и ждать, пока шахта заполнит тележку саму. Пока игрок
-- реально стоит с тележкой в зоне шахты (та же проверка, что двигает
-- обычную добычу — см. MineService.activeCarts), время от времени на
-- экране всплывает кнопка; успел нажать — сразу RewardOreCount руды
-- падает в тележку (в дополнение к обычной добыче, не взамен неё), и
-- ТУТ ЖЕ появляется следующая кнопка КОМБО-цепочки — с более коротким
-- окном на реакцию (первая попытка ощутимо легче, чем raньше — 2 сек, а
-- не 0.9, чтобы дети успевали; сложнее становится только если уже
-- поймал предыдущую). Промах на любом шаге просто обрывает цепочку без
-- штрафа — то, что уже поймано до этого, остаётся начисленным.
--------------------------------------------------------------------------------
Config.MiningRhythm = {
	-- ВЫКЛЮЧЕНО: механика "тележка стоит в зоне шахты → руда сама
	-- капает/мигает кнопка" полностью убрана по ТЗ ("удали механику
	-- выпадения руды из шахты при наступлении рядом тележки"). Добыча
	-- теперь идёт ТОЛЬКО через НПС-экспедицию, см. Config.MineExpedition
	-- и новый MineService.lua. Таблица и код мини-игры оставлены в файлах
	-- (не удалены физически), чтобы легко вернуть при желании — просто
	-- Enabled = true и заново подключить вызовы в MineService.
	Enabled = false,
	MinIntervalSeconds = 14, -- пауза между началами цепочки — рандом в этом диапазоне
	MaxIntervalSeconds = 26,
	-- Окно на реакцию для каждого шага комбо по порядку — длина списка =
	-- максимальная длина цепочки. По прямому запросу — больше 3 шагов
	-- (сейчас 5) и ускорение попроще, чтобы у игрока с медленной реакцией
	-- цепочка сама быстро обрывалась (не тянулась бы долго для всех
	-- подряд) — а не потому что шагов стало меньше.
	ComboWindowSeconds = { 2.0, 1.4, 1.0, 0.7, 0.5 },
	ComboStepPause = 0.2, -- небольшая пауза после попадания, прежде чем показать следующую кнопку — иначе следующая кнопка появлялась бы мгновенно поверх фидбека "NICE!"
	RewardOreCount = 4, -- сколько руды падает в тележку ЗА КАЖДОЕ попадание (не суммарно на всю цепочку)
}

--------------------------------------------------------------------------------
-- ЭКСПЕДИЦИЯ В ШАХТУ v2 — ПОЛНАЯ ЗАМЕНА старой механики "подъехал тележкой —
-- посыпалась руда". См. ТЗ целиком (в двух сообщениях) — коротко:
--   1. Игрок подходит к НПС слева от шахты → диалог → "ОТПРАВИТЬСЯ В ШАХТУ".
--   2. НПС и игрок анимацией ходьбы идут внутрь, камера отъезжает и
--      поднимается (см. NpcWalkInSeconds/CameraDolly ниже).
--   3. Мини-игра "дуга": стрелка катается туда-сюда по дуге, 3 раза подряд
--      спавнится случайная зона на дуге — успеть тыкнуть, пока стрелка в
--      зоне. 3 попадания = добыча состоялась.
--   4. Каждое попадание — FOV-пружинка + шахта "дышит" (расширяется/трясётся)
--      + дверь шахты (MineDoor, см. ниже) обновляет неоновый цвет.
--   5. На 3-м попадании — камера ныряет к земле, из шахты хаотично
--      вылетает вся выбитая руда (см. MineService:_ejectOre), игрок с НПС
--      выходят обратно, камера возвращается игроку.
--   6. Руда лежит на земле — подбирается НАЕЗДОМ тележки (см. CartService).
--------------------------------------------------------------------------------
Config.MineExpedition = {
	-- ШАГ 2: ходьба внутрь.
	NpcWalkInSeconds = 2.2,
	NpcWalkOutSeconds = 2.0,
	-- ID анимации ходьбы НПС/игрока внутрь шахты. Оставь 0, чтобы играть
	-- только перемещение (Humanoid:MoveTo) без самой анимации, пока не
	-- вставишь свой AnimationId (см. ТЗ — "я просто вставлю айди анимки").
	WalkAnimationId = 0,

	-- ШАГ 2: камера. CameraBackOffset — насколько камера отъезжает НАЗАД
	-- (по -LookVector входа шахты) от точки, где встал игрок для мини-игры,
	-- CameraUpOffset — насколько выше. TweenSeconds — длительность отъезда
	-- (тот же "рывок", что при апгрейде — playUpgradeRevealCamera в
	-- CustomCartUI.client.lua, см. комментарий там).
	CameraBackOffset = 22,
	CameraUpOffset = 16,
	CameraDollySeconds = 1.4,
	CameraFOVDefault = 70,
	CameraFOVMinigame = 62, -- чуть уже во время дуги — фокус на воротах шахты

	-- МАРКЕРЫ КАМЕРЫ (по прямому запросу — "камера летает не так, как
	-- хочет сейчас, а я буду спавнить маркеры с направлением куда она
	-- должна смотреть при каждой ситуации"). Билдер кладёт в модель шахты
	-- пары частей "CameraMarkerN"/"CameraMarkerNLook" (N — просто номер;
	-- см. подробности в PlotService:_buildMine). Здесь — какой номер
	-- маркера отвечает за какую стадию экспедиции. Для стадии, для
	-- которой в этой таблице нет номера ИЛИ у шахты нет соответствующей
	-- пары маркеров, клиент использует старый расчётный долли (см.
	-- CameraBackOffset/CameraUpOffset выше и dollyTo в
	-- MineExpeditionUI.client.lua) — так шахты без маркеров не остаются
	-- совсем без камеры.
	CameraMarkerForStage = {
		WalkIn = 1,
		Minigame = 2,
		Eject = 3,
		WalkOut = 1,
	},

	-- КАМЕРА ПО ОСИ "ШАХТА → БАНК" (по прямому запросу — "вместо работы по
	-- маркерам камеру тоже переделай").
	--
	-- Маркеры требовали ручной расстановки в каждой шахте и молча
	-- отваливались там, где их забыли поставить. Вместо этого камера
	-- теперь СЧИТАЕТСЯ: берём горизонтальное направление от шахты к банку
	-- и отходим вдоль него на нужное расстояние и высоту. Это работает на
	-- любом участке без единого маркера, а разговор с НПС, мини-игра и
	-- выброс руды отличаются только парой чисел.
	--
	--   Talk  — игрок говорит с шахтёром: далеко и ВЫСОКО, смотрим на
	--           шахту сверху (обзорный план, видно весь участок).
	--   Eject — шахта "лопнула": уходим ЕЩЁ дальше в сторону банка и
	--           опускаемся почти на землю (низкий, "киношный" план, руда
	--           летит прямо над камерой).
	UseBankAxisCamera = true, -- false вернёт старое поведение по маркерам
	-- Ещё дальше к банку (было 72/42): с такого отлёта в кадр помещается и
	-- шахта целиком, и вся площадка, куда полетит руда.
	-- Чуть ближе и ниже, чем было (96 / 50) — по прямому запросу.
	CameraTalkDistance = 84,
	CameraTalkHeight = 40,
	CameraTalkSeconds = 1.4,
	CameraTalkAimHeight = 6, -- на сколько выше основания шахты целится камера
	-- ВЫБРОС РУДЫ: ещё ближе к банку и чуть шире объектив. На тесном
	-- кадре разлетающаяся пачка вылезала за края — камера отходит дальше,
	-- а FOV дополнительно расширяется на CameraEjectFOVWiden, чтобы куски
	-- гарантированно помещались целиком.
	-- Ближе, чем было (92): руда теперь падает у самой шахты, и с 92 стадов
	-- она читалась мелко.
	CameraEjectDistance = 62,
	CameraEjectHeight = 8,
	CameraEjectAimHeight = 4, -- было 10: чуть наклоняем вниз, чтобы руда у самого объектива не уходила за нижний край кадра
	CameraEjectFOVWiden = 10, -- прибавляется к обычному FOV на время выброса

	-- ШАГ 3: мини-игра "дуга". HitsRequired — сколько удачных тычков нужно
	-- (ТЗ: ровно 3). Ширина зоны попадания ТЕПЕРЬ СЛУЧАЙНАЯ каждый раунд
	-- (ZoneWidthMin..ZoneWidthMax, доля от всей дуги [0,1]) — по прямому
	-- запросу "на каждой зоне свой шанс увеличения дропа": узкая (сложная)
	-- зона даёт больше LuckPerNarrowZone-бонуса при попадании, чем
	-- широкая (лёгкая), см. MineService:_onArcHit/LuckBonus и
	-- Config.RollOreForTier. SweepSeconds — время одного прохода стрелки
	-- от начала до конца дуги (туда-обратно, пинг-понг).
	-- RoundTimeoutSeconds — если игрок вообще не попал за это время, зона
	-- перевыпускается заново (мини-игра НЕ проваливается насовсем —
	-- просто ждём дальше, добыча — не боевая механика, штрафовать не за что).
	HitsRequired = 3,
	-- ЗОНЫ ДУГИ (по прямому запросу — "красная зона должна быть почти на
	-- весь ползунок, жёлтая на 50 процентов больше, а зелёную процентов на
	-- 5 больше").
	--
	-- РАСКЛАДКА ИЗМЕНИЛАСЬ. Раньше это были пять отдельных плашек встык
	-- (Red|Yellow|GREEN|Yellow|Red), которые вместе занимали всего 38%
	-- дуги — остальные 62% были пустотой, где клик просто не засчитывался.
	-- Теперь это ВЛОЖЕННЫЕ полосы, как в обычной рыбалке/чекпоинте:
	--
	--   [=========== RED (почти вся дуга) ===========]
	--          [==== YELLOW ====]
	--              [ GREEN ]
	--
	-- Красная — фон почти на весь ползунок, жёлтая лежит поверх неё,
	-- зелёная — поверх жёлтой. Промахнуться "в никуда" теперь почти
	-- невозможно, а попадание всё равно имеет градацию: чем точнее, тем
	-- больше удачи.
	--
	-- Width — доля ВСЕЙ дуги [0,1]. Luck — сколько "удачи" даёт попадание
	-- в эту зону (см. MineService:_onArcHit → Config.RollOreForTier —
	-- удача наклоняет финальный ролл руды к более редким слотам тира).
	-- Позиция связки каждый раунд случайная, заучить нельзя.
	-- РАСКЛАДКА ДУГИ (по референсу). Сегменты идут ПОДРЯД и покрывают
	-- дугу ЦЕЛИКОМ — сумма Weight равна 1. Именно это чинит "стрелка не
	-- попадает в края": раньше зоны занимали кусок дуги, а всё остальное
	-- было пустотой, где клик не засчитывался; теперь пустоты нет вообще,
	-- любое положение стрелки попадает в какой-то сегмент.
	--
	-- "Dead" — серые заглушки по краям (как на референсе): в них попасть
	-- можно, но удачи они не дают. Каждый раунд список ЦИКЛИЧЕСКИ
	-- сдвигается на случайное число позиций, поэтому раскладку нельзя
	-- заучить, но она всегда остаётся сплошной и красивой.
	ArcSegments = {
		{ Kind = "Dead",   Weight = 0.07 },
		{ Kind = "Green",  Weight = 0.10 },
		{ Kind = "Yellow", Weight = 0.11 },
		{ Kind = "Red",    Weight = 0.13 },
		{ Kind = "Green",  Weight = 0.18 },
		{ Kind = "Red",    Weight = 0.13 },
		{ Kind = "Yellow", Weight = 0.11 },
		{ Kind = "Green",  Weight = 0.10 },
		{ Kind = "Dead",   Weight = 0.07 },
	},

	ZoneKinds = {
		-- 0.06 → 0.063: +5%, как и просили. Зелёная намеренно осталась
		-- почти такой же — она и должна требовать точности, иначе весь
		-- смысл целиться пропадает.
		Green  = { Width = 0.063, Luck = 0.10, Color = Color3.fromRGB(80, 200, 90) },
		-- 0.07 → 0.105: ровно +50%. Это ПОЛНАЯ ширина жёлтой полосы
		-- (раньше 0.07 было шириной ОДНОГО из двух жёлтых крыльев).
		Yellow = { Width = 0.105, Luck = 0.05, Color = Color3.fromRGB(235, 180, 55) },
		-- "Почти на весь ползунок": 94% дуги, оставшиеся 6% — узкие поля
		-- по краям, чтобы позиция связки всё-таки могла гулять и раскладка
		-- не была одинаковой каждый раунд.
		Red    = { Width = 0.94,  Luck = 0.01, Color = Color3.fromRGB(210, 70, 60) },
		-- Серые заглушки по краям дуги (см. ArcSegments). Клик засчитывается,
		-- удачи не даёт — ровно как промах, но теперь это ВИДНО заранее.
		Dead   = { Width = 0.07,  Luck = 0,    Color = Color3.fromRGB(90, 85, 80) },
	},
	-- Клик ВООБЩЕ мимо всех зон (в те самые 6% полей) теперь тоже
	-- засчитывается как попадание — по прямому запросу "когда по пустой
	-- зоне кликаешь, тоже должно регать". Удачи не даёт, но раунд
	-- двигает: игрок нажал — игра отреагировала. Раньше такой клик
	-- проваливался в тишину, и это читалось как "игра зависла".
	MissLuck = 0,
	MissColor = Color3.fromRGB(150, 150, 160),

	----------------------------------------------------------------------------
	-- МИНИ-ИГРА "РУДНАЯ ЖИЛА" (вариант A). ZoneKinds/ArcSegments выше —
	-- старая раскладка, больше не используется (оставлена для истории).
	--
	-- Удача: PERFECT (самородок) и GOOD (кристаллы). Промах — мимо зон —
	-- удачи НЕ даёт вовсе (по прямому запросу), но удар засчитывается и
	-- раунд идёт дальше.
	----------------------------------------------------------------------------
	VeinLuck = { Perfect = 0.10, Good = 0.05, Miss = 0 },
	VeinColors = {
		Perfect = Color3.fromRGB(255, 205, 70),
		Good = Color3.fromRGB(110, 210, 90),
		Miss = Color3.fromRGB(215, 90, 80),
	},
	-- РАЗНЫЕ ЗОНЫ НА КАЖДЫЙ УДАР (вариант 1). Ширины — доли жилы [0..1].
	--   Good    — ширины кристальных зон этого удара (их может быть несколько);
	--   Perfect — ширина самородка внутри ОДНОЙ случайной кристальной зоны;
	--   Speed   — множитель скорости кирки (>1 — быстрее).
	-- Удар 1 широкий и спокойный, 2 уже, 3 — две маленькие зоны и быстрее.
	VeinRounds = {
		{ Good = { 0.24 }, Perfect = 0.055, Speed = 1.0 },
		{ Good = { 0.16 }, Perfect = 0.045, Speed = 1.1 },
		{ Good = { 0.10, 0.10 }, Perfect = 0.04, Speed = 1.2 },
	},
	VeinEdgeMargin = 0.04, -- зоны не прилипают к самым краям жилы
	VeinHitTolerance = 0.006, -- доля жилы: запас на округление, не на лаг
	-- Компенсация лага: клиент присылает, СКОЛЬКО секунд с начала раунда
	-- прошло у него в момент нажатия; сервер принимает это значение, только
	-- если оно не старше собственного времени больше чем на
	-- 2·пинг + VeinLagGrace (и не больше VeinLagMax).
	VeinLagGrace = 0.12,
	VeinLagMax = 0.35,

	-- МОДИФИКАТОРЫ ЗАХОДА (вариант 4). Выбирается один на весь заход с
	-- шансом ModifierChance, иначе заход обычный (без карточки).
	--   SweepMul    — множитель длительности прохода (<1 — быстрее);
	--   Motion      — "Eased": медленно у краёв, быстро в центре;
	--   GoodMul     — множитель ширины кристальных зон;
	--   PerfectMul  — множитель ширины самородка;
	--   ExtraGood   — сколько кристальных зон добавить в КАЖДЫЙ удар;
	--   LuckMul     — множитель всей удачи; PerfectLuckMul — только самородка.
	ModifierChance = 0.65,
	-- v14.3 — дополнительные поля режимов:
	--   Dual        — две кирки навстречу, засчитывается лучшая из двух;
	--   Momentum    — каждый PERFECT подряд ускоряет кирку (×MomentumSpeed)
	--                 и даёт +MomentumLuck к удаче следующего удара;
	--   Shrink      — { Seconds, MinFrac }: зоны сужаются к центру;
	--   GhostSeconds— через столько секунд зоны гаснут (бить по памяти);
	--   Reverse     — { Count, Min, Max }: кирка разворачивается в случайные
	--                 моменты (Count раз, между Min и Max сек от старта);
	--   Jackpot     — только один крошечный самородок (ширина JackpotWidth);
	--   Hits        — сколько ударов в заходе (вместо HitsRequired).
	Modifiers = {
		{ Id = "FastRock", Weight = 3, Title = "FAST ROCK", Subtitle = "Faster pick, +50% luck",
			Color = Color3.fromRGB(255, 140, 70), SweepMul = 0.72, LuckMul = 1.5 },
		{ Id = "GoldenVein", Weight = 2, Title = "GOLDEN VEIN", Subtitle = "Nuggets give x2.5 luck",
			Color = Color3.fromRGB(255, 205, 70), PerfectMul = 0.75, PerfectLuckMul = 2.5 },
		{ Id = "CrackedVein", Weight = 3, Title = "CRACKED VEIN", Subtitle = "One more crystal zone every hit",
			Color = Color3.fromRGB(140, 220, 120), ExtraGood = 1 },
		{ Id = "WideVein", Weight = 3, Title = "WIDE VEIN", Subtitle = "Bigger crystal zones",
			Color = Color3.fromRGB(120, 200, 255), GoodMul = 1.4, PerfectMul = 1.2 },
		{ Id = "UnstableRock", Weight = 2, Title = "UNSTABLE ROCK", Subtitle = "The pick speeds up in the middle",
			Color = Color3.fromRGB(200, 130, 255), Motion = "Eased", LuckMul = 1.3 },
		-- v14.3 --------------------------------------------------------------
		{ Id = "SlowMo", Weight = 3, Title = "SLOW MO", Subtitle = "Super slow pick, a bit less luck",
			Color = Color3.fromRGB(150, 220, 255), SweepMul = 1.8, GoodMul = 0.9, LuckMul = 0.85 },
		{ Id = "DualPicks", Weight = 2, Title = "DUAL PICKS", Subtitle = "Two picks — the best one counts!",
			Color = Color3.fromRGB(255, 120, 200), Dual = true, GoodMul = 0.85 },
		{ Id = "Momentum", Weight = 2, Title = "MOMENTUM", Subtitle = "Perfect streak = faster pick, more luck",
			Color = Color3.fromRGB(255, 90, 90), Momentum = true, MomentumSpeed = 0.85, MomentumLuck = 0.5 },
		{ Id = "ShrinkingVein", Weight = 2, Title = "SHRINKING VEIN", Subtitle = "Zones shrink — hit fast!",
			Color = Color3.fromRGB(120, 255, 200), GoodMul = 1.35, Shrink = { Seconds = 2.6, MinFrac = 0.3 }, LuckMul = 1.15 },
		{ Id = "GhostVein", Weight = 1, Title = "GHOST VEIN", Subtitle = "Zones vanish — hit from memory, +40% luck",
			Color = Color3.fromRGB(190, 200, 230), GhostSeconds = 0.7, LuckMul = 1.4 },
		{ Id = "Reverse", Weight = 2, Title = "REVERSE", Subtitle = "The pick turns around at random",
			Color = Color3.fromRGB(255, 170, 90), Reverse = { Count = 2, Min = 0.5, Max = 2.6 }, LuckMul = 1.2 },
		{ Id = "Jackpot", Weight = 1, Title = "JACKPOT", Subtitle = "One tiny nugget — x4 luck!",
			Color = Color3.fromRGB(255, 225, 60), Jackpot = true, JackpotWidth = 0.055, PerfectLuckMul = 4 },
		{ Id = "Frenzy", Weight = 1, Title = "FRENZY", Subtitle = "5 quick hits!",
			Color = Color3.fromRGB(255, 80, 160), Hits = 5, SweepMul = 0.72, LuckMul = 0.6 },
	},

	-- РЕАКЦИЯ ШАХТЫ НА УДАР — своя на каждый результат. Overshoot — насколько
	-- шахта "подпрыгивает" сверх накопленного роста (доля MineBaseScale),
	-- Shake — амплитуда тряски в стадах, ShakeSeconds — её длительность,
	-- Rocks — сколько каменных осколков вылетает из входа (у клиента).
	MineHitReaction = {
		Perfect = { Overshoot = 0.20, Shake = 0.55, ShakeSeconds = 0.4, Rocks = 22 },
		Good    = { Overshoot = 0.09, Shake = 0.22, ShakeSeconds = 0.28, Rocks = 14 },
		Miss    = { Dip = 0.06, Shake = 0.10, ShakeSeconds = 0.22, Rocks = 6 },
	},
	-- v9: цветные эффекты двери (неон по качеству удара, VFX_<Rarity>) —
	-- выключены; на клик только серые 3D-осколки вокруг всей шахты.
	DoorColorFX = false,
	-- v9: вход редкости подгоняется под размер ENTRY, но не сильнее этих рамок.
	EntryScaleMin = 0.75,
	EntryScaleMax = 1.5,
	SweepSeconds = 1.6,
	RoundTimeoutSeconds = 8,
	HitForgivenessSeconds = 0.12, -- запас на сетевую задержку клика, как в старой ритм-мини-игре

	-- "УДАЧА" ЗА МИНИ-ИГРУ (по прямому запросу — "с каждым кликом надо
	-- увеличивать редкость выпадения, хотя бы визуально или не сильно") —
	-- копится за экспедицию (см. MineService:_onArcHit → expedition
	-- .LuckBonus), применяется один раз при роллах ВСЕЙ пачки руды в
	-- конце (см. _ejectOre → Config.RollOreForTier(tier, luckBonus)).
	-- Сколько даёт каждая зона — см. ZoneKinds выше (Luck). За 3
	-- попадания подряд в ЗЕЛЁНУЮ набегает 0.30 — заметно, но не
	-- переворачивает шансы тира с ног на голову (см. потолок 0.6 в
	-- Config.RollOreForTier). Три красных дадут всего 0.03 — клик
	-- засчитан, но почти без пользы, ровно как и задумано.

	-- ШАГ 4: "пружинка" FOV на каждое попадание + тряска шахты.
	HitFOVKick = -6, -- отрицательное = временно СУЖАЕТСЯ (наезд), затем плавно возвращается
	HitFOVKickSeconds = 0.22,

	-- НАКОПИТЕЛЬНЫЙ НАЕЗД КАМЕРЫ (по прямому запросу — "сделай её
	-- динамичной, чтобы при каждом клике условно камера приближалась
	-- слегка"). В отличие от HitFOVKick выше, который отыгрывает назад,
	-- этот наезд ОСТАЁТСЯ: с каждым кликом базовый FOV становится уже, и
	-- к последнему попаданию камера заметно ближе к воротам шахты, чем
	-- была на первом. Отсчёт сбрасывается в начале каждой экспедиции.
	--
	-- Шаг отрицательный (сужение = приближение). Потолок нужен, чтобы
	-- длинная серия не загнала FOV в неприлично узкий "телескоп", при
	-- котором любое движение камеры выглядит рывком.
	-- Наезд сделан СЛАБЕЕ (было -3.5 за клик при потолке -14): на прошлых
	-- значениях к третьему попаданию кадр становился настолько узким, что
	-- шахта переставала помещаться целиком.
	HitFOVZoomStep = -1.8,
	HitFOVZoomMax = -6,
	HitFOVZoomSeconds = 0.35,
	MineShakeMagnitude = 0.35,
	MineShakeSeconds = 0.3,
	-- Во сколько раз модель шахты "раздувается" на пике каждого попадания
	-- (ScaleTo вокруг текущего размера, потом плавно назад).
	-- ПОСТОЯННЫЙ РАЗМЕР ШАХТЫ (по прямому запросу — "+30% для любого тира").
	-- Это БАЗОВЫЙ масштаб, вокруг которого пляшут все временные эффекты
	-- (рост при ударах, "взрыв"). Если бы рост/взрыв продолжали считать
	-- от 1, они бы на каждом ударе SBRAсывали шахту обратно к её
	-- АВТОРСКОМУ размеру (Model:ScaleTo принимает АБСОЛЮТНЫЙ масштаб от
	-- исходной геометрии, а не "от текущего") — постоянная прибавка бы
	-- пропадала при первом же клике мини-игры. Поэтому весь код роста
	-- ниже (_stretchMine/_burstMine) считает от ЭТОЙ константы, а не от 1.
	MineBaseScale = 1.3,

	MineBulgeScale = 1.06,

	-- ШАХТА РАСТЯГИВАЕТСЯ С КАЖДЫМ КЛИКОМ (по прямому запросу). В отличие
	-- от MineBulgeScale выше, который отыгрывает назад сразу, этот
	-- масштаб НАКАПЛИВАЕТСЯ: к третьему попаданию шахта заметно раздута и
	-- выглядит так, будто вот-вот лопнет — что дальше и происходит.
	-- Рост РЕЗКИЙ (по прямому запросу): шахта скачком прибавляет в размере
	-- на каждый клик и тут же чуть оседает — читается как удар изнутри, а
	-- не как плавное надувание.
	MineStretchPerHit = 0.14,
	MineStretchOvershoot = 0.09, -- на сколько проскакивает выше цели в момент удара
	MineStretchSeconds = 0.18,
	-- "Шахта будто лопается" в момент завершения мини-игры: резко
	-- раздувается и тут же схлопывается обратно к MineBaseScale.
	--
	-- MineBurstScale ЗАДАЁТСЯ МНОЖИТЕЛЕМ ОТ MineBaseScale, а не абсолютным
	-- числом. Абсолютное 1.4 было МЕНЬШЕ, чем шахта успевает раздуться
	-- накопительным ростом за 3 удара мини-игры (HitsRequired) даже без
	-- поправки на +30% (1 + 0.14×3 + оverdshoot ≈ 1.51 > 1.4) — то есть
	-- "взрыв" в кульминационный момент на деле СЖИМАЛ шахту, а не раздувал.
	-- С добавлением MineBaseScale = 1.3 разрыв стал ещё заметнее (шахта к
	-- третьему удару уже около 1.72-1.81, а взрыв тянул её вниз до 1.4).
	-- Множитель гарантирует, что взрыв ВСЕГДА больше самого раздутого
	-- состояния перед ним, при любой базе.
	MineBurstScale = 1.5, -- итоговый масштаб = MineBaseScale * MineBurstScale
	MineBurstSeconds = 0.45,

	-- "ПЛЕВОК" ШАХТЫ НА КАЖДУЮ РУДУ (по прямому запросу): пока руда
	-- приседает в двери, шахта чуть поджимается (MineSpitSquash), в момент
	-- вылета резко раздувается (MineSpitScale) и упруго возвращается к
	-- MineBaseScale. Оба числа — МНОЖИТЕЛИ от MineBaseScale.
	-- Руды одного батча вылетают по очереди с шагом MineSpitStaggerSeconds,
	-- чтобы у каждой был свой плевок (см. MineService:_ejectOre/_spitMine).
	MineSpitScale = 1.2,
	MineSpitSquash = 0.94,
	MineSpitSeconds = 0.55,
	MineSpitStaggerSeconds = 0.5,

	-- РУДА НА ВРЕМЯ КАТСЦЕНЫ КРУПНЕЕ (по прямому запросу). Пока идёт
	-- катсцена, камера стоит далеко, и руда нормального размера читалась бы
	-- как несколько пикселей. Поэтому на время выброса каждый кусок
	-- увеличивается, а когда катсцена заканчивается — плавно садится
	-- обратно к 1, уже рядом с игроком.
	-- КАТСЦЕНА С ДУБЛЁРОМ (по прямому запросу). Камера больше НЕ залетает
	-- внутрь шахты: сразу после разговора она встаёт на верхнюю точку, с
	-- которой идёт мини-игра, и оттуда показывает, как в шахту заходят —
	-- а в конце выходят — шахтёр и КЛОН игрока.
	--
	-- Настоящий персонаж при этом не двигается вообще: он становится
	-- невидимым и стоит ровно там, где нажал на разговор, поэтому по
	-- окончании катсцены игрок оказывается на том же месте — никакого
	-- "возврата" не требуется, возвращать нечего.
	--
	-- Идут ПО ОЧЕРЕДИ: сначала оба стоят (ActorIdleSeconds), потом трогается
	-- шахтёр, а клон выходит следом с задержкой ActorStaggerSeconds — так
	-- читается "повёл за собой", а не "двое синхронно поехали".
	ActorIdleSeconds = 0.9,
	ActorStaggerSeconds = 0.8,
	ActorWalkSeconds = 2.2,
	ActorCloneOffset = Vector3.new(-3, 0, 0), -- где клон стоит относительно шахтёра у входа

	-- v14.3: ПУТЬ В ШАХТУ. Шахтёр и клон игрока идут ПО ТОЧКАМ: отходят от
	-- входа, поворачивают направо, проходят, ещё раз направо и заходят в
	-- ENTRY. Точки — детали MinePath1, MinePath2, MinePath3… внутри модели
	-- шахты (сколько положишь — столько и пройдут, по порядку номеров). Нет
	-- ни одной — путь считается сам из чисел ниже (отсчёт от места, где
	-- стоял шахтёр, «вперёд» = куда смотрит шахта).
	ActorWalkSpeed = 9,          -- стадов/сек
	ActorTurnSpeed = 10,         -- насколько резко разворачиваются на поворотах
	ActorFollowGap = 3.2,        -- клон идёт за шахтёром на таком расстоянии
	PathAutoForward = 7,         -- авто-путь: сколько отойти от шахты
	PathAutoSide = 7,            -- …потом вправо
	PathAutoApproach = 5,        -- …потом к точке перед входом
	-- Анимация ходьбы клона (Humanoid игрока). 0 — стандартная Roblox.
	ActorWalkAnimationR15 = 0,
	ActorWalkAnimationR6 = 0,

	-- v14.3: ПОСЛЕ ВЫХОДА руда из шахты не подбирается, пока игрок не
	-- сдвинется с места появления хотя бы на ExitMoveThreshold стадов, и
	-- подбирается только вблизи (DropPickupRadius; с пропуском OreMagnet —
	-- DropPickupRadiusMagnet). Так куча не «магнитится» в игрока сама.
	ExitMoveThreshold = 3,
	DropPickupRadius = 4.5,
	DropPickupRadiusMagnet = 9,

	-- v14.3: КАРТОЧКА РЕДКОСТИ ШАХТЫ после мини-игры — пролетает снизу
	-- вверх экрана с микро-паузой в центре, потом начинается вылет руды.
	-- Свои модели: ReplicatedStorage.Assets.MineRarityCards.<Редкость>
	-- (Common, Uncommon, Rare, Epic, Legendary, Mythic) — см. CHANGELOG.
	RarityCard = {
		Distance = 10,       -- стадов перед камерой (карточка — 3D-объект в мире)
		ScreenWidth = 0.36,  -- ширина карточки, доля экрана
		-- v17: дольше висит в центре и двигается плавнее (вылет с мягким
		-- перелётом, покачивание в центре, замах вниз перед уходом вверх).
		InSeconds = 0.6,     -- вылет снизу до центра
		HoldSeconds = 1.45,  -- «висит» в центре (+ HoldExtra редкости)
		OutSeconds = 0.5,    -- улетает вверх
		SwayDegrees = 7,     -- покачивание в центре (крен/поворот)
		TiltDegrees = 24,    -- наклон: снизу — вниз, сверху — вверх
		-- ЭФФЕКТЫ ПО РЕДКОСТИ (в момент остановки в центре):
		--   Burst — искры; Stars — крупные звёзды; Rays — лучи позади;
		--   Ring — ударная волна; Confetti — конфетти; Shake — тряска камеры;
		--   Flash — вспышка экрана цветом редкости (0..1); Rainbow — рамка
		--   переливается; HoldExtra — насколько дольше висит в центре.
		Effects = {
			Common = { Burst = 10 },
			Uncommon = { Burst = 18, Ring = true },
			Rare = { Burst = 28, Ring = true, Rays = 6, Shake = 0.08 },
			Epic = { Burst = 40, Ring = true, Rays = 8, Stars = true, Shake = 0.14, HoldExtra = 0.1 },
			Legendary = { Burst = 60, Ring = true, Rays = 12, Stars = true, Confetti = 40, Shake = 0.24, Flash = 0.45, HoldExtra = 0.2 },
			Mythic = { Burst = 90, Ring = true, Rays = 16, Stars = true, Confetti = 70, Shake = 0.34, Flash = 0.6, Rainbow = true, HoldExtra = 0.35 },
		},
	},

	-- Выброс руды игроком на Backspace (см. MineService:ThrowOreToGround).
	DropSelfPickupDelay = 4, -- секунд, столько бросивший не может поднять свой кусок
	DropThrowDistance = 7,
	DropThrowSeconds = 0.6,
	DropThrowArcHeight = 6,

	CutsceneOreScale = 2.6,
	CutsceneOreShrinkSeconds = 0.5,

	-- Руда слегка ЛЕВИТИРУЕТ над землёй и покачивается — так она читается
	-- как "добыча", а не как валяющийся камень, и её видно поверх травы.
	OreHoverHeight = 1.6,
	OreHoverBob = 0.35,          -- амплитуда покачивания вверх-вниз, студ
	OreHoverBobSeconds = 2.2,    -- период покачивания

	-- Точка падения руды сдвигается В СТОРОНУ БАНКА от центра участка —
	-- камера на выбросе стоит именно с той стороны, и без сдвига куча
	-- ложилась бы у неё за спиной.
	DropTowardBankStuds = 10, -- больше не используется: руда падает у выхода шахты (см. EjectLand* ниже)

	-- КУДА ПАДАЕТ РУДА: сектор перед дверью шахты (по прямому запросу —
	-- "ближе к выходу шахты, но не совсем близко"). Расстояния — в стадах
	-- от двери, разлёт — в градусах в каждую сторону от направления наружу.
	EjectLandMinDistance = 10,
	EjectLandMaxDistance = 22,
	EjectLandSpreadDegrees = 55,
	-- ...но по умолчанию руда летит К КАМЕРЕ и падает почти перед ней (по
	-- прямому запросу). Gap — сколько стадов от объектива до центра кучи,
	-- Spread — разброс вбок и в глубину. false вернёт сектор у выхода.
	EjectLandInFrontOfCamera = true,
	EjectLandCameraGap = 16,
	EjectLandCameraSpreadSide = 7,
	EjectLandCameraSpreadDepth = 4,
	-- v9: разброс с минимальной дистанцией (ярлыки шансов не слипаются).
	EjectLandMinGap = 4.5,        -- стадов между кусками (по ширине кадра)
	EjectLandDepthWeight = 0.7,   -- по глубине кадра дистанция «весит» меньше
	EjectLandMaxSpreadSide = 16,  -- куча растёт с числом руды, но не шире этого
	EjectLandMaxSpreadDepth = 9,

	-- Тряска куска в момент раскрытия.
	RevealShakeStuds = 0.22,
	RevealShakeSeconds = 0.35,

	-- ШАГ 5: нырок камеры к земле + очередность вылета руды.
	-- По прямому запросу ("по таймингам беда... сначала вылетает первая
	-- руда, потом две секунды ожидание и следующие вылетают, и редкость
	-- проявляется только тогда, когда выявляется следующая руда") —
	-- батчи (1 центральная → пара сбоку → волны по WaveSize) идут строго
	-- ПОСЛЕДОВАТЕЛЬНО с одной и той же паузой BatchGapSeconds между ними,
	-- и каждый батч раскрывается (снимает "чёрную скорлупу") РОВНО в
	-- момент, когда вылетает следующий — см. MineService:_ejectOre.
	CameraDiveSeconds = 0.9,
	BatchGapSeconds = 2,
	WaveSize = 3,
	-- ПО ПРЯМОМУ ЗАПРОСУ ("сильнее раскидывались", "появлялись сто
	-- процентов на земле", "крутились на месте когда выпали", "будто мячи
	-- волейбольные с трейлом") — дуга выше и дальше, разброс намного шире,
	-- полёт чуть дольше (иначе с таким разбросом камни выглядели бы
	-- слишком быстрыми), плюс TrailEjectWidth/EjectSpinAfterLanding ниже.
	EjectArcHeight = 14, -- было 9
	EjectFlightSeconds = 0.85, -- было 0.65

	-- "ПЛЕВОК" ШАХТЫ (по прямому запросу): руда становится крупнее в
	-- момент вылета из шахты, а после — уменьшается обратно, как будто её
	-- выплюнуло. Действует ТОЛЬКО на настоящий вылет из шахты (см. flyOre,
	-- параметр spitPop) — на выброс руки игроком (Backspace) не влияет.
	-- ВЫКЛЮЧЕНО: теперь "плюётся" сама ШАХТА (MineSpit* выше), а руда
	-- летит своим обычным размером. true вернёт старое раздувание руды
	-- поверх плевка шахты.
	EjectOreSpitPop = false,
	EjectSpitPopMultiplier = 1.35, -- во сколько раз крупнее на пике
	EjectSpitPopSeconds = 0.3,     -- сколько длится весь всплеск туда-обратно
	EjectScatterRadius = 20, -- было 10 — разлёт заметно шире
	-- Скорость непрерывного вращения уже приземлившейся руды (рад/сек) —
	-- "крутились на месте когда выпали", см. общий Heartbeat-вращатель в
	-- MineService:Init (крутит всё, что лежит в workspace.MineGroundOre
	-- с атрибутом Landed=true, пока не подобрано).
	EjectSpinAfterLanding = 1.6,
	-- Трейл во время полёта (см. flyOre) — толщина у начала/конца
	-- (Attachment0/1 разнесены по высоте камня) и время жизни хвоста.
	EjectTrailWidth = 0.6,
	EjectTrailLifetime = 0.4,
	-- Пока камень летит — он "заспойлерен": чёрный, без надписи шанса.
	-- Через RevealDelaySeconds ПОСЛЕ приземления ВСЕЙ пачки камера чуть
	-- отъезжает (см. RevealCameraBackOffset) и все камни разом раскрываются
	-- (настоящий цвет/материал + билборд шанса) — см. ТЗ.
	RevealDelaySeconds = 0.35,
	RevealCameraBackOffset = 6,
	RevealTweenSeconds = 0.4,
}

-- ЦВЕТ ВОРОТ ШАХТЫ (MineDoor, см. ТЗ) ПО РЕДКОСТИ САМОЙ ЦЕННОЙ руды в
-- выбитой пачке. Часть MineDoor получает Enum.Material.Neon + этот Color,
-- и КАЖДЫЙ VFX-attachment под MineDoor, чьё имя начинается с "VFX_" + это
-- имя редкости (например "VFX_Legendary"), включается (Enabled = true);
-- все остальные "VFX_*" — выключаются. Так билдер может положить под
-- MineDoor сколько угодно ParticleEmitter/Beam-attachment-ов на каждую
-- редкость, ничего не программируя.
Config.MineDoorRarityColor = {
	Common = Color3.fromRGB(180, 185, 195),
	Uncommon = Color3.fromRGB(80, 220, 120),
	Rare = Color3.fromRGB(70, 140, 255),
	Epic = Color3.fromRGB(190, 90, 255),
	Legendary = Color3.fromRGB(255, 70, 70),
}

--------------------------------------------------------------------------------
-- ОФЛАЙН-ШАХТА: ТЕЛЕЖКА, ЗАБИТАЯ РУДОЙ, ПОКА ИГРОКА НЕ БЫЛО
--
-- ГЛАВНОЕ РЕШЕНИЕ: офлайн даёт РУДУ, А НЕ ДЕНЬГИ. Тележка стоит на своей
-- обычной парковке уже наполненной — но деньги игрок всё равно зарабатывает
-- сам: руду надо довезти до банка, не потеряв её по дороге в PvP. Комбо-
-- множитель тоже считается только при реальной доставке (см. CartService.
-- comboMultiplier). Поэтому эта механика физически НЕ МОЖЕТ работать как
-- второй сейф — она даёт сырьё, а не результат.
--
-- ПОЧЕМУ ПОТОЛОК — РОВНО ОДНА ТЕЛЕЖКА. Шахта очень быстрая: полная тележка
-- набирается за 1.4 мин на T5 и за 4.3 мин на T10 (Capacity × SpawnInterval).
-- Любой накопитель большего размера заполнялся бы за 10-20 минут отсутствия
-- и всегда был бы полным — то есть перестал бы быть таймером вообще. Одна
-- тележка — это честный «подарок за возвращение» на 1-4 минуты игры, и она
-- принципиально не способна сдвинуть экономику (ребёрт стоит 17-110 полных
-- тележек, см. Config.Rebirth).
--
-- Хочешь сделать щедрее — поднимай Rate, а не потолок: потолок и есть то,
-- что защищает баланс.
--------------------------------------------------------------------------------
Config.OfflineCart = {
	Enabled = true,

	-- v20.9: ЧТО ВЫДАЁТСЯ ЗА ОФЛАЙН. "Money" — просто немного денег сразу
	-- на счёт (руда, высыпанная в тележку разом, давала лаг на заходе);
	-- "Ore" — старая схема с рудой в тележке (настройки ниже).
	Mode = "Money",
	-- Деньги = активный доход в минуту (Config.IncomePerMinute по текущим
	-- тирам шахты и тележки, × множитель ребёртов/перков) × минуты офлайна ×
	-- MoneyRate. 0.05 = 5% от активной игры: час отсутствия ≈ 3 минуты
	-- игры, потолок MaxMoneySeconds (6 ч) ≈ 18 минут игры. Сейф подиума
	-- копит отдельно, как и раньше.
	MoneyRate = 0.05,
	MaxMoneySeconds = 6 * 60 * 60,

	-- Скорость шахты, пока игрока нет, в долях от обычной. 0.4 = 40%.
	-- На T5 (1.39 сек/кристалл) полная тележка на 60 мест наберётся за
	-- 60 × 1.39 / 0.4 ≈ 3.5 минуты отсутствия.
	Rate = 0.4,

	-- Меньше этого времени отсутствия офлайн-добыча не начисляется ВООБЩЕ.
	-- Без этого порога перезаход раз в минуту был бы выгоднее, чем игра:
	-- вышел-зашёл — и тележка снова полная.
	MinOfflineSeconds = 300, -- 5 минут

	-- Дальше этого времени накопление не идёт. Формально избыточно (потолок
	-- и так — вместимость тележки), но оставлено явно: если однажды решишь
	-- поднять потолок выше одной тележки, именно это число не даст
	-- вернувшемуся через месяц игроку получить склад руды.
	MaxOfflineSeconds = 12 * 60 * 60,

	-- Какую долю ВМЕСТИМОСТИ тележки максимум может занять офлайн-руда.
	-- 1.0 = тележка полная. Ставь 0.7, если хочешь, чтобы игрок всё равно
	-- постоял у шахты пару секунд перед выездом.
	MaxFillPercent = 1.0,
}

