-- Тир шахты меняет стоимость и внешний вид кристалла. Multiplier задаёт
-- simulator-кривую дохода от $1K на T1 до $650M на T10.
-- ГЛОБАЛЬНЫЙ МАСШТАБ ЭКОНОМИКИ. Раньше базовое значение (1000) в паре с
-- ростом Multiplier по тирам руды (см. ниже) и комбо-множителем тележки
-- (до x260 на 100% заполнении тира 10, см. Config.Cart.ComboThresholds)
-- уводило доход полностью гружёной тележки в АБСУРДНЫЕ числа — тир 10
-- давал 38 ТРИЛЛИОНОВ за рейс. "Очень много денег" перестаёт ощущаться
-- как деньги, когда на экране трейлится 15-значное число.
--
-- 1000 → 10 (÷100) сжимает ВСЮ кривую пропорционально, не трогая сами
-- Multiplier (флейвор "во сколько раз эта руда ценнее угля" остаётся тем
-- же) и не трогая комбо-таблицу — только общий масштаб чисел на экране.
-- Результат по факту полной тележки на 100% заполнении, до Rebirth-бонусов:
--   T1  ≈ $480         (сотни)
--   T3  ≈ $36,000       (десятки тысяч)
--   T5  ≈ $3,750,000     (миллионы, середина прогрессии)
--   T7  ≈ $420,000,000    (сотни миллионов)
--   T10 ≈ $380,250,000,000 (очень много денег — большое, но ещё осмысленное число)
-- ЭКОНОМИКА v3 (ребаланс "цифры слишком большие"): база 1, цены руды —
-- прямо в Multiplier (Coal $2 … Singularity $2000, шаг ~×1.5 на руду).
-- Итог без ребёрт-бонусов: первая тележка ≈ $110, топовая пещера ≈ $250K.
Config.Crystal_BaseValue = 1

-- Points — ОТДЕЛЬНАЯ от денег шкала "ценности" руды для комбо-множителя
-- тележки (см. Config.Cart.ComboThresholds ниже). Специально нелинейная и
-- ускоряющаяся, как и денежный Multiplier, но не обязана с ним совпадать —
-- можно менять "вес" одной руды в комбо, не трогая её цену, и наоборот.
-- Разброс между тиром 1 и тиром 8 НАМЕРЕННО умеренный (не x95, как цена) —
-- иначе при формуле effectiveFill = rawFill × Points/ComboReferencePoints
-- дешёвая руда вообще не набирает ComboMinFill ни при каком заполнении,
-- а дорогая улетает в потолок раньше 60%. Текущий разброс (17..63, ×3.7)
-- откалиброван так, что на 60% заполнения тир 1 даёт x2, тир 8 — ~x35.
--------------------------------------------------------------------------------
-- РУДА v2 — ПОЛНЫЙ РЕДИЗАЙН (см. ТЗ "переписать систему механики сбора руды").
--
-- Раньше: 1 тир шахты = 1 фиксированная руда. Теперь: 15 тиров шахты, у
-- КАЖДОГО тира — окно из 4 доступных руд (скользящее окно по 18-позиционной
-- цепочке ниже): 3 руды "унаследованы" от предыдущего тира, 1 новая
-- добавляется, самая старая (пятая по счёту назад) выходит из пула. Именно
-- так, как описано в ТЗ таблицей тиров (Coal/Copper/Quartz/Amber → ... →
-- Singularity).
--
-- Config.OreChain — мастер-список всех руд по порядку появления (позиция в
-- массиве = порядок "возраста"). Все геймплейные и денежные параметры руды
-- живут здесь ОДИН раз.
--------------------------------------------------------------------------------
Config.OreChain = {
	{ Key = "Coal",        DisplayName = "Coal", Description = "A humble fuel ore that starts every miner's journey.",        Rarity = "Common",    Multiplier = 2,     Color = Color3.fromRGB(90, 90, 95),    Size = 1.00, Points = 17 },
	{ Key = "Copper",      DisplayName = "Copper", Description = "A warm metal ore prized by growing mining camps.",      Rarity = "Common",    Multiplier = 3,     Color = Color3.fromRGB(205, 120, 70),  Size = 1.05, Points = 19 },
	{ Key = "Quartz",      DisplayName = "Quartz", Description = "A clear crystal that catches every stray torchlight.",      Rarity = "Common",    Multiplier = 5,     Color = Color3.fromRGB(225, 225, 235), Size = 1.10, Points = 21 },
	{ Key = "Amber",       DisplayName = "Amber", Description = "Fossilised resin holding secrets older than the mine.",       Rarity = "Common",    Multiplier = 7,    Color = Color3.fromRGB(235, 190, 80),  Size = 1.15, Points = 23 },
	{ Key = "Iron",        DisplayName = "Iron", Description = "The dependable backbone of every serious operation.",        Rarity = "Common",    Multiplier = 10,    Color = Color3.fromRGB(160, 165, 175), Size = 1.20, Points = 25 },
