	{ Key = "Emerald",     DisplayName = "Emerald", Description = "A deep green gem formed under immense pressure.",     Rarity = "Uncommon",  Multiplier = 35,   Color = Color3.fromRGB(70, 225, 130),  Size = 1.38, Points = 35 },
