	{ Key = "Sapphire",    DisplayName = "Sapphire", Description = "A cool blue gem cut from the deepest seams.",    Rarity = "Rare",      Multiplier = 75,   Color = Color3.fromRGB(70, 130, 255),  Size = 1.50, Points = 42 },
	{ Key = "Amethyst",    DisplayName = "Amethyst", Description = "A violet crystal carrying a calm ancient glow.",    Rarity = "Rare",      Multiplier = 115,   Color = Color3.fromRGB(190, 105, 255), Size = 1.56, Points = 47 },
	{ Key = "Obsidian",    DisplayName = "Obsidian", Description = "Volcanic glass with an edge sharper than steel.",    Rarity = "Epic",      Multiplier = 170,  Color = Color3.fromRGB(45, 40, 60),    Size = 1.62, Points = 52 },
	{ Key = "Platinum",    DisplayName = "Platinum", Description = "A rare white metal that resists almost everything.",    Rarity = "Epic",      Multiplier = 260,  Color = Color3.fromRGB(230, 235, 240), Size = 1.68, Points = 57 },
	{ Key = "Mythril",     DisplayName = "Mythril", Description = "A legendary alloy lighter than air and twice as strong.",     Rarity = "Epic",      Multiplier = 390,  Color = Color3.fromRGB(110, 255, 220), Size = 1.74, Points = 63 },
	{ Key = "Voidstone",   DisplayName = "Voidstone", Description = "A dense shard that seems to swallow nearby light.",   Rarity = "Legendary", Multiplier = 580, Color = Color3.fromRGB(70, 25, 100),   Size = 1.80, Points = 70 },
	{ Key = "Starshard",   DisplayName = "Starshard", Description = "A stellar fragment still burning with distant sunlight.",   Rarity = "Legendary", Multiplier = 870, Color = Color3.fromRGB(255, 240, 180), Size = 1.86, Points = 78 },
	{ Key = "Celestium",   DisplayName = "Celestium", Description = "Metal fallen from the sky, humming with cold energy.",   Rarity = "Legendary", Multiplier = 1300, Color = Color3.fromRGB(140, 200, 255), Size = 1.92, Points = 86 },
	{ Key = "Singularity", DisplayName = "Singularity", Description = "A point of impossible mass — the deepest prize of all.", Rarity = "Legendary", Multiplier = 2000, Color = Color3.fromRGB(20, 15, 30),    Size = 2.00, Points = 95 },
}
-- 18 руд в цепочке (ТЗ упоминало то 17, то поимённую таблицу на 18 — берём
-- таблицу как источник истины, она однозначна; если нужно ровно 17, скажи
-- какую руду убрать/слить, это одна строка).
-- v20: «БОЛЬШИЕ ЦИФРЫ» НА ВЕРХНИХ ТИРАХ. Начиная с руды From каждая
-- следующая дороже ещё в Growth раз сверх базовой кривой: последние
-- пещеры приносят миллионы. Цены пещер/тележки/кирки/престижа ниже
-- масштабируются тем же коэффициентом (Config.CaveNumberScale), поэтому
-- ТЕМП игры не меняется — растут только числа.
Config.NumberGrowth = { From = 5, Growth = 1.19 }
local function niceNumber(value)
	if value < 100 then return math.max(1, math.floor(value + 0.5)) end
	local step = 10 ^ (math.floor(math.log10(value)) - 1)
	return math.floor(value / step + 0.5) * step
end
Config.NiceNumber = niceNumber
function Config.OreNumberScale(index)
	local growth = Config.NumberGrowth
	return growth.Growth ^ math.max(0, (tonumber(index) or 1) - growth.From)
end
for index, info in ipairs(Config.OreChain) do
	info.Index = index
	info.BaseMultiplier = info.Multiplier
	info.Multiplier = niceNumber(info.Multiplier * Config.OreNumberScale(index))
	info.CrystalValue = Config.Crystal_BaseValue * info.Multiplier
end

--------------------------------------------------------------------------------
-- ВАРИАЦИИ РУДЫ (по прямому запросу — "у каждой руды есть по 3
-- вариативности, 1/2/3; первая дешевле третьей, вторая дороже первой, но
-- не сильно; это всё будут меши в будущем").
--
-- Вариация — это НЕ отдельная руда: тир/пул/шансы самой руды не меняются
-- (см. Config.RollOreForTier), вариация роллится ОТДЕЛЬНО поверх уже
-- выпавшей руды и лишь домножает цену. Так 18 руд дают 54 визуально
-- разных камня, не раздувая таблицу тиров.
--
-- Множители намеренно близкие (1.0 / 1.25 / 1.6): по ТЗ "вторая дороже
-- первой, но не сильно". Веса — вариация 1 самая частая, 3 самая редкая,
-- чтобы третья ощущалась находкой.
--
-- МЕШИ: когда появятся модели, клади их в ReplicatedStorage/Assets с
-- именем "Crystal_<Ore>_V<N>" (например "Crystal_Iron_V3") — фабрика сама
-- их подхватит, см. PlaceholderFactory.OreCrystal. Пока таких ассетов
-- нет, берётся общий "Crystal_<Ore>", а вариация видна по подписи и
-- размеру камня (SizeScale ниже).
--------------------------------------------------------------------------------
Config.OreVariants = {
	{ Variant = 1, DisplayName = "I",   ValueMultiplier = 1.00, SizeScale = 0.90, Weight = 60 },
	{ Variant = 2, DisplayName = "II",  ValueMultiplier = 1.25, SizeScale = 1.00, Weight = 30 },
	{ Variant = 3, DisplayName = "III", ValueMultiplier = 1.60, SizeScale = 1.12, Weight = 10 },
}

-- Роллит вариацию (1/2/3) для уже выпавшей руды. Возвращает
-- (variantInfo, chanceFraction) — chanceFraction нужен, чтобы честно
-- перемножить его с шансом самой руды в надписи "1/N" над камнем.
function Config.RollOreVariant()
	local total = 0
	for _, variant in Config.OreVariants do
		total += variant.Weight
	end
	local roll = math.random() * total
	local acc = 0
	for _, variant in Config.OreVariants do
		acc += variant.Weight
		if roll <= acc then
			return variant, variant.Weight / total
		end
	end
	local last = Config.OreVariants[#Config.OreVariants]
	return last, last.Weight / total
end

Config.OreByKey = {}
for _, info in Config.OreChain do
	Config.OreByKey[info.Key] = info
end

--------------------------------------------------------------------------------
-- v17: МУСОР. С маленьким шансом вместо руды из шахты, валуна или жеоды
-- выпадает хлам: собачья кость, древние осколки, камень, банка колы,
-- резиновая утка. Стоит копейки или ничего. Ведёт себя как обычная руда
-- (летит в тележку/рюкзак, продаётся), но без мутаций, вариаций и книги
-- коллекции, в плавильню не берётся.
--
-- Chance — шанс, что КОНКРЕТНЫЙ кусок окажется мусором (на каждый кусок
-- отдельно). Value — цена в $ (0 = бесплатно). Weight — как часто этот
-- мусор среди мусора. Своя модель: ReplicatedStorage.Assets.Junk_<Key>
-- (Model с PrimaryPart или Part). Нет модели — простой плейсхолдер.
--------------------------------------------------------------------------------
Config.Junk = {
	Enabled = true,
	Chance = { Mine = 0.03, Boulder = 0.04, Geode = 0.04 },
	Items = {
		{ Key = "Junk_Rock",       DisplayName = "Plain Rock",     Value = 0, Weight = 30, Color = Color3.fromRGB(125, 120, 115), Description = "Just a rock. Truly remarkable." },
		{ Key = "Junk_ColaCan",    DisplayName = "Cola Can",       Value = 1, Weight = 25, Color = Color3.fromRGB(200, 30, 40),   Description = "Empty. Someone was thirsty down here." },
		{ Key = "Junk_DogBone",    DisplayName = "Dog Bone",       Value = 2, Weight = 20, Color = Color3.fromRGB(240, 232, 210), Description = "A good boy buried it here long ago." },
		{ Key = "Junk_AncientShards", DisplayName = "Ancient Shards", Value = 4, Weight = 15, Color = Color3.fromRGB(150, 175, 170), Description = "Broken pottery from a forgotten age." },
		{ Key = "Junk_RubberDuck", DisplayName = "Rubber Duck",    Value = 6, Weight = 10, Color = Color3.fromRGB(255, 215, 40),  Description = "Squeak." },
	},
}
Config.JunkByKey = {}
do
	local total = 0
	for _, item in Config.Junk.Items do total += item.Weight end
	for _, item in Config.Junk.Items do
		-- Поля «как у руды», чтобы весь конвейер руды принимал мусор как есть.
		item.Junk = true
		item.Index = 0 -- «дешевле» любой руды при сортировке
		item.Rarity = "Common"
		item.Multiplier = 0
		item.CrystalValue = item.Value
		item.Points = 0
		item.Size = 1
		item.Chance = item.Weight / math.max(1, total)
		Config.OreByKey[item.Key] = item
		Config.JunkByKey[item.Key] = item
	end
end

function Config.IsJunk(oreKey)
	return oreKey ~= nil and Config.JunkByKey[oreKey] ~= nil
end

-- source: "Mine" | "Boulder" | "Geode". Возвращает запись мусора или nil.
function Config.RollJunk(source)
	local cfg = Config.Junk
	if not (cfg and cfg.Enabled) then return nil end
	local chance = tonumber(cfg.Chance and cfg.Chance[source or "Mine"]) or 0
	if chance <= 0 or math.random() >= chance then return nil end
	local total = 0
	for _, item in cfg.Items do total += item.Weight end
	local roll = math.random() * total
	local acc = 0
	for _, item in cfg.Items do
		acc += item.Weight
		if roll <= acc then return item end
	end
	return cfg.Items[#cfg.Items]
end

--------------------------------------------------------------------------------
-- ПЕЩЕРЫ v3 (ребаланс): 15 пещер (под них уже есть модели Mine_Tier1..15).
-- Раньше ветка шахты кончалась на 9-м тире, и руды 13-18 не выпадали
-- никогда — теперь цепочка пещеры доходит до 15.
--
-- У каждой пещеры окно из 5 руд, сдвиг на 1 руду за пещеру: 4 руды
-- «наследуются» от прошлой пещеры, 1 новая добавляется. Пещера 14 = руды
-- 14..18. Пещера 15 — те же руды, что у 14-й, но с «богатыми» весами
-- (Config.TopCaveWeights): финальная пещера = заметно чаще редкие слоты.
--
-- РЕДКОСТЬ ПО СЛОТУ (выбор Ж2): редкость — это не свойство руды навсегда,
-- а то, насколько она редкая В ТЕКУЩЕЙ ПЕЩЕРЕ. Слот 1 (60%) — Common,
-- слот 5 (0.5%) — Legendary. В любой пещере с первой минуты видны все
-- цвета. Одна и та же руда в следующей пещере «дешевеет» по редкости —
-- это честно: для игрока с пещерой повыше она уже обыденная.
-- Mythic намеренно оставлен мутациям и жеодам.
--------------------------------------------------------------------------------
Config.OreTierWeights = { 60, 28, 9, 2.5, 0.5 }
Config.TopCaveWeights = { 40, 30, 18, 9, 3 } -- только для последней пещеры
Config.SlotRarities = { "Common", "Uncommon", "Rare", "Epic", "Legendary" }

Config.Mine.CaveCount = 15
Config.Mine.WindowStep = 1
-- Сколько руды вылетает за один заход в шахту (по пещере), 5 → 20.
Config.Mine.OreYieldByCave = { 5, 6, 7, 8, 9, 10, 11, 13, 14, 15, 16, 17, 18, 19, 20 }
Config.Mine.OreYieldByTier = { Min = 5, Max = 20 } -- совместимость, не используется

local function caveWindowStart(tier)
	local slots = #Config.OreTierWeights
	return math.min((tier - 1) * Config.Mine.WindowStep + 1, #Config.OreChain - slots + 1)
end

-- Средняя цена вариации (60/30/10 на I/II/III) — нужна для честного
-- «среднего дропа» пещеры (им считаются цены апгрейдов, пассивка, награды).
local variantAverage = 0
do
	local totalWeight = 0
	for _, variant in Config.OreVariants do
		totalWeight += variant.Weight
		variantAverage += variant.ValueMultiplier * variant.Weight
	end
	variantAverage /= math.max(1, totalWeight)
end
Config.OreVariantAverage = variantAverage

Config.MineTiers = {}
for tier = 1, Config.Mine.CaveCount do
	local start = caveWindowStart(tier)
	local windowOres = {}
	for slot = 1, #Config.OreTierWeights do
		windowOres[slot] = Config.OreChain[start + slot - 1]
	end
	local weights = (tier == Config.Mine.CaveCount and Config.TopCaveWeights) or Config.OreTierWeights
	local weightTotal, expected, points, expectedBase = 0, 0, 0, 0
	for slot, weight in weights do
		weightTotal += weight
		expected += windowOres[slot].CrystalValue * weight
		expectedBase += Config.Crystal_BaseValue * (windowOres[slot].BaseMultiplier or windowOres[slot].Multiplier) * weight
		points += windowOres[slot].Points * weight
	end
	local newest = windowOres[#windowOres]
	Config.MineTiers[tier] = {
		Tier = tier,
		Ores = windowOres, -- [1]=Common 60% .. [5]=Legendary 0.5%
		Weights = weights,
		OreYield = Config.Mine.OreYieldByCave[tier] or Config.Mine.OreYieldByCave[#Config.Mine.OreYieldByCave],
		-- СРЕДНЯЯ цена одного куска руды пещеры (с вариациями, без мутаций
		-- и ребёртов). Раньше экономику считали по CrystalValue самой
		-- редкой руды окна — отсюда завышение дохода в 5-13 раз и цены,
		-- которые уходили в отрыв от реального заработка.
		ExpectedValue = expected / weightTotal * variantAverage,
		-- v20: во сколько раз доход пещеры вырос от Config.NumberGrowth.
		NumberScale = expected / math.max(1e-9, expectedBase),
		AveragePoints = points / weightTotal,
		-- Поля ниже — обратная совместимость (витрина тира = самая редкая руда окна).
		DisplayName = newest.DisplayName,
		Description = newest.Description,
		Rarity = Config.SlotRarities[#Config.SlotRarities],
		Multiplier = newest.Multiplier,
		Color = newest.Color,
		Size = newest.Size,
		Points = newest.Points,
		CrystalValue = newest.CrystalValue,
	}
end

-- Редкость руды oreKey в пещере mineTier (выбор Ж2 — по слоту окна).
-- Ниже окна → Common, выше окна → Legendary. Без mineTier — редкость по
-- «родной» пещере руды (где она впервые появляется самым редким слотом).
function Config.OreRarityFor(oreKey, mineTier)
	local ore = Config.OreByKey[oreKey]
	if not ore or ore.Junk then return "Common" end
	local tier = tonumber(mineTier)
	if not tier then
		return ore.Rarity or "Common"
	end
	tier = math.clamp(math.floor(tier), 1, #Config.MineTiers)
	local start = caveWindowStart(tier)
	local slot = ore.Index - start + 1
	if slot < 1 then return Config.SlotRarities[1] end
	if slot > #Config.SlotRarities then return Config.SlotRarities[#Config.SlotRarities] end
	return Config.SlotRarities[slot]
end

-- Статическая «родная» редкость руды (для мест без контекста пещеры):
-- слот, в котором руда стоит в первой пещере, где она появляется.
for _, info in Config.OreChain do
	local firstTier = 1
	for tier = 1, #Config.MineTiers do
		if caveWindowStart(tier) + #Config.OreTierWeights - 1 >= info.Index then
			firstTier = tier
			break
		end
	end
	info.Rarity = Config.OreRarityFor(info.Key, firstTier)
end

--------------------------------------------------------------------------------
-- СРЕДНЯЯ РЕДКОСТЬ ДЛЯ ТИРА (меш входа шахты entry_common/..., см.
-- MineService:_applyEntryMesh). Средневзвешенная по тем же весам и с тем
-- же наклоном удачи, что и настоящий ролл.
--------------------------------------------------------------------------------
Config.RarityOrder = { "Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic" }

local RARITY_INDEX = {}
for index, name in Config.RarityOrder do
	RARITY_INDEX[name] = index
end

local function tiltedWeights(weights, luckBonus)
	local adjusted = {}
	local total = 0
	for slot, weight in ipairs(weights) do
		local w = weight * (1 + luckBonus * (slot - 1))
		adjusted[slot] = w
		total += w
	end
	return adjusted, total
end

function Config.AverageRarityForTier(tier, luckBonus)
	-- v3: при редкости по слоту «средняя редкость» одинакова в любой пещере,
	-- поэтому вход шахты светится по ПРОГРЕССУ: пещеры 1-3 Common, 4-6
	-- Uncommon, 7-9 Rare, 10-12 Epic, 13-15 Legendary. Хорошая мини-игра
	-- (удача ≥ LuckStepThreshold) поднимает свечение на одну ступень.
	tier = math.clamp(math.floor(tonumber(tier) or 1), 1, #Config.MineTiers)
	local bands = #Config.SlotRarities
	local index = math.clamp(math.ceil(tier / #Config.MineTiers * bands), 1, bands)
	if (tonumber(luckBonus) or 0) >= (Config.Mine.EntryLuckStepThreshold or 0.3) then
		index = math.min(index + 1, bands)
	end
	return Config.RarityOrder[index]
end

-- Роллит ОДНУ руду из пула пещеры. Возвращает (oreInfo, trueChance, slot,
-- rarity). trueChance — базовый шанс слота БЕЗ удачи (честная надпись
-- «1/N»). luckBonus (0..0.6) наклоняет веса к редким слотам.
function Config.RollOreForTier(tier, luckBonus)
	local tierInfo = Config.MineTiers[math.clamp(tier or 1, 1, #Config.MineTiers)]
	local weights = tierInfo.Weights
	luckBonus = luckBonus and math.clamp(luckBonus, 0, 0.6) or 0
	local adjusted, total = tiltedWeights(weights, luckBonus)
	local baseTotal = 0
	for _, weight in weights do baseTotal += weight end
	local roll = math.random() * total
	local acc = 0
	for slot, weight in ipairs(adjusted) do
		acc += weight
		if roll <= acc then
			return tierInfo.Ores[slot], weights[slot] / baseTotal, slot, Config.SlotRarities[slot]
		end
	end
	local lastSlot = #tierInfo.Ores
	return tierInfo.Ores[lastSlot], weights[lastSlot] / baseTotal, lastSlot, Config.SlotRarities[lastSlot]
end

--------------------------------------------------------------------------------
-- ТЕЛЕЖКА
-- MaxHealth больше НЕ зеркалит держателя — растёт с тиром САМОЙ тележки:
-- вложился в апгрейд → возишь груз увереннее, дольше выдерживаешь погоню.
-- Тир 1 (100) — как раньше, дальше рост ускоряется вместе с Capacity, но
-- не настолько, чтобы тир 8 кирка (46 урона/сек) переставала быть страшной —
-- даже топовая тележка ловит смертельную серию за ~7-8 сек непрерывного боя.
--------------------------------------------------------------------------------
Config.CartTiers = {
	[1] = { Capacity = 12,  MaxHealth = 100 },
	[2] = { Capacity = 20,  MaxHealth = 125 },
	[3] = { Capacity = 30,  MaxHealth = 150 },
	[4] = { Capacity = 45,  MaxHealth = 180 },
	[5] = { Capacity = 60,  MaxHealth = 215 },
	[6] = { Capacity = 80,  MaxHealth = 255 },
	[7] = { Capacity = 105, MaxHealth = 300 },
	[8] = { Capacity = 140, MaxHealth = 350 },
	[9] = { Capacity = 180, MaxHealth = 410 },
}

-- Сетка слотов внутри тележки (кристаллы видны БЕЗ интерфейса).
Config.CartSlots = {
	Cell = 1.8, -- шаг сетки; должен вмещать самый крупный кристалл
	Cols = 4,   -- по ширине
	Rows = 3,   -- по глубине
}

Config.Cart = {
	-- Дистанция клика/наведения на кусок руды В ТЕЛЕЖКЕ (своей или чужой) —
	-- клиентский raycast в OrePreviewHud.client.lua проверяет её от игрока до
	-- найденной руды.
	OrePreviewMaxDistance = 24,
	-- На этом расстоянии руда из рук автоматически отправляется в свою тележку.
	DepositDistance = 9,

	-- Смещение тележки относительно HumanoidRootPart держателя — X/Z
	-- (позади) берутся отсюда буквально, а вот Y (высота) больше НЕ читается
	-- напрямую: CartService:computeFollowOffset пересчитывает её под
	-- конкретную тележку и игрока (см. Bottom-маркер в PlaceholderFactory.Cart
	-- и Humanoid.HipHeight), чтобы низ тележки не проваливался в землю.
	-- Значение Y здесь оставлено для справки/старого умолчания, реально не используется.
	-- Z увеличен (было 6) — тележка держится чуть дальше от игрока, чтобы
	-- растяжение рук в IK-хвате (CustomCartUI.client.lua) выглядело как
	-- настоящая протянутая рука, а не почти прямая в упор к телу.
	FollowOffset = CFrame.new(0, -2, 8.5),

	-- Пол тележки шире по X (Cols), чем по Z (Rows) — 90° разворачивает
	-- саму тележку так, чтобы к игроку была обращена УЗКАЯ сторона, а не
	-- широкая (см. CartService:Attach, C1 у Motor6D). Не трогает сетку
	-- слотов кристаллов — она в локальных координатах тележки и крутится
	-- вместе с ней как единое целое.
	HolderSideRotation = 90,

	-- ПРЫЖОК С ТЕЛЕЖКОЙ: разрешён, но не часто — после каждого прыжка
	-- Jumping-состояние отключается на этот срок и включается обратно
	-- само (см. CartService:Attach). Не полный запрет — только откат.
	JumpCooldown = 3,

	-- СКОРОСТЬ С ТЕЛЕЖКОЙ (переделано по фидбеку игроков — старое замедление
	-- от % заполнения било по первому впечатлению: уже на половине тележки
	-- терялась треть скорости, на полной — больше 60%, и это ДО того, как
	-- игрок вообще успевал прокачаться. Новичок набирал первую тележку и
	-- буквально плёлся до банка — "that's where players will get bored and
	-- leave the game"). Теперь скорость с тележкой ВООБЩЕ НЕ зависит от
	-- заполнения — фиксированная база (+ геймпасс Speed Boost) плюс
	-- небольшой процент от обычной скорости ходьбы (см. CartSpeedBonusPercent
	-- в Config.Rebirth) — так прокачка (ребёрты/геймпасс) всё ещё немного
	-- влияет на скорость тележки, просто без пугающего резкого замедления.
	BaseWalkSpeed = 14,     -- скорость персонажа без груза (было 16 = стандарт Roblox — по фидбеку ощущалось слишком быстро, слегка снижено)
	-- ТЕЛЕЖКА ВООБЩЕ НЕ ЗАМЕДЛЯЕТ — по прямому запросу. Раньше даже на
	-- максимально ускоренной базе (13.1875) тележка была на ~5.8% медленнее
	-- обычной ходьбы (14) — теперь FixedCartSpeed РОВНО равен BaseWalkSpeed,
	-- разницы не остаётся вообще. Бонус от ребёртов (CartSpeedBonusPercent
	-- в Config.Rebirth) по-прежнему добавляется ПОВЕРХ — это ускорение,
	-- не компенсация замедления, никак не мешает "без замедления".
	FixedCartSpeed = 14,

	-- МЕДЛЕННЫЕ ПОВОРОТЫ: пока тележка в руках, AutoRotate персонажа
	-- выключается — поворотом управляет CartService вручную (limitTurning),
	-- с ограниченной угловой скоростью. Линейно от % заполнения тележки:
	-- MaxTurnRate (пустая, почти как обычно) до MinTurnRate (полная,
	-- разворот тяжёлый и медленный). Тележка приварена к HRP через Motor6D,
	-- поэтому автоматически повторяет уже ограниченный поворот персонажа —
	-- отдельно её саму крутить не нужно.
	-- ПОВОРОТ: даже у пустой тележки есть небольшое "стопорное" сопротивление —
	-- MaxTurnRate заметно ниже, чем "мгновенно", чтобы ощущалось, что в руках
	-- реально что-то есть, а не просто обычный разворот персонажа.
	MaxTurnRate = math.rad(225),  -- град/сек → рад/сек, пустая тележка — уже не мгновенно
	MinTurnRate = math.rad(45),   -- полная тележка — медленный, тяжёлый разворот

	-- ВЗЯТИЕ/ОТПУСКАНИЕ: сколько держать кнопку, чтобы взять свободную
	-- тележку (ProximityPrompt.HoldDuration) и чтобы отпустить ту, что уже
	-- несёшь (клавиша E, см. src/client/CustomCartUI.client.lua).
	PickupHoldDuration = 0, -- было 0.7 — теперь мгновенно (тап, не удержание), брать тележку должно быть без трения
	DropHoldDuration = 2.5,

	-- ДЕСПАВН ПРОСТОЯ: свободную (никто не держит) тележку, которую не
	-- трогали дольше этого времени — не важно, украдена она и брошена
	-- где-то далеко, или просто стоит без дела у самого владельца на базе,
	-- пока он бегает по карте — уничтожает полностью, груз внутри теряется.
	-- Если это была ТЕКУЩАЯ тележка игрока — тут же спавнится пустая новая
	-- на его базе (см. CartService:Start).
	DespawnIdleTime = 45,

	-- РУЧНОЙ РЕСПАВН: физическая кнопка у парковки на базе — всегда
	-- доступна (даже если старую в этот момент несёт вор — та не трогается
	-- вообще, просто перестаёт быть "текущей" и сама сгорит по таймеру
	-- простоя выше), но с кулдауном — иначе кража теряет всякий смысл.
	-- Числовой отсчёт над кнопкой — только в последние
	-- RespawnCountdownThreshold секунд, до этого видно только то, что
	-- кнопка "вдавлена" (см. CartService:SetupRespawnButton).
	ManualRespawnCooldown = 180,
	RespawnCountdownThreshold = 30,

	-- КУДА СТАВИТЬ КНОПКУ ("Spawn New"), если в PlotTemplate НЕТ отдельного
	-- маркера "CartButtonMarker" (см. PLACEHOLDERS_GUIDE.md — можно вместо
	-- этого просто подвинуть мышкой Part с таким именем в Studio, тогда
	-- ButtonOffset ниже вообще не используется, маркер побеждает). Это —
	-- запасной способ ЦИФРАМИ, без захода в модель участка: смещение
	-- (X, Y, Z) от точки парковки тележки (CartSpawnMarker), в studs,
	-- X — вбок, Y — вверх/вниз, Z — вперёд/назад.
	ButtonOffset = Vector3.new(5, -0.5, 0),

	-- Сам поворот применяется к персонажу НЕ прямой записью CFrame (это
	-- конфликтует с внутренней физикой Humanoid и даёт дёрганое движение
	-- при репликации другим игрокам), а через AlignOrientation-констрейнт,
	-- который физический движок плавно интегрирует в общий солвер вместе
	-- с обычным движением персонажа. Торк/отзывчивость специально высокие —
	-- вся "медленность" уже заложена в MaxTurnRate/MinTurnRate выше, здесь
	-- нужно лишь без задержки дотягиваться до уже посчитанной цели.
	TurnMaxTorque = 1e6,
	TurnResponsiveness = 35,

	-- РЕАЛЬНЫЙ ФИЗИЧЕСКИЙ ЛЮФТ: тележка больше НЕ приварена к игроку
	-- абсолютно жёстко — вместо прямого Motor6D она физически ДОГОНЯЕТ
	-- невидимый "идеальный" якорь (тот жёстко висит на игроке ровно так же,
	-- как раньше сама тележка), через AlignPosition/AlignOrientation с
	-- конечной силой/отзывчивостью (см. CartService:Attach). При резком
	-- движении/повороте тележка на мгновение чуть отстаёт — от этого руки
	-- (см. CustomCartUI.client.lua — IK каждый кадр считает честную дистанцию
	-- до точки хвата) визуально чуть растягиваются, и через секунду-другую
	-- само возвращается. FollowResponsiveness — главная ручка "насколько
	-- тянучее" (ниже = дольше самокоррекция), FollowMaxForce/Torque —
	-- потолок силы, важен в основном для того, чтобы держать вес тележки
	-- (не давать ей проседать) — не про "жёсткость" реакции.
	FollowResponsiveness = 4,
	FollowMaxForce = 40000,
	FollowForceGravityMultiplier = 8, -- минимум силы = масса тележки × gravity × это число
	FollowRotationResponsiveness = 30, -- поворот САМОЙ тележки относительно направления игрока остаётся куда более снятым — люфт нужен только по позиции
	FollowRotationMaxTorque = 1e6,

	-- ПОМОЩЬ НА РЕЛЬЕФЕ: при прыжке игрока тележка подпрыгивает следом, а
	-- низкие выступы медленно переползает вверх. Высокая стена остаётся
	-- стеной: верхний луч блокирует карабканье выше ClimbMaxHeight.
	FollowJumpVelocity = 28,
	ClimbMaxHeight = 3.5,
	ClimbSpeed = 5,
	ClimbProbeDistance = 2.75,
	ClimbMinFollowLag = 0.75,
	ClimbProbeInterval = 0.08,
	StuckDistance = 3,
	StuckDelay = 0.35,
	StuckBoostVelocity = 10,
	StuckBoostCooldown = 0.55,
	StuckMaxBoosts = 2,

	-- КОМБО-МНОЖИТЕЛЬ: радужная капсула над тележкой, умножает деньги при
	-- продаже — награда за риск возить ценный груз через опасную дорогу.
	-- Множитель зависит от % заполнения тележки НАПРЯМУЮ, а не от
	-- абсолютных очков — комбо начинается, только когда тележка ощутимо
	-- заполнена, а не с пустой/почти пустой (иначе не показательно и
	-- нечестно к маленьким тележкам). Очки (Config.MineTiers[N].Points)
	-- работают как "ускоритель": ценная руда даёт тот же множитель при
	-- МЕНЬШЕМ % заполнения — effectiveFill = rawFill × (среднийPoints/ComboReferencePoints).
	ComboMinFill = 0.15,               -- ниже этого % заполнения комбо не считается вообще (защита от "1 кусок дорогой руды в пустой телеге = дикий x60")
	-- Фиксированная точка отсчёта (не привязана к конкретному тиру руды) —
	-- откалибрована вместе с MineTiers[N].Points так, чтобы при 60% заполнения
	-- САМАЯ дешёвая руда (тир 1) давала x2 (серебро), а САМАЯ дорогая (тир 8) —
	-- около x35. Прокачка Шахты напрямую поднимает тир добываемой руды → выше
	-- средний Points → выше эффективный буст при той же % заполнения тележки —
	-- это и есть "зависимость от прокачки".
	-- ВАЖНО: тележка физически не может быть заполнена больше 100%
	-- (AddCrystal отказывает при #Crystals >= Capacity, см. CartService) —
	-- поэтому "потолок" каждого тира руды достигается РОВНО на полной
	-- тележке (fill=1.0), effectiveFill в этой точке равен Points/ComboReferencePoints
	-- этого тира. Тиры 1-6 упираются в x50 около 100% заполнения; тиры 7 и 8
	-- НАРОЧНО имеют более высокий буст (k=2.60 и k=3.15) — их потолок выше
	-- (x80 и x120 соответственно), тоже достижимый ровно на полной тележке.
	ComboReferencePoints = 20,
	-- ЭКОНОМИКА v3: комбо зависит ТОЛЬКО от заполнения тележки (не от
	-- «качества» руды) и упирается в x3 на полной тележке. Старое комбо
	-- доходило до x260 и было главным источником гигантских чисел: цена
	-- руды росла в ~2 раза за тир, а комбо поверх — ещё в 1.5-2 раза.
	ComboUseOreQuality = false,
	ComboThresholds = {
		{ Fill = 0.35, Multiplier = 1.25 },
		{ Fill = 0.50, Multiplier = 1.5 },
		{ Fill = 0.70, Multiplier = 2 },
		{ Fill = 0.85, Multiplier = 2.5 },
		{ Fill = 1.00, Multiplier = 3 },
	},
	-- Порог «продал на высоком комбо» для квеста X4Sales (теперь «x3»).
	QuestHighComboMultiplier = 3,

	-- ВИЗУАЛЬНЫЕ СТАДИИ карточки комбо — растёт размер и меняется градиент
	-- по "лигам" множителя: от тусклого дерева при скромном комбо до полной
	-- радуги на самом верху — видно издалека, кого стоит грабить.
	-- Радуга нарочно начинается высоко (x65) — на 100% заполнения её физически
	-- достают только тиры руды 7-8 (потолки x80/x120, см. ComboThresholds выше),
	-- остальным тирам светит максимум "кристалл". Порядок лиг: дерево → серебро
	-- → бронза → золото → кристалл → радуга.
	-- ВИЗУАЛЬНЫЕ СТАДИИ карточки комбо — теперь просто текст "X{число}" без
	-- фона-плашки (см. CartService:findOrBuildComboGui/updateComboLabel):
	-- растёт размер текста и меняется его СПЛОШНОЙ цвет по "лигам" множителя.
	-- Только у самой верхней лиги (Радуга) вместо Color — Gradient: крутящийся
	-- радужный градиент прямо на буквах, как и раньше был на фоне.
	ComboVisualStages = {
		{ -- Дерево — самое скромное комбо, любая руда его достаёт почти сразу
			MinMultiplier = 1.25,
			Size = UDim2.new(3.6, 0, 0.95, 0),
			Color = Color3.fromRGB(181, 136, 99),
		},
		{ -- Серебро
			MinMultiplier = 1.5,
			Size = UDim2.new(4.0, 0, 1.05, 0),
			Color = Color3.fromRGB(225, 225, 235),
		},
		{ -- Бронза
			MinMultiplier = 2,
			Size = UDim2.new(4.4, 0, 1.15, 0),
			Color = Color3.fromRGB(215, 140, 90),
		},
		{ -- Золото
			MinMultiplier = 2.5,
			Size = UDim2.new(4.8, 0, 1.25, 0),
			Color = Color3.fromRGB(255, 205, 60),
		},
		{ -- Кристалл — холодный переливающийся голубой, ощутимо "дороже" золота
			MinMultiplier = 2.75,
			Size = UDim2.new(5.2, 0, 1.35, 0),
			Color = Color3.fromRGB(150, 215, 255),
		},
		{ -- Радуга — вершина, x65+ (реально только тиры руды 7-8 на почти полной тележке)
			MinMultiplier = 3, -- v3: радуга = полная тележка (потолок комбо x3)
			Size = UDim2.new(5.6, 0, 1.45, 0),
			Gradient = ColorSequence.new({
				ColorSequenceKeypoint.new(0.00, Color3.fromRGB(255, 0, 0)),
				ColorSequenceKeypoint.new(0.17, Color3.fromRGB(255, 165, 0)),
				ColorSequenceKeypoint.new(0.34, Color3.fromRGB(255, 255, 0)),
				ColorSequenceKeypoint.new(0.50, Color3.fromRGB(0, 255, 0)),
				ColorSequenceKeypoint.new(0.67, Color3.fromRGB(0, 170, 255)),
				ColorSequenceKeypoint.new(0.84, Color3.fromRGB(140, 0, 255)),
				ColorSequenceKeypoint.new(1.00, Color3.fromRGB(255, 0, 0)),
			}),
		},
	},
}

--------------------------------------------------------------------------------
-- УПАКОВКА ТЕЛЕЖКИ (v12 — полная замена "тележка выдаётся сама + кнопка
-- Spawn New").
--
-- НОВЫЙ ЖИЗНЕННЫЙ ЦИКЛ:
--   1. У нового игрока тележки НЕТ ВООБЩЕ. Первая покупается у НПС прокачки
--      за 0 (карточка "GET CART · FREE", см. UpgradeService — ветка Cart при
--      ещё не купленной тележке).
--   2. Покупка выдаёт не тележку, а УПАКОВКУ — предмет инвентаря
--      (data.Gear["CartPackage"], тот же контейнер, что у динамита/сундуков,
--      поэтому она сразу появляется в рюкзаке и хотбаре).
--   3. Взял упаковку в руки — она поднимается НАД ГОЛОВОЙ ровно как руда
--      (OreCarryPose.client.lua, атрибут HeldCartPackage), и включается
--      ЗЕЛЁНЫЙ/КРАСНЫЙ предпросмотр места постановки (CartPlacement.client.lua).
--   4. Поставил — тележка появляется маленькой и резко "надувается" до
--      нормального размера (CartService:_playInflate).
--   5. Улучшил тележку: стоит в мире — апгрейд применяется ПРЯМО НА НЕЙ (с
--      подсветкой и той же надувной анимацией); не стоит — игрок просто
--      получает новую упаковку (тир читается в момент постановки, поэтому
--      сама упаковка тир не хранит).
--
-- ИНВАРИАНТ: у игрока с купленной тележкой ВСЕГДА ровно одно из двух —
-- тележка в мире ИЛИ упаковка в рюкзаке. Потерял тележку (упала в бездну,
-- сгорела по простою) — упаковка возвращается сама (RestoreDelay), кнопка
-- ручного респавна больше не нужна и удалена.
--------------------------------------------------------------------------------
Config.CartPackage = {
	-- Ключ предмета в data.Gear и в хотбаре (uid "gear:CartPackage").
	GearKey = "CartPackage",
	DisplayName = "Cart Package",
	Icon = "📦",

	-- ПОСТАНОВКА.
	--
	-- v12.1: пороги СИЛЬНО ослаблены. Первая версия проверяла место одним
	-- лучом и раздутой коробкой, из-за чего превью краснело почти везде —
	-- любая кочка, бордюр или стык частей читались как "нет твёрдой
	-- поверхности"/"место занято". Теперь земля замеряется девятью лучами
	-- по площади тележки, а ровность считается по перепаду высот между
	-- ними (см. Shared/CartPlacement.Validate).
	MaxDistance = 34,      -- дальше этого от игрока поставить нельзя (превью краснеет)
	MinDistance = 2.5,     -- ближе — тоже нельзя, иначе тележка встаёт в игрока
	DefaultDistance = 10,  -- куда падает превью, если луч прицела ни во что не попал
	-- v14.3: тележку можно ставить на ЛЮБУЮ поверхность, кроме стен.
	MaxSlope = 70,         -- градусов: круче — это уже стена под центром
	MaxGroundSpread = 0,   -- 0 = перепад высот под тележкой не проверяется
	GroundRayUp = 8,       -- с какой высоты над точкой бьют лучи-замеры
	GroundRayDown = 60,    -- как глубоко они ищут пол
	-- Насколько найденная земля может быть выше/ниже самого игрока. Без
	-- этого прицел в стену над обрывом ставил бы тележку на дно ущелья.
	MaxHeightDifference = 16,
	-- ЗАЗОР ДО ЗЕМЛИ: тележка намеренно встаёт ЧУТЬ ВЫШЕ самой высокой
	-- точки под собой и оседает/выравнивается физикой сама (см.
	-- CartService:_settleUpright). Так неровная поверхность перестаёт быть
	-- помехой: ничего не проваливается в бугор и не встаёт враскоряку.
	-- v14.3: подняли с 0.9 — тележка больше не проваливается в меши/текстуры.
	GroundGap = 1.6,
	-- Коробка проверки "место свободно" УЖЕ габаритов тележки (ужимается на
	-- столько по X и Z) и ниже её (доля высоты). Цель — ловить стены и
	-- столбы, а не бордюр под колёсами.
	ClearanceShrink = 0.8,
	ClearanceHeightFactor = 0.55,
	-- Ставить можно где угодно на проходимой земле. true — только внутри
	-- своего участка (как сундуки, см. GearService:_placeChest).
	OwnPlotOnly = false,
	PlaceCooldown = 0.6,   -- антиспам на серверный remote

	-- ЦВЕТА ПРЕДПРОСМОТРА.
	PreviewOkColor = Color3.fromRGB(70, 255, 120),
	PreviewBadColor = Color3.fromRGB(255, 70, 70),
	PreviewTransparency = 0.55,   -- прозрачность самого призрака тележки
	PreviewFillTransparency = 0.7, -- заливка Highlight поверх призрака

	-- "НАДУВАНИЕ" ПРИ ПОСТАНОВКЕ: тележка появляется крошечной и резко
	-- раздувается до нормального размера с перелётом (Back/Out).
	Inflate = {
		StartScale = 0.12,
		Duration = 0.42,
		Overshoot = 1.12, -- максимум, до которого перелетает, прежде чем осесть в 1
		SettleDuration = 0.16,
	},

	-- ОСЕДАНИЕ ПОСЛЕ ПОСТАНОВКИ. Тележку отпускают на GroundGap выше земли,
	-- и она падает на неё сама. Чтобы на неровности её не завалило набок,
	-- на это время включается временный AlignOrientation, удерживающий её
	-- вертикально (поворот вокруг Y он не трогает).
	Settle = {
		Seconds = 1.6,      -- сколько держим вертикаль после отпускания
		Responsiveness = 35, -- жёсткость удержания (как у Attach)
	},

	-- Потерял тележку (бездна/деспавн по простою) — через столько секунд
	-- упаковка возвращается в рюкзак. Заменяет старую физическую кнопку
	-- "Spawn New" с её 180-секундным кулдауном.
	RestoreDelay = 8,
	-- Угнанную (в руках чужого игрока) тележку упаковка НЕ дублирует —
	-- иначе кража теряет смысл. Возврат произойдёт, только когда та
	-- окончательно исчезнет (деспавн по простою).
}

