-- КИРКА
-- ВАЖНО (Catch-Up): урон по здоровью НЕ растёт с тиром.
-- Тир кирки = внешний вид + СКОЛЬКО кристаллов выбивается за удар + цвет VFX.
--------------------------------------------------------------------------------
-- Cooldown и Damage — теперь ГЛАВНАЯ ось прогрессии кирки (не только
-- выбивание кристаллов): тир 1 бьёт редко и слабо (сильный catch-up для
-- новичков — почти не боец), тир 8 бьёт часто и сильно. Damage считается
-- относительно стандартных 100 HP: тир 1 требует ~13 попаданий, тир 8 —
-- ~3, при этом тир 8 ещё и почти в 7 раз чаще бьёт — разрыв в PvP-силе
