--------------------------------------------------------------------------------
-- 3 НЕЗАВИСИМЫЕ ВЕТКИ ПРОКАЧКИ: Шахта / Тележка / Кирка.
-- У каждой свой пьедестал на участке и свой прогресс (Config хранит только
-- стоимость каждого шага — тир = 1 + число купленных шагов в этой ветке).
--
-- ЗАВИСИМОСТЬ МЕЖДУ ВЕТКАМИ: нельзя купить тир, если он окажется больше
-- чем на 2 тира выше САМОЙ ОТСТАЮЩЕЙ из двух других веток — качать в отрыв
-- можно, но не более чем на 2 шага (см. UpgradeService:_canAfford).
--------------------------------------------------------------------------------
-- ЦЕНЫ ПРОКАЧКИ — пересчитаны (прогрессия была слишком быстрой).
--
-- Единица измерения при калибровке — ПОЛНЫЙ РЕЙС ТЕЛЕЖКИ предыдущего тира
-- (вся тележка доверху × цена руды этого тира × комбо-множитель на 100%
-- заполнения). Было: ~2.4-3.0 рейса на то, чтобы поднять ВСЕ ТРИ ветки на
-- следующий тир — то есть один полный тир окупался буквально за пару
-- ходок, и игрок пролетал всю прогрессию, не успевая ничего почувствовать.
-- Стало: ~4 рейса на самом первом апгрейде (чтобы не отпугнуть новичка) с
-- плавным ростом до ~10 рейсов на девятом (последнем) тире.
--
-- Множители к старым ценам: T2 ×1.6, T3 ×2.6, T4 ×2.8, T5 ×3.0, T6 ×3.2,
-- T7 ×3.4, T8 ×3.6, T9 ×3.8 — то есть чем дальше по игре, тем
-- ощутимее замедление, а самое начало почти не тронуто.
--
-- ВАЖНО про ощущение темпа: игроку НЕ обязательно поднимать все три ветки
-- сразу — Config.BranchMaxGap (2) позволяет увести Шахту на два тира
-- вперёд, а она одна и определяет цену добываемой руды. Так что реальный
-- рост дохода наступает быстрее, чем "суммарная цена трёх веток / рейс".
-- ЦЕНЫ АПГРЕЙДОВ — пересчитаны ПОСЛЕ смены масштаба экономики (см.
-- Config.Crystal_BaseValue выше). База — реальный доход ПОЛНОСТЬЮ гружёной
-- тележки на 100% заполнении с учётом комбо-множителя текущего тира
-- (Config.Cart.ComboThresholds), а не голая цена руды без комбо — так
-- ощущается для игрока, который реально возит полные тележки. Целимся в
-- ~8 таких рейсов на тир Шахты, ~11 на Тележку, ~14 на Кирку — И ЭТО ЧИСЛО
-- ОДИНАКОВО НА ВСЕХ 9 ТИРАХ (раньше росло с 6 до 427 — см. историю
-- переписки/коммит выше по файлу), то есть темп прокачки не ускоряется и
-- не замедляется на всей дистанции игры, только сами суммы растут вместе
-- с экономикой.
-- ЦЕЛЬ ТЕМПА ПРОКАЧКИ (v2, ×3 к предыдущей версии по прямому запросу —
-- "забираю почти весь первый тир пещеры за один раз", хочет дольше
-- фармить). Раньше было 3→8 рейсов на тир — ощущалось слишком быстро.
-- Просто утроил все цены — сам темп (плавный рост от ранних тиров к
-- поздним, единый для всех трёх веток) не менял, поднялась только
-- магнитуда. Специально остановился РОВНО на ×3, не больше: предыдущая
-- версия ДО этого ребаланса (16-28 рейсов на тир, через
-- Config.Economy.ProgressionSlowdown=2.07) прямым текстом называлась
-- скучной — ×3 даёт 9-24 рейса, заметно дольше нынешних 3-8, но всё ещё
-- ощутимо мягче того, от чего уже один раз уходили.
--   тир →  2     3      4       5        6         7          8           9
--   рейсов 9     9      12      15       18        21         24          24
--------------------------------------------------------------------------------
-- ЭКОНОМИКА v3 — ПРОКАЧКА (выбор Б2: пещера главная, тележка и кирка — перки).
--
-- ПЕЩЕРА (ветка Mine) — единственная ось, которая открывает новую руду.
-- 15 пещер. Кап по ребёртам: без ребёрта — пещера 5, каждый ребёрт +2
-- (5 → 7 → 9 → 11 → 13 → 15, до финальной пещеры пять ребёртов).
-- ТЕЛЕЖКА и КИРКА (9 уровней) — перки: не упираются в кап ребёрта и в
-- «отрыв веток» (BranchMaxGap убран), потолок — только длина цепочки.
-- На ребёрте сбрасывается ВСЁ (пещера, тележка, кирка, деньги).
--
-- Калибровка — в «полных тележках» (Config.CartValue: средний дроп, x3
-- комбо) при естественном тире тележки для этой пещеры: шаг пещеры стоит
-- 2 → 2.5 → 3 → … → 9 тележек. Примерное время без пассов: пещера 5
-- (первый ребёрт) ≈ 30 мин + ≈ 6 мин на сам ребёрт; дальше шаги растут
-- плавно — до ~1 часа на пещеру 14→15.
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------
-- ЭКОНОМИКА v4 (темп «быстрый, но не слишком»): цены посчитаны симуляцией
-- (Config.IncomePerMinute × 0.75 — реальный игрок возит не каждую тележку
-- на x3) по целевым минутам на шаг:
--   пещера 2→8: 2.5 … 5.5 мин на шаг, пещера 9→15: 6.5 … 12.5 мин;
--   тележка ≈ 3.5 мин дохода, кирка ≈ 2 мин дохода в момент покупки.
-- Итог без пассов и престижа: пещера 8 (первый престиж) ≈ 45 мин, пещера
-- 15 + всё докачано ≈ 2.3 ч. Цены ФИКСИРОВАННЫЕ (не зависят от игрока).
--------------------------------------------------------------------------------
-- v20: цены пещер +15% (прогрессия была слишком быстрой).
Config.MineChain = {
	{ Tier = 2, Cost = 140 },
	{ Tier = 3, Cost = 330 },
	{ Tier = 4, Cost = 750 },
	{ Tier = 5, Cost = 1500 },
	{ Tier = 6, Cost = 2400 },
	{ Tier = 7, Cost = 5200 },
	{ Tier = 8, Cost = 8600 },
	{ Tier = 9, Cost = 21000 },
	{ Tier = 10, Cost = 39000 },
	{ Tier = 11, Cost = 67000 },
	{ Tier = 12, Cost = 130000 },
	{ Tier = 13, Cost = 220000 },
	{ Tier = 14, Cost = 430000 },
	{ Tier = 15, Cost = 690000 },
}
Config.CartChain = {
	{ Tier = 2, Cost = 330 },
	{ Tier = 3, Cost = 930 },
	{ Tier = 4, Cost = 3100 },
	{ Tier = 5, Cost = 8400 },
	{ Tier = 6, Cost = 14000 },
	{ Tier = 7, Cost = 42000 },
	{ Tier = 8, Cost = 110000 },
	{ Tier = 9, Cost = 240000 },
}
Config.PickaxeChain = {
	{ Tier = 2, Cost = 200 },
	{ Tier = 3, Cost = 640 },
	{ Tier = 4, Cost = 1800 },
	{ Tier = 5, Cost = 5400 },
	{ Tier = 6, Cost = 9100 },
	{ Tier = 7, Cost = 24000 },
	{ Tier = 8, Cost = 64000 },
	{ Tier = 9, Cost = 140000 },
}
-- v20: цены — в масштабе дохода пещеры, где их покупают (Config.NumberGrowth):
-- пещеру N оплачивает доход пещеры N-1, тележку/кирку тира T — доход
-- пещеры, для которой этот тир «родной».
function Config.CaveNumberScale(cave)
	local info = Config.MineTiers[math.clamp(math.floor(tonumber(cave) or 1), 1, #Config.MineTiers)]
	return info and info.NumberScale or 1
end
local function caveForNineTierLocal(tier)
	return math.clamp(1 + math.floor((tier - 1) * (#Config.MineTiers - 1) / 8 + 0.5), 1, #Config.MineTiers)
end
-- v20.2: РАСТЯЖКА ПОЗДНЕЙ ИГРЫ (по данным DevForum: первые ~45 мин не
-- трогаем — быстрые награды и первый престиж держат новичка; конец раньше
-- проходился за 1–2 вечера). Множитель цены по пещере; плавный, без скачка.
-- Первое прохождение до пещеры 15 ≈ 3.5 ч активной игры.
Config.LateGameStretch = { [9] = 1.35, [10] = 1.5, [11] = 1.65, [12] = 1.75, [13] = 1.75, [14] = 1.75, [15] = 1.75 }
local function stretchFor(cave)
	return Config.LateGameStretch[cave] or 1
end
for _, entry in Config.MineChain do
	entry.BaseCost = entry.Cost
	entry.Cost = niceNumber(entry.Cost * Config.CaveNumberScale(entry.Tier - 1) * stretchFor(entry.Tier))
end
for _, chain in { Config.CartChain, Config.PickaxeChain } do
	for _, entry in chain do
		entry.BaseCost = entry.Cost
		local cave = caveForNineTierLocal(entry.Tier)
		entry.Cost = niceNumber(entry.Cost * Config.CaveNumberScale(cave) * stretchFor(cave))
	end
end

-- v3: отрыв веток больше не ограничивается (Б2). Оставлено числом, чтобы
-- старый код, если где-то читает поле, не падал на nil.
Config.BranchMaxGap = math.huge
-- Какие ветки упираются в кап ребёрта. Перки (тележка, кирка) — нет.
Config.TierCappedBranches = { Mine = true }

-- ДОХОД С ПОЛНОЙ ТЕЛЕЖКИ (средний дроп × вместимость × максимальное комбо),
-- без ребёртов/пассов. Единая «линейка» для цен, наград, пассивки, паков.
function Config.CartValue(mineTier, cartTier)
	local mine = Config.MineTiers[math.clamp(math.floor(tonumber(mineTier) or 1), 1, #Config.MineTiers)]
	local cart = Config.CartTiers[math.clamp(math.floor(tonumber(cartTier) or 1), 1, #Config.CartTiers)]
	if not (mine and cart) then return 0 end
	local thresholds = Config.Cart.ComboThresholds
	local maxCombo = thresholds[#thresholds] and thresholds[#thresholds].Multiplier or 1
	return mine.ExpectedValue * cart.Capacity * maxCombo
end

-- Примерная длительность рейса (минуты): заходы в шахту до полной тележки + дорога.
Config.Economy_TripSecondsPerExpedition = 25
Config.Economy_TripSecondsOverhead = 30
function Config.TripMinutes(mineTier, cartTier)
	local mine = Config.MineTiers[math.clamp(math.floor(tonumber(mineTier) or 1), 1, #Config.MineTiers)]
	local cart = Config.CartTiers[math.clamp(math.floor(tonumber(cartTier) or 1), 1, #Config.CartTiers)]
	if not (mine and cart) then return 2 end
	local expeditions = math.ceil(cart.Capacity / math.max(1, mine.OreYield))
	return (expeditions * Config.Economy_TripSecondsPerExpedition + Config.Economy_TripSecondsOverhead) / 60
end

-- Активный доход в минуту (без ребёртов/пассов).
function Config.IncomePerMinute(mineTier, cartTier)
	return Config.CartValue(mineTier, cartTier) / math.max(0.1, Config.TripMinutes(mineTier, cartTier))
end

