-- PVP
-- Урон одинаков для всех (Catch-Up: богатый — цель, а не угроза).
--------------------------------------------------------------------------------
Config.Combat = {
	KnockoutMin = 1, -- минимум кристаллов за удар (доля/максимум — в PickaxeTiers)

	-- Жёсткий потолок на кол-во руды, вылетающей ИЗ ТЕЛЕЖКИ за ОДИН удар —
	-- НЕЗАВИСИМО от тира кирки атакующего (у топовых тиров KnockoutMax в
	-- PickaxeTiers доходит до 18 — без этого потолка один удар мог вынести
	-- почти всю телегу разом). Руки жертвы (HandCarryService) этот потолок
	-- не трогает — там свой отдельный knockoutMax по тому же тиру.
	CartKnockoutMaxPerHit = 5,

	-- ХИТБОКС УДАРА: большой прямоугольный объём ВОКРУГ атакующего
	-- (центр совпадает с HumanoidRootPart), поэтому прежний охват сохраняется
	-- равномерно спереди, сбоку и сзади.
	-- Это ЖЕ САМАЯ геометрия, что рисует debugDrawHitbox — больше нет
	-- расхождения между "визуальным ориентиром" и реальным попаданием.
	-- Растёт вместе с тиром кирки (Config.PickaxeTiers[tier].Scale), как и
	-- сама модель кирки (см. PlaceholderFactory.Pickaxe).
	HitboxSize = Vector3.new(15.5, 15.5, 15.5),
	HitboxForwardOffset = 0,
	HitboxActiveDuration = 0.02, -- хитбокс следует за атакующим ещё 20 мс
	SwingAnimationDuration = 1.9, -- полный замах: прежние 0.9 сек + 1 сек
	SwingReturnFadeTime = 0.22, -- v17: плавнее возврат из замаха в idle-позу (было 0.14)
	MaxPingCompensation = 0.15, -- учитываем не больше 150 мс, чтобы задержку нельзя было абьюзить
	MaxPingHitboxPadding = 2.5, -- максимальное расширение X/Z на высокой задержке

	-- МИКРО-СТАН: жертва на мгновение теряет скорость при попадании (см.
	-- CombatService:ApplyHit) — даёт атакующему реальное окно, а не
	-- мгновенный разворот жертвы обратно за выбитой рудой. Сопровождается
	-- лёгкой тряской на месте (см. StunShakeAmplitude ниже).
	MicroStunDuration = 1.5,

	-- ТРЯСКА ПРИ СТАНЕ: едва заметное дрожание персонажа на месте (не
	-- перемещение) на всё время микро-стана — чисто визуальная обратная
	-- связь "тебя оглушили", амплитуда нарочно крошечная.
	StunShakeAmplitude = 0.18, -- студы, в каждую сторону от текущей позиции
	StunShakeInterval = 0.05,  -- сек между "рывками" тряски

	-- ВЫБИТИЕ РУДЫ: гарантированно ОТ тележки/жертвы по радиусу (не
	-- случайный разброс) — физически не может приземлиться обратно внутрь
	-- тележки. На время полёта у выбитого кристалла отключена коллизия с
	-- источником (тележкой или самим игроком, см. CrystalService:MakeLoose),
	-- иначе застревал в её геометрии на едущей тележке.
	KnockoutEjectUpSpeed = NumberRange.new(18, 28),
	KnockoutEjectOutSpeed = NumberRange.new(14, 22), -- горизонтально, строго по радиусу наружу
	KnockoutEjectNoCollideTime = 0.6,

	-- РЕАЛЬНЫЙ CATCH-UP: раньше тир кирки давал разрыв не только по урону,
	-- но и по ЧАСТОТЕ выбития руды (через общий Cooldown замаха) — топ-тир
	-- фармил новичка кратно быстрее по всем трём осям сразу. Теперь выбитие
	-- руды (и из тележки, И из рук) ограничено ОБЩИМ кулдауном на САМУ
	-- ЖЕРТВУ, не зависящим от тира кирки атакующего: ЭТОГО игрока нельзя
	-- ограбить чаще раза в KnockoutCooldown секунд, даже если бьёт другой
	-- атакующий следом. HP-урон + микро-стан применяются КАЖДЫМ удачным
	-- ударом всегда, вне зависимости от этого кулдауна — тир кирки по-прежнему
	-- полностью решает, как быстро и часто прилетает урон (страх перед
	-- прокачанным противником никуда не делся), просто больше не решает,
	-- как часто можно физически обчищать карман.
	KnockoutCooldown = 7.5,

	-- БЕЗОПАСНЫЕ ЗОНЫ: своя база (весь PlotPad — см. PlotService) и зона
	-- сдачи руды в банке (SellZone — см. WorldService) НЕ являются PvP-зоной.
	-- Работает как позиционная проверка ЖЕРТВЫ (и тела, и тележки отдельно —
	-- см. findVictim/consider) — правило зоны, а не привязка к владельцу:
	-- защищён любой, кто физически стоит внутри, будь то хозяин базы или
	-- случайно забежавший чужак. Атаковать НАРУЖУ из зоны по-прежнему можно —
	-- защита только от того, чтобы самому стать целью. YPadding — запас по
	-- высоте поверх плоского Part зоны (иначе обычный прыжок/неровность
	-- рельефа технически "выводил" бы игрока за пределы зоны по Y).
	SafeZoneYPadding = 50,

	-- VFX-плейсхолдер на месте удара киркой (свой ассет "PickaxeHitVFX" из
	-- Assets — заменишь позже, см. PlaceholderFactory) — сколько живёт перед
	-- автоматическим удалением.
	HitVfxDuration = 0.8,
}

--------------------------------------------------------------------------------
-- PVP v2 — ШКАЛА ОГЛУШЕНИЯ + РАГДОЛЛ (см. CombatService, StaggerFX.client.lua,
-- shared/CombatUiBuilder.lua, tools/BuildAllUI.lua).
--
-- Удар киркой по игроку больше НЕ снимает HP и не бьёт по тележке в руках —
-- он заполняет шкалу оглушения над головой жертвы. Полная шкала → рагдолл
-- на RagdollSeconds, жертву отбрасывает, вылетает РОВНО 1 руда (самая
-- дорогая: сначала из рук, потом из тележки). Потом — неуязвимость.
-- Встречные удары в пределах ClashWindow = ПАРИРОВАНИЕ: оба отлетают,
-- шкала не растёт (очко, которое успел набить соперник, возвращается).
--------------------------------------------------------------------------------
Config.Stagger = {
	Enabled = true,
	PlayerHitsDealDamage = false, -- true вернёт старый урон по HP/тележке поверх шкалы

	-- Сколько ударов нужно на полную шкалу — по ТИРУ КИРКИ атакующего.
	HitsByPickaxeTier = { 4, 4, 3, 3, 3, 3, 2, 2, 2 },
	-- Пасс DoubleDamage ускоряет заполнение, DoubleHealth жертвы — замедляет
	-- (вместо урона/здоровья, чтобы купленные пассы не потеряли смысл).
	DoubleDamageProgressMultiplier = 1.34,
	DoubleHealthProgressMultiplier = 0.75,

	Pips = 4,                 -- сколько делений рисует шкала (заполнение дробное)
	DecayDelay = 4,           -- сек без ударов, после которых шкала начинает спадать
	DecayPerSecond = 0.35,    -- доля шкалы в секунду при спаде

	RagdollSeconds = 3, -- v9: было 2.2
	ImmunitySeconds = 3,      -- после подъёма: удары не заполняют шкалу
	KnockbackSpeed = 42,      -- горизонтальный отлёт при рагдолле
	KnockbackUp = 30,

	DropCount = 1,            -- сколько руды вылетает при рагдолле

	-- ПАРИРОВАНИЕ (только встречные удары, отдельной кнопки блока нет).
	ClashWindow = 0.3,        -- оба замахнулись друг на друга в пределах этого окна
	ClashFacingDot = 0.2,     -- «смотрит на соперника» (скалярное произведение)
	ClashKnockback = 30,
	ClashKnockUp = 14,

	-- НАГРАДА ЗА ГОЛОВУ: у игрока с загруженной тележкой над головой
	-- появляется компактный значок 💰$X. Кто уронит его в рагдолл — получает
	-- X (деньги из воздуха, у жертвы сверх 1 руды ничего не списывается).
	-- Выплачивается ОДИН раз, пока тележка снова не опустеет ниже порога.
	BountyEnabled = true,
	BountyMinFill = 0.7,      -- доля заполнения тележки, с которой объявляется награда
	BountyShare = 0.15,       -- награда = доля текущей стоимости тележки (с комбо)
	BountyRefresh = 1,        -- сек, как часто пересчитывается значок

	-- КОМБО-СЧЁТЧИК атакующего (чисто визуальный).
	ComboWindow = 3,          -- сек между попаданиями, чтобы серия не прервалась

	-- Шаблоны интерфейса (tools/BuildAllUI.lua → StarterGui/CombatUi).
	UiVersion = 1,
	BillboardMaxDistance = 90,
	BillboardHeight = 3.1,
}

--------------------------------------------------------------------------------
-- ЗАЩИТА: временная неуязвимость от атак — кнопка на экране (рядом с
-- кнопкой "Заспавить тележку"). Защищённого нельзя атаковать вообще
-- (findVictim в CombatService его пропускает), но если он САМ атакует
-- кого-то — щит тут же спадает (наказание за агрессивное использование,
-- честная "передышка", а не бесплатная неуязвимость для охоты на других).
--------------------------------------------------------------------------------
Config.Protection = {
	FreeDuration = 30,  -- сек защиты бесплатно
	FreeCooldown = 180, -- сек до следующей бесплатной активации

	-- Разовая защита новичку при самом первом заходе (см. DataService:LoadProfile) —
	-- покрывает прохождение гайда и первые пару апгрейдов шахты, чтобы не
	-- умереть/не быть ограбленным раньше, чем разберётся в игре. НЕ
	-- складывается по кругу — активируется один раз при первом заходе.
	NewbieDuration = 300,

	-- Платное продление — требует настоящего Developer Product в Roblox
	-- (создаётся вручную в Studio/Creator Dashboard, см. README). ID = 0 —
	-- продукт ещё не создан, кнопка покупки будет неактивна/предупредит.
	-- Разовая покупка (Developer Product), НЕ навсегда — в отличие от
	-- геймпасса GoldenShield (Config.GamePasses.GoldenShield) ниже, который
	-- меняет саму БАЗОВУЮ бесплатную защиту навсегда. Эти два эффекта
	-- складываются: владелец GoldenShield тоже может докупить +80 сек сверху.
	PaidDuration = 80,   -- сек, которые добавляет платное продление
	PaidProductId = 3711468020,
	PriceRobux = 9, -- v10: «щит сейчас» — дешёвая импульсная покупка

	-- Единый зелёный цвет щита — им же красится и VFX над тележкой, и
	-- обводка (Highlight) игрока/тележки, и индикатор на кнопке в UI.
	Color = Color3.fromRGB(120, 255, 150),
	-- На какой высоте над ГОЛОВОЙ ДЕРЖАТЕЛЯ висит VFX щита (см.
	-- CombatService — приварен к Head, едет вместе с персонажем, не с
	-- тележкой). Меньше, чем раньше (было 7 — рассчитано на то, чтобы
	-- перекрыть всю тележку сверху; над головой столько не нужно).
	VfxHeight = 3,
}

--------------------------------------------------------------------------------
-- МОНЕТИЗАЦИЯ
-- Все Id — плейсхолдеры (0). Создаёшь Game Pass/Developer Product в Creator
-- Dashboard → вписываешь сюда реальный Id → дальше ничего в коде трогать не
-- нужно (MonetizationService сам подхватит). Пока Id = 0 — эффект просто
-- никому не выдаётся (ownership-чек на Id=0 всегда false), игра не падает.
