-- v3: сумма денежного пака/стартового пака для игрока с данными тирами.
-- rebirthMultiplier — множитель цены руды от ребёртов (DataService:GetCrystalMultiplier).
function Config.MoneyPackAmount(pack, mineTier, cartTier, rebirthMultiplier)
	if type(pack) ~= "table" then return 0 end
	local floorAmount = tonumber(pack.Amount or pack.Money) or 0
	local minutes = tonumber(pack.Minutes) or 0
	if minutes <= 0 or not Config.IncomePerMinute then return floorAmount end
	local byIncome = minutes * Config.IncomePerMinute(mineTier, cartTier) * (tonumber(rebirthMultiplier) or 1)
	return math.floor(math.max(floorAmount, byIncome) + 0.5)
end

--------------------------------------------------------------------------------
-- РЕБЁРТ
-- НПС стоит на КАЖДОМ участке (не один общий у банка). Доступен, когда
-- ВСЕ 3 ветки прокачки этого игрока достигли текущего rebirth-cap (до T10).
-- Сброс всех трёх веток за постоянный множитель цены кристаллов.
--------------------------------------------------------------------------------
Config.Rebirth = {
	MultiplierPerRebirth = 0, -- v8: престиж больше не даёт множителей — только очки перков (Config.Prestige)
	SpeedBonusPerRebirth = 0, -- v8: скорость теперь перк Swift Feet
	SpeedBonusPerRebirthLegacy = 1.03125, -- каждый ребёрт: +1.03125 к WalkSpeed персонажа (на 50% меньше текущего бонуса), полностью применяется только без тележки
	CartSpeedBonusPercent = 0.05, -- с тележкой в руках — вместо полного плоского бонуса ребёртов, только 5% от обычной (без тележки) скорости ходьбы — иначе с полной тележкой набегало слишком много скорости
	ResetMoney = true,          -- ребёрт обнуляет и деньги (иначе он почти бесплатен)

	-- ТИР-КАП ОТ РЕБЁРТОВ: без единого ребёрта потолок тира — BaseTierCap
	-- (не физический максимум 10) во ВСЕХ 3 ветках. Каждый ребёрт поднимает
	-- потолок на TierCapPerRebirth, вплоть до MaxTierCap (= реальный предел
	-- цепочек, 9). Чтобы дойти до T9, нужно четыре rebirth при базе T5.
	-- v3: кап действует только на ПЕЩЕРУ (Config.TierCappedBranches). Первый
	-- ребёрт — после пещеры 5 (~35 мин игры), каждый ребёрт +2 пещеры.
	BaseTierCap = 15, -- v8: лимитов на пещеру нет (престиж — с Config.Prestige.MinCave)
	TierCapPerRebirth = 0,
	MaxTierCap = 15, -- v3: = число пещер (Config.MineChain + 1). Слайм больше не гейт ребёрта, так что его MaxLevel (9) с этим не связан.

	-- Денежная стоимость самого ребёрта — СВЕРХ того, что уже потрачено на
	-- прокачку до текущего потолка (тот прогресс так и так сбрасывается).
	-- Растёт геометрически с каждым следующим ребёртом.
	-- ЦЕНА РЕБЁРТА — тоже пересчитана, и здесь разрыв был самым диким:
	-- при старых 150M первый ребёрт стоил 0.4 ПОЛНОЙ ТЕЛЕЖКИ на тир-капе
	-- T5 (payout ~375M), то есть фактически выдавался бесплатно вместе с
	-- любой случайной ходкой. Даже шестой ребёрт стоил всего ~2 рейса.
	-- Теперь база 3B = ровно 8 полных рейсов на T5, а рост 10 (вместо 12)
	-- держит следующие ребёрты в коридоре 7-11 рейсов, вместо того чтобы
	-- сначала отставать от дохода, а потом резко улетать вперёд.
	-- ЦЕНА РЕБЁРТА пересчитана вместе с общей сменой масштаба экономики
	-- (см. Config.Crystal_BaseValue выше, 1000→10, тот же ÷100). Была
	-- откалибрована как "8 полных тележек на T5" под старую шкалу
	-- (3B ÷ 375M-payout); теперь то же соотношение (8 рейсов) на НОВЫЙ
	-- T5-payout (3.75M): 8 × 3,750,000 = 30,000,000. Рост (CostGrowth)
	-- не трогаем — это коэффициент, а не абсолютная сумма.
	-- v3: ≈3 полные тележки на пещере-капе; рост x3.4 = рост дохода за +2 пещеры.
	CostBase = 4100,
	CostGrowth = 3.4,
	-- v3: уровень слайма больше НЕ условие ребёрта — только бонус к продаже.
	-- v3: для ребёрта нужна только пещера на капе (перки можно не докачивать).
	RequireOnlyCappedBranches = true,

	-- РОСТ ЦЕНЫ ПОСЛЕ ТОГО, КАК ТИР-КАП УПЁРСЯ В MaxTierCap.
	--
	-- Зачем отдельное число: пока каждый ребёрт поднимает потолок тира на
	-- +1, доход игрока растёт примерно в 10 раз за ребёрт (следующий тир
	-- руды дороже примерно во столько же) — и CostGrowth = 10 ровно за ним
	-- поспевает. Но как только потолок дошёл до MaxTierCap (это происходит
	-- на ребёрте MaxTierCap - BaseTierCap = 4), новых тиров больше нет, и
	-- доход дальше растёт ТОЛЬКО за счёт MultiplierPerRebirth, то есть
	-- ЛИНЕЙНО (+50% от базы за ребёрт: x3.0 → x3.5 → x4.0 ...). Цена же
	-- продолжала расти геометрически ×10 — и разрыв мгновенно становился
	-- непроходимым (цифры ниже — из истории тюнинга ЕЩЁ ПРИ MaxTierCap=10,
	-- сам вывод/1.30 не поменялись со снижением потолка до 9): по расчёту
	-- ребёрт №7 стоил ~43 полных рейса, №8 — уже ~380. Это не "сложно",
	-- это глухая стена, за которой игра кончается.
	--
	-- 1.30 подобрано чуть выше реального прироста дохода на этом участке
	-- (он около +9..17% за ребёрт), поэтому каждый следующий ребёрт всё
	-- равно ощутимо дороже предыдущего — прогрессия продолжает замедляться,
	-- как и просили, — но остаётся проходимой сколько угодно долго
	-- (≈5 → 6 → 7 → 8 → 10 рейсов и так далее плавно вверх).
	LateCostGrowth = 1.30,
}

