-- РУДА В РУКАХ (без тележки)
-- Выбитые в PvP кристаллы (см. CombatService:_swing → CrystalService:MakeLoose)
-- можно подобрать не только в тележку, но и голыми руками — способ для тех,
-- кто не хочет угонять/тащить целую тележку. Компромисс "мало, но надёжно":
--   • Вместимость зависит ТОЛЬКО от тира кирки (растёт с прокачкой).
--   • НЕ выбивается повторно в PvP (см. HandCarryService) — но роняется
--     на землю при смерти держателя, как и содержимое тележки.
--   • Продаётся в той же зоне банка, что и тележка, но БЕЗ её
--     комбо-множителя — тележка остаётся более выгодным, но рискованным путём.
--------------------------------------------------------------------------------
Config.HandCarry = {
	-- Максимум кусков руды в руках по тиру кирки (индекс = тир 1..8).
	-- Растёт вместе с прокачкой кирки, но упирается в потолок на тире 5 —
	-- дальше кирка продолжает расти в бою (урон/кулдаун), не в переноске.
	CapacityByPickaxeTier = { 2, 4, 6, 8, 10, 10, 10, 10, 10, 10 },

	-- ЗАМЕДЛЕНИЕ (отдельно от замедления тележки, см. Config.Cart) —
	-- линейно за каждый кусок на горбу, независимо от того, несёт ли игрок
	-- ещё и тележку одновременно (эффекты перемножаются, см. CartService).
	SlowdownPerItem = 0.055, -- ~5.5% скорости за штуку
	MaxSlowdown = 0.5,       -- потолок — даже с полными руками не встаёт колом
	ReturnToOwnerPerHit = 1, -- столько украденных кусков возвращается в тележку владельца за удар по вору
	-- Продажа руки БЕЗ комбо тележки, ЗАТО ворованный кусок (OwnerUserId
	-- принадлежит кому-то другому, см. HandCarryService:SellOne) продаётся
	-- с этим множителем — риск удачной кражи должен окупаться, а не
	-- обесцениваться до голой базовой цены. На СВОЮ переполненную руду (не
	-- украдена ни у кого) множитель не действует — руки для неё остаются
	-- осознанно слабее полной тележки, это не баг, а мотивация прокачивать
	-- вместимость.
	StolenOreMultiplier = 5,
}

