-- МУТАЦИИ РУДЫ (см. src/server/Services/CrystalService.lua:Create) — по
-- образцу "Grow a Garden": редкий шанс при добыче (роллится в момент захода
-- куска руды в тележку, без предупреждения/подсветки заранее — сюрприз).
-- Независимые роллы — мутации МОГУТ комбинироваться на одном куске
-- (Multiplier'ы перемножаются между собой и с обычной ценой руды).
-- Порядок ниже используется и для роллов, и для сортировки в чат-сообщении.
--------------------------------------------------------------------------------
Config.Mutations = {
	-- ПОРЯДОК = ОТ ЧАСТЫХ К РЕДКИМ. На него опираются сразу три вещи:
	-- MutationRoll.Roll идёт по нему при броске, объявление в чат берёт
	-- ПОСЛЕДНЮЮ выпавшую как "самую редкую" (см. CrystalService), а книга
	-- коллекции рисует ячейки в этом же порядке.
	Order = {
		"Mossy", "Rusty", "Cracked", "Frozen", "Soaked", "Tiny", "Toxic", "Gigantic",
		"Void", "Electric", "Molten", "Sanguine", "Golden", "Radiant", "Glitched",
		"Prismatic", "Celestial", "Eclipsed",
	},

	-- ВЗАИМОИСКЛЮЧАЮЩИЕ ГРУППЫ: из одной группы выпадает максимум одна
	-- мутация. Пока нужна только для размера — руда не может быть
	-- одновременно гигантской и крошечной. Без группы результат зависел бы
	-- от того, какой Scale применился последним, то есть от порядка в Order,
	-- а множители при этом перемножились бы оба.
	ExclusiveGroups = {
		Gigantic = "Size",
		Tiny = "Size",
	},

	-- УДАЧА ОТ ПРОГРЕССА. Прибавка ОТНОСИТЕЛЬНАЯ (см. MutationRoll.
	-- EffectiveChance): при luck = 0.5 шанс становится в полтора раза выше
	-- базового. Работает только для мутаций с ScalesWithLuck = true, то есть
	-- для редких — иначе Mossy со своими 12% забил бы весь пул.
	--
	-- На 10 ребёртах и 10 тире шахты: 10*0.04 + 9*0.015 = 0.535, то есть
	-- +53.5% к базовому шансу. Celestial с 0.30% поднимется до 0.46%.
	LuckBonus = {
		PerRebirth = 0, -- v8: удача — перк Luck/Mutations
		PerMineTier = 0.015,
		MaxTotal = 1.5, -- жёсткий потолок: шанс не вырастет больше чем в 2.5 раза
	},

	-- ПОТОЛОК МУТАЦИИ ДЛЯ ПАССИВНОГО ДОХОДА. Множитель мутации применяется и
	-- к установленному в коллекции кристаллу (см. PassiveIncomeService), но
	-- НЕ целиком: Celestial со своими x15 на Titanheart дал бы 840 млрд/мин,
	-- а это 25% всего Config.Economy.MaxCurrency за одну суточную оффлайн-
	-- выплату. При потолке 3.0 получается около 5% — заметная награда, но
	-- экономика не заканчивается за четыре захода. На ПРОДАЖУ руды из шахты
	-- потолок не распространяется, там множитель работает полностью.
	-- Потолок бонуса мутаций к ПАССИВНОМУ доходу (на цену руды при продаже
	-- он не влияет — там мутации работают в полную силу).
	-- Снижен с 3.0 до 1.5 по прямому запросу («процент маленький от
	-- мутаций»). Причина не только в просьбе: пассивный доход теперь
	-- привязан к экономике самого игрока (см. OreIncome.lua), и множитель
	-- x3 поверх этой привязки означал бы, что одна удачная мутация даёт
	-- больше, чем два тира прогрессии подряд. x1.5 оставляет мутацию
	-- приятной находкой, но не заменой прокачке.
	IncomeMultiplierCap = 1.2, -- было 1.5 — часть общего нерфа пассивного дохода (см. Config.Geodes.PassiveIncomePercentOfCart)

	--------------------------------------------------------------------------
	-- ЧТО ИЗ ЭТОГО ПОПАДАЕТ В ЧАТ (см. CrystalService:Create → shouldAnnounce)
	--
	-- ПРОБЛЕМА, КОТОРУЮ ЭТО ЧИНИТ. Раньше в чат уходила ЛЮБАЯ мутация без
	-- исключений. При текущих шансах мутирует 43% всей руды, а шахта выдаёт
	-- кусок раз в 1.2-1.7 сек — то есть на сервере из 8 человек сообщение
	-- «X found a rare ... ore!» печаталось несколько раз В СЕКУНДУ. Редкая
	-- находка полностью терялась в потоке обычных: вау-эффекта не было ни у
	-- одной строки, потому что их было слишком много.
	--
	-- ИНДЕКСЫ НИЖЕ — ЭТО ПОЗИЦИИ В Order (см. выше), от частых к редким:
	--   1 Mossy   2 Rusty    3 Cracked   4 Frozen    5 Tiny      6 Toxic
	--   7 Gigantic 8 Void    9 Electric 10 Molten   11 Golden   12 Radiant
	--  13 Glitched 14 Prismatic 15 Celestial 16 Eclipsed
	-- Порядок и есть источник правды о редкости — отдельного «уровня
	-- редкости» заводить не пришлось.
	--
	-- ДВА ПРАВИЛА, ровно как задумано («только редкие и сочетания сразу
	-- нескольких»):
	--   • ОДНА мутация  → в чат, только если её индекс >= AnnounceSingleMinIndex
	--   • ДВЕ И БОЛЬШЕ  → в чат, только если САМАЯ РЕДКАЯ из них >= AnnounceComboMinIndex
	-- Порог для сочетаний намеренно НИЖЕ: две мутации сразу — уже само по
	-- себе событие, поэтому планка мягче. Но она есть: без неё в чат летели
	-- бы «Mossy + Rusty», а это 1.2% всей руды, то есть снова спам.
	--
	-- ЧТО ПОЛУЧАЕТСЯ НА ЭТИХ ЧИСЛАХ (посчитано симуляцией на 800k роллов):
	--   в чат уходит 0.89% всей руды вместо прежних 43% — в 48 раз меньше;
	--   ≈1 сообщение на игрока раз в 2.6 минуты, ≈3 в минуту на полном сервере.
	--
	-- Хочешь ещё реже — поднимай AnnounceSingleMinIndex до 15 (только
	-- Celestial/Eclipsed поодиночке). Хочешь чаще — опускай оба на 1-2.
	AnnounceSingleMinIndex = 14,
	AnnounceComboMinIndex = 13,

	-- ЖЁСТКИЙ ПОТОЛОК ЧАСТОТЫ, независимый от шансов выше. Сколько секунд
	-- обязано пройти между ЛЮБЫМИ двумя сообщениями о мутациях в чате
	-- (общий на весь сервер, не на игрока). Нужен как страховка: тир шахты
	-- и число игроков влияют на поток руды напрямую, и без этого потолка
	-- полный сервер на T10 снова превратил бы чат в ленту. Находка при этом
	-- не пропадает — она просто не печатается: книга мутаций
	-- (MutationBookService) и цена кристалла считаются как обычно.
	AnnounceGlobalCooldown = 20,

	-- ИСКЛЮЧЕНИЕ ИЗ ПОТОЛКА. Мутации с индексом >= этого печатаются ВСЕГДА,
	-- даже если кулдаун ещё не прошёл: Celestial (0.2%) и Eclipsed (0.1%) —
