--------------------------------------------------------------------------------
-- ПОГОДНЫЕ ИВЕНТЫ — по прямому запросу. Раз в RollIntervalSeconds сервер
-- перебрасывает кубик и выбирает, что будет твориться на карте следующие
-- RollIntervalSeconds (тот же интервал — ивент длится РОВНО до следующего
-- броска, отдельного поля Duration нет специально, чтобы не расходилось).
-- См. WeatherService.lua — там сам бросок, смена освещения, синхронизация
-- с клиентами и применение бустов к мутациям (через MutationRoll —
-- CrystalService/RockService передают туда BoostedMutations текущего
-- ивента при каждом броске мутации на новую руду).
--
-- Chance — АБСОЛЮТНАЯ вероятность именно этого ивента при каждом броске
-- (не "из оставшихся", а от общего пула) — сумма всех Chance ниже меньше 1,
-- остаток — это "Clear" (обычная погода, без ивента, не описан отдельной
-- записью — WeatherService просто ничего не применяет, если ни один Chance
-- не выпал). Порядок — от частого к редкому, как и Config.Mutations.Order.
--------------------------------------------------------------------------------
Config.WeatherEvents = {
	Enabled = true,
	RollIntervalSeconds = 300, -- 5 минут

	Events = {
		{
			Id = "Night",
			DisplayName = "Nightfall",
			Chance = 0.135, -- по прямому запросу — все 5 ивентов вместе теперь дают 40%, чистое небо 60%
			-- IsDark — для скайбокса (см. WeatherService:_applySky ниже):
			-- если у конкретного ивента своего скайбокса нет, тёмные
			-- (IsDark=true) откатываются на общий "NightSky", светлые — на
			-- общий "DaySky".
			IsDark = true,
			-- Небо/звёзды — тематически ближе всего к ночи из уже готовых
			-- мутаций: Celestial ("небесный", голубое сияние) и Void
			-- (тёмный, почти чёрный) — усиливаем СРАЗУ ДВЕ, как и просили
			-- ("либо сразу на два типа мутаций").
			-- Void теперь ОСНОВНАЯ мутация ночи — по прямому запросу
			-- "специфичная руда должна выпадать даже чаще обычной". Базовый
			-- шанс 0.021 × 26 ≈ 55% при luck=0 — чаще, чем "обычная" руда
			-- без мутации, и растёт ещё выше с прокачанным luck (Void
			-- ScalesWithLuck=true). Celestial остаётся редким бонусом
			-- поверх (тот же множитель, что и был) — "остальные мутации
			-- реже, чем эта".
			BoostedMutations = { Celestial = 6, Void = 26 },
			-- Яркость поднята по прямому запросу ("не такой тёмной, но
			-- чтобы было понятно что всё ещё ночь") — Brightness почти
			-- вдвое выше, Ambient/OutdoorAmbient светлее, но оттенок
			-- остался тем же холодным сине-фиолетовым, ClockTime всё ещё
			-- полночь — ночь читается сразу, просто не кромешная тьма.
			-- Яркость теперь СЧИТАЕТСЯ ОТНОСИТЕЛЬНО реального дня (см.
			-- WeatherService:_applyDarknessRatio), а не зашита абсолютным
			-- числом — по прямому запросу "примерно на 20% темнее чем
			-- днём, чтобы фонари не понадобились". Хардкод (2.2 и т.п.)
			-- работал бы только если день на карте ровно такой яркости,
			-- какую я себе представлял — с DarknessRatio это верно всегда,
			-- на любой карте. 0.8 = 80% от дневной яркости (то есть на 20%
			-- темнее).
			-- Затемнение снижено ещё сильнее по повторному запросу — свои
			-- скайбоксы теперь несут атмосферу ночи сами, Lighting не
			-- обязан затемнять так сильно. 0.95 = 95% от дневной яркости.
			-- FogColor/FogEnd ниже DarknessRatio не трогает вообще (только
			-- Brightness/Ambient/OutdoorAmbient) — атмосфера/туман остаются
			-- как заданы, не "осветляются" вместе с этим.
			DarknessRatio = 0.95,
			Lighting = {
				ClockTime = 0, -- полночь
				Brightness = 2.2, -- запасное значение, если DarknessRatio почему-то не применится
				Ambient = Color3.fromRGB(55, 55, 85),
				OutdoorAmbient = Color3.fromRGB(50, 50, 80),
				FogColor = Color3.fromRGB(30, 30, 50),
				FogEnd = 900,
			},
			VfxKind = "Night", -- см. WeatherFX.client.lua — какие частицы/цвет использовать
			AnnounceText = "🌙 NIGHTFALL — Celestial and Void ore are far more common while it lasts!",
		},
		{
			Id = "Rain",
			DisplayName = "Rainstorm",
			Chance = 0.162, -- по прямому запросу — все 5 ивентов вместе теперь дают 40%, чистое небо 60%
			IsDark = false,
			-- По прямому запросу — затемнение на 13% относительно реального
			-- дня (см. WeatherService:resolveLightingTarget), то есть
			-- DarknessRatio = 0.87.
			DarknessRatio = 0.645, -- было 0.7 — ещё на 5.5% темнее, по прямому запросу
			-- Базовый шанс 0.045 × 13 ≈ 60% при luck=0 — чаще, чем обычная
			-- руда без мутации, по прямому запросу.
			BoostedMutations = { Soaked = 13 },
			Lighting = {
				Brightness = 1.4, -- запасное значение, если DarknessRatio почему-то не применится
				Ambient = Color3.fromRGB(60, 65, 75),
				OutdoorAmbient = Color3.fromRGB(70, 75, 85),
				FogColor = Color3.fromRGB(120, 130, 140),
				FogEnd = 550,
			},
			VfxKind = "Rain",
			AnnounceText = "🌧️ RAINSTORM — Soaked ore is much more common while it lasts!",
		},
		{
			Id = "Thunderstorm",
			DisplayName = "Thunderstorm",
			Chance = 0.068, -- по прямому запросу — все 5 ивентов вместе теперь дают 40%, чистое небо 60%
			IsDark = false,
			DarknessRatio = 0.595, -- было 0.65 — ещё на 5.5% темнее, по прямому запросу
			-- Electric — прямое попадание (молния = электричество). Glitched
			-- добавлен вторым — визуально его "подрагивание" читается как
			-- нервная реакция на грозу, тот же принцип "два типа сразу".
			-- Electric теперь ОСНОВНАЯ мутация грозы — 0.021 × 26 ≈ 55% при
			-- luck=0, чаще обычной руды. Glitched остаётся второстепенным
			-- бонусом с прежним множителем — "остальные мутации реже, чем
			-- эта".
			BoostedMutations = { Electric = 26, Glitched = 5 },
			Lighting = {
				Brightness = 1.0, -- запасное значение
				Ambient = Color3.fromRGB(40, 40, 55),
				OutdoorAmbient = Color3.fromRGB(35, 35, 50),
				FogColor = Color3.fromRGB(30, 30, 45),
				FogEnd = 450,
			},
			VfxKind = "Thunderstorm",
			AnnounceText = "⛈️ THUNDERSTORM — Electric and Glitched ore are surging!",
		},
		{
			Id = "BloodMoon",
			DisplayName = "Blood Moon",
			Chance = 0.027, -- по прямому запросу — все 5 ивентов вместе теперь дают 40%, чистое небо 60%
			IsDark = true,
			-- Sanguine — новая мутация, см. Config.Mutations (подходящей
			-- кроваво-красной не было, завели специально под этот ивент).
			-- Базовый шанс 0.015 × 40 ≈ 60% при luck=0 — чаще обычной руды,
			-- по прямому запросу.
			BoostedMutations = { Sanguine = 40 },
			-- Тоже посветлело по тому же запросу — красный оттенок остаётся
			-- ведущим (это и есть "кровавая луна"), но не тонет в почти
			-- полной черноте, как раньше.
			-- Та же логика DarknessRatio, что и у Night выше — 20% темнее
			-- реального дня на этой карте, а не абсолютное число.
			DarknessRatio = 0.95, -- было 0.8 — по повторному запросу светлее, свой скайбокс несёт атмосферу сам
			-- Красность снижена на ~20% по прямому запросу — R-канал
			-- уменьшен, G/B оставлены как были, так яркость/темнота (через
			-- DarknessRatio) не меняется, меняется именно насыщенность
			-- красного.
			Lighting = {
				ClockTime = 0,
				Brightness = 1.8, -- запасное значение
				Ambient = Color3.fromRGB(76, 30, 30),
				OutdoorAmbient = Color3.fromRGB(68, 25, 25),
				FogColor = Color3.fromRGB(52, 15, 15),
				FogEnd = 700,
			},
			VfxKind = "BloodMoon",
			AnnounceText = "🔴 BLOOD MOON RISES — Sanguine ore is everywhere tonight!",
		},
		{
			Id = "SolarEclipse",
			DisplayName = "Solar Eclipse",
			Chance = 0.008, -- по прямому запросу — все 5 ивентов вместе теперь дают 40%, чистое небо 60%, но всё ещё САМОЕ РЕДКОЕ
			IsDark = true,
			-- Базовый шанс всего 0.001 (самая редкая руда в игре) —
			-- множитель поднят до 550 (0.001×550 ≈ 55% при luck=0), чтобы
			-- во время самого редкого ивента она была основной рудой, а
			-- не редким исключением из редкого исключения. Плюс
			-- ForcedMutationChance ниже — часть руды получает Eclipsed
			-- напрямую, минуя этот бросок вообще.
			BoostedMutations = { Eclipsed = 550 },
			-- ТОЛЬКО у затмения: часть добытой руды получает Eclipsed
			-- НАПРЯМУЮ, минуя обычный бросок (см. MutationRoll.ForceInclude)
			-- — самый редкий ивент должен ощущаться качественно иначе, а не
			-- просто "шанс чуть выше".
			ForcedMutationChance = 0.12,
			-- Та же система DarknessRatio, что и у Night/BloodMoon/Rain/
			-- Thunderstorm (см. WeatherService:resolveLightingTarget) — по
			-- прямому запросу "всё должно быть оранжевое +- как в кровавую
			-- луну": оттенок теперь ГАРАНТИРОВАННО остаётся ведущим
			-- (масштабируется от реальной яркости дня, сохраняя цвет, а не
			-- фиксированным абсолютным числом, которое на ярком дне могло
			-- бы смотреться тускло/невыразительно). 0.35 — заметно темнее,
			-- чем у кровавой луны (0.8): самый редкий ивент должен
			-- ощущаться качественно мрачнее, не просто "оранжевый день".
			DarknessRatio = 0.6, -- было 0.35 — по повторному запросу светлее (свой скайбокс несёт атмосферу), но всё ещё заметно темнее остальных — самый редкий ивент должен ощущаться мрачнее
			Lighting = {
				ClockTime = 12,
				Brightness = 0.2, -- запасное значение, если DarknessRatio почему-то не применится
				-- Оттенок усилен по прямому запросу — БЕЗ полноэкранного
				-- оверлея (тот убрали по повторному запросу), весь эффект
				-- держится на самом Lighting: R поднят заметно выше, G/B
				-- заметно ниже, чем в первой версии — более насыщенный,
				-- "чистый" оранжевый, а не размытый бежево-коричневый.
				Ambient = Color3.fromRGB(115, 48, 8),
				OutdoorAmbient = Color3.fromRGB(100, 40, 6),
				FogColor = Color3.fromRGB(80, 32, 5),
				FogEnd = 300,
			},
			VfxKind = "SolarEclipse",
			AnnounceText = "🌑 SOLAR ECLIPSE — Eclipsed ore chance is off the charts, and some ore turns Eclipsed instantly!",
		},
	},
}

-- НА КАКОМ РАССТОЯНИИ ВИДНО ПОЛОСКИ ЗДОРОВЬЯ. BillboardGui.MaxDistance
-- скрывает подпись дальше указанного расстояния сам, на стороне каждого
-- клиента — скрипт для этого не нужен.
--
-- У валуна раньше ограничения не было вовсе: "BOULDER LV. 5  340/900" читался
-- через всю карту, и в поле зрения одновременно висело до шестнадцати таких
-- подписей. У гоблина стояло 70 — тоже далеко, полоска появлялась задолго до
-- того, как игрок вообще собирался драться.
Config.HealthDisplay = {
	BoulderMaxDistance = 55,
	GoblinMaxDistance = 55,
}

-- РАЗГОН ПРИ ДОЛГОЙ ХОДЬБЕ ("бег"). Игрок, который двигается без остановки
-- дольше BuildUpSeconds, плавно ускоряется на SpeedBonus. Стоит остановиться —
-- разгон так же плавно спадает.
--
-- Множитель применяется в CartService:recomputeWalkSpeed — это единственное
-- место в проекте, где выставляется WalkSpeed игрока, поэтому бег
-- автоматически совмещается со всем остальным: бонусом за ребёрты,
-- геймпассом Speed Boost, замедлением от руды в руках и оглушением.
Config.Sprint = {
	Enabled = true,
	BuildUpSeconds = 3,    -- сколько нужно двигаться без остановки, чтобы начать разгоняться
	SpeedBonus = 0.40,     -- +40% к итоговой скорости на полном разгоне
	RampSeconds = 0.8,     -- за сколько бонус набирается полностью (и спадает)
	-- Короткая остановка не сбрасывает разгон: иначе бег обрывался бы от
	-- любого шага назад, прыжка или упора в угол.
	StopGraceSeconds = 0.3,
	-- С тележкой разгон НЕ работает. Скорость толкания намеренно
	-- фиксированная (Config.Cart.FixedCartSpeed), чтобы доставка не зависела
	-- от прокачки и все игроки везли груз одинаково — бег бы это сломал.
	ApplyWhileHoldingCart = false,
}

Config.Bank = {
	-- v17: при сдаче руды торговцу (банку) крупное «+$…» пиксельным шрифтом
	-- на ЭКРАНЕ больше не показывается — доход и так считает счётчик над
	-- торговцем (client/SellFx). true — вернуть экранную надпись.
	ScreenMoneyPopupOnSell = false,
	-- Руда продаётся ТОЛЬКО тележкой (по прямому запросу). true вернёт
	-- старую продажу руды из рук (HandCarry) прямо в зоне банка.
	HandSellEnabled = false,

	--------------------------------------------------------------------------
	-- ПРОДАЖА РУДЫ ИЗ РЮКЗАКА (см. BankService:_sellBackpack).
	--
	-- ЗАЧЕМ. До первой тележки у игрока нет вообще никакого способа
	-- превратить руду в деньги — а тележку он получает только на шестом
	-- шаге обучения. Без этой продажи первые два шага (сломать валуны,
	-- отнести руду в центр) упирались бы в стену.
	--
	-- ПОЧЕМУ ЭТО НЕ ЛОМАЕТ ЭКОНОМИКУ. Рюкзак сознательно хуже тележки по
	-- двум осям сразу: комбо-множитель рейса (до x120, см.
	-- Config.Cart.ComboThresholds) на такую продажу НЕ начисляется вообще,
	-- а до покупки тележки рюкзак ужат до StarterSlots ячеек (см.
	-- Config.Inventory). Возить руду руками остаётся аварийным вариантом,
	-- а не заменой рейсу.
	InventorySellEnabled = true,
	InventorySellDelay = 0.12, -- пауза между кусками, чтобы продажа читалась как процесс
	SellDelayPerCrystal = 0.16,
	SellAcceleration = 0.82,
	SellMinimumDelay = 0.035,
}

--------------------------------------------------------------------------------
-- ТОРГОВЕЦ И БИРЖА РУДЫ (заменили слайма банка).
--
-- Торговец стоит в зоне банка ПОСТОЯННО (MerchantService). Раз в
-- CycleSeconds ОДНОВРЕМЕННО, для всего сервера:
--   • меняется КУРС — общий множитель цены продажи ВСЕЙ руды (Market);
--   • обновляется СТОК лавки — что и сколько продаётся (Items).
-- Таймер один на весь сервер: все видят одно и то же "New stock in 3m 17s"
-- и одинаковый курс, поэтому "x2.4 ПРЯМО СЕЙЧАС" — общее событие, ради
-- которого стоит доехать до банка или придержать тележку.
--
-- ЗАЧЕМ ИМЕННО ТАК (удержание онлайна):
--   • решение "продать сейчас или переждать обвал" — с риском, что
--     тележку по дороге угонят;
--   • редкий товар в стоке появляется не каждый цикл, а цикл короткий —
--     повод заглянуть через 5 минут;
--   • личный RESTOCK за Robux перебрасывает сток только себе.
--------------------------------------------------------------------------------
Config.Merchant = {
	Enabled = true,
	CycleSeconds = 5 * 60,

	-- Имя модели в ReplicatedStorage.Assets — своя модель торговца
	-- подставляется без правок кода (PlaceholderFactory.BankMerchant).
	AssetName = "BankMerchant",
	DisplayName = "Ore Merchant",
	PromptDistance = 12,

	--------------------------------------------------------------------------
	-- БИРЖА. Курс выбирается корзиной (по весу), внутри корзины —
	-- равномерно, с округлением до Step. Средний курс при случайной продаже
	-- ≈ x1.06 — экономика почти не разгоняется, а выигрыш даёт именно
	-- умение поймать хороший цикл. Корзины с Announce объявляются в чат.
	--------------------------------------------------------------------------
	Market = {
		Step = 0.05,
		-- Два обвала подряд — уже не игра, а наказание:
		-- после Crash следующий цикл не может снова быть Crash.
		NoRepeat = { Crash = true, Jackpot = true },
		-- v4: курс сужен до x0.7 … x1.8 (было x0.4 … x3). Средний ≈ x1.03.
		Buckets = {
			{ Id = "Crash",   Weight = 10, Min = 0.70, Max = 0.75, Label = "CRASH",   Color = Color3.fromRGB(255, 80, 80),  Announce = true },
			{ Id = "Low",     Weight = 28, Min = 0.75, Max = 0.95, Label = "LOW",     Color = Color3.fromRGB(255, 160, 90) },
			{ Id = "Normal",  Weight = 34, Min = 0.95, Max = 1.10, Label = "NORMAL",  Color = Color3.fromRGB(235, 235, 235) },
			{ Id = "High",    Weight = 18, Min = 1.10, Max = 1.35, Label = "HIGH",    Color = Color3.fromRGB(120, 255, 120) },
			{ Id = "Boom",    Weight = 8,  Min = 1.35, Max = 1.60, Label = "BOOM",    Color = Color3.fromRGB(70, 255, 170), Announce = true },
			{ Id = "Jackpot", Weight = 2,  Min = 1.70, Max = 1.80, Label = "JACKPOT", Color = Color3.fromRGB(255, 215, 60), Announce = true },
		},
	},

	--------------------------------------------------------------------------
	-- ЛАВКА. Показываются ВСЕ товары всегда (как в Grow a Garden): каждый
	-- цикл товар с шансом Chance получает сток в диапазоне Stock, иначе —
	-- "NO STOCK". Сток личный: у каждого игрока свои X шт. на цикл.
	--
	-- v4: цены ФИКСИРОВАННЫЕ (Price, в $) — не зависят от пещеры и тележки
	-- игрока. Прокачался — старые товары стали дешевле, пассы x2..x5
	-- реально ускоряют. Ориентир: зелье x2 Money ≈ 6K — дорого на пещере 5,
	-- копейки на пещере 12; скины — долгосрочные цели.
	--
	-- Kind:
	--   Potion  — кладётся в data.Potions, активируется тапом в панели
	--             зелий (баф из Config.Buffs[Buff] на Seconds секунд);
	--   Gear    — снаряжение (GearService:AddGear), Key = ключ Config.Dynamite.Types;
	--   Skin    — скин кирки (SkinService:GrantSkin), разовый.
	--------------------------------------------------------------------------
	Items = {
		-- В лавке ТОЛЬКО то, чего нигде больше не купить: бафы ×2 и скины
		-- кирок. Обычный динамит продаётся у торговца улучшениями всегда —
		-- здесь он не появляется, чтобы не занимать место в стоке.
		{ Id = "Potion_Speed",    Kind = "Potion", Potion = "Potion_Speed",    Rarity = "Common",    Chance = 1.00, Stock = { 2, 4 }, Price = 500 },
		{ Id = "Potion_Damage",   Kind = "Potion", Potion = "Potion_Damage",   Rarity = "Uncommon",  Chance = 0.80, Stock = { 1, 3 }, Price = 1500 },
		{ Id = "Skin_Radioactive",Kind = "Skin",   SkinId = "RadioactivePickaxe", DisplayName = "Radioactive Pickaxe", Icon = "⛏", Rarity = "Uncommon", Chance = 0.50, Stock = { 1, 1 }, Price = 20000 },
		{ Id = "Potion_Money",    Kind = "Potion", Potion = "Potion_Money",    Rarity = "Rare",      Chance = 0.60, Stock = { 1, 2 }, Price = 6000 },
		{ Id = "Potion_Luck",     Kind = "Potion", Potion = "Potion_Luck",     Rarity = "Rare",      Chance = 0.45, Stock = { 1, 2 }, Price = 9000 },
		{ Id = "Skin_Love",       Kind = "Skin",   SkinId = "LovePickaxe",        DisplayName = "Love Pickaxe",        Icon = "⛏", Rarity = "Rare",     Chance = 0.28, Stock = { 1, 1 }, Price = 120000 },
		{ Id = "Skin_BigWooden",  Kind = "Skin",   SkinId = "BigWoodenPickaxe",   DisplayName = "Big Wooden Pickaxe",  Icon = "⛏", Rarity = "Rare",     Chance = 0.28, Stock = { 1, 1 }, Price = 120000 },
		{ Id = "Potion_Mutation", Kind = "Potion", Potion = "Potion_Mutation", Rarity = "Epic",      Chance = 0.20, Stock = { 1, 1 }, Price = 30000 },
		{ Id = "Skin_Crystal",    Kind = "Skin",   SkinId = "CrystalPickaxe",     DisplayName = "Crystal Pickaxe",     Icon = "⛏", Rarity = "Epic",     Chance = 0.13, Stock = { 1, 1 }, Price = 450000 },
		{ Id = "Potion_MoneyX3",  Kind = "Potion", Potion = "Potion_MoneyX3",  Rarity = "Legendary", Chance = 0.07, Stock = { 1, 1 }, Price = 75000 },
		{ Id = "Skin_Void",       Kind = "Skin",   SkinId = "VoidPickaxe",        DisplayName = "Void Pickaxe",        Icon = "⛏", Rarity = "Legendary", Chance = 0.05, Stock = { 1, 1 }, Price = 1500000 },
	},

	-- Редкий товар в стоке объявляется всему серверу — повод доехать до
	-- банка, пока не разобрали (сток личный, но цикл общий).
	AnnounceRarities = { Epic = true, Legendary = true, Mythic = true },

	-- Табло над торговцем (курс/таймер). Выключено: курс и таймер видны в
	-- HUD-плашке сверху и в самом окне лавки, над кротом остаётся чисто.
	ShowBoard = false,

	-- Цвета плашек редкости в окне лавки.
	RarityColors = {
		Common    = Color3.fromRGB(170, 170, 170),
		Uncommon  = Color3.fromRGB(90, 200, 90),
		Rare      = Color3.fromRGB(60, 140, 255),
		Epic      = Color3.fromRGB(170, 80, 255),
		Legendary = Color3.fromRGB(255, 185, 40),
		Mythic    = Color3.fromRGB(255, 70, 90),
	},

	-- НАСЛЕДИЕ СЛАЙМА. Уровень слайма давал +1% к продаже за уровень.
	-- Прогресс кормления (data.SlimeFedValue) не выбрасывается: игрок
	-- получает тот же бонус навсегда, замороженным (DataService:
	-- GetLegacySellBonus). Новые игроки его не копят.
	LegacySlime = {
		BonusPerLevel = 0.01,
		Thresholds = { 0, 2000, 10000, 40000, 150000, 600000, 2500000, 10000000, 40000000 },
	},
}

--------------------------------------------------------------------------------
-- ЗЕЛЬЯ — снаряжение (data.Gear[key]), как динамит и сундуки: лежат в
-- инвентаре, ячеек рюкзака не тратят, ставятся в хотбар. Взял в руку — над
-- головой колба-пузырёк (client/PotionBubble.client.lua, у всех игроков),
-- клик — выпить (GearService:_drinkPotion → BuffService).
--
-- Amount — бонус сверх 1.0 в терминах BuffService: Money/Speed/Damage
-- читаются как множитель 1+Amount (1.0 = ×2), Luck — прямая добавка к
-- удаче (0.15 = та же сила, что Robux-продукт "Luck x2"), MutationPotion —
-- множитель шанса мутаций как есть (2 = ×2).
-- Второе зелье того же вида ПРОДЛЕВАЕТ действие, а не сгорает.
--------------------------------------------------------------------------------
Config.Potions = {
	Order = { "Potion_MoneyX3", "Potion_Money", "Potion_Luck", "Potion_Mutation", "Potion_Damage", "Potion_Speed" },
	MaxStack = 99,
	Types = {
		Potion_Speed    = { Buff = "Speed",          Amount = 1.0,  Seconds = 180, DisplayName = "x2 Speed Potion",    Icon = "⚡", Color = Color3.fromRGB(90, 200, 255) },
		Potion_Damage   = { Buff = "Damage",         Amount = 1.0,  Seconds = 180, DisplayName = "x2 Damage Potion",   Icon = "💪", Color = Color3.fromRGB(255, 90, 70) },
		Potion_Money    = { Buff = "Money",          Amount = 1.0,  Seconds = 180, DisplayName = "x2 Money Potion",    Icon = "💰", Color = Color3.fromRGB(255, 215, 70) },
		Potion_Luck     = { Buff = "Luck",           Amount = 0.15, Seconds = 300, DisplayName = "x2 Luck Potion",     Icon = "🍀", Color = Color3.fromRGB(110, 235, 120) },
		Potion_Mutation = { Buff = "MutationPotion", Amount = 2.0,  Seconds = 180, DisplayName = "x2 Mutation Potion", Icon = "🧪", Color = Color3.fromRGB(200, 110, 255) },
		Potion_MoneyX3  = { Buff = "Money",          Amount = 2.0,  Seconds = 120, DisplayName = "x3 Money Potion",    Icon = "💎", Color = Color3.fromRGB(255, 170, 40) },
	},
}


--------------------------------------------------------------------------------
	-- ТОЧНЫЕ ШАНСЫ ПО КАЖДОМУ ИСХОДУ (для честного раскрытия дропа, Roblox
-- Random Item Generator policy). Это НЕ отдельная таблица данных — цифры
	-- ниже лишь ДОКУМЕНТИРУЮТ то, что реально считают Types[x].MoneyChance/
-- MoneyChance ниже + Config.Skins.DropChance, разложенные поровну между
-- позициями внутри каждой корзины (Ores — GeodeService:levelForCopies не
-- участвует, это распределение ПЕРВОГО дропа; money — фиксированный сплит
-- 70/25/5% между Money[1]/[2]/[3]; skin — поровну между Pickaxe-скинами
-- этого типа, Cart-скины сейчас НЕ в пуле, см. Config.Skins.Definitions).
	-- Dust отключён: его бывшая доля добавлена к руде. Если поменяешь
	-- MoneyChance/Money[]/DropChance/список Ores или
-- список скинов — актуализируй и эту табличку, иначе расхождение между
-- увиденным игроком текстом и кодом = нарушение политики.
--
	-- Все типы жеод используют одинаковые корзины: 55% деньги, 25% руда,
	-- 5% скин, 15% временный бафф (см. Config.Buffs ниже — по прямому
	-- запросу "внутри по сути бесполезные скины и деньги, предложи как
	-- переделать"). Три денежные награды делят 55% как 70/25/5, руды и
	-- баффы делятся поровну между вариантами каждой категории.
--
-- Каждая строка выше в сумме даёт ровно 100.00% (проверено). Совпадает 1:1
-- с тем, что реально показывает панель "i" в GeodeUI.client.lua (та же
-- формула деления поровну), и с тем, что реально считает GeodeService:OpenGeode.
--------------------------------------------------------------------------------
Config.Geodes = {
	MaxPerCart = 3,
	SafeCollectHoldDuration = 1.5,
	-- Кристалл на подиуме — левитирует над центром и крутится вокруг себя
	-- (см. PassiveIncomeService:UpdateDisplay), а не стоит неподвижно.
	OreLevitateHeight = 0.15, -- небольшой зазор над "родной" точкой посадки
	OreBobHeight = 0.35,      -- студ, амплитуда лёгкого покачивания вверх-вниз
	OreBobSpeed = 1.5,        -- рад/сек, скорость покачивания
	OreSpinSpeed = 1.0,       -- рад/сек, скорость вращения вокруг себя
	CrystalSwitchCooldown = 0.6,
	SpawnPity = 40,
	OpenPity = 8,
	OfflineCapSeconds = 8 * 60 * 60, -- v3: было 24ч; сейф и так ограничен SafeCapTargetHours

	--------------------------------------------------------------------------
	-- ПОТОЛОК БАЛАНСА СЕЙФА — ДОЛЯ ОТ ЦЕНЫ ТЕКУЩЕГО РЕБЁРТА.
	--
	-- ЗАЧЕМ. Доход руды растёт примерно ×10 за тир (см. Ores ниже:
	-- 2K → 30K → 180K → 1.5M → 12M → 120M → 1.2B → 12B → 24B → 42B в минуту),
	-- а цена ребёрта после того, как тир-кап упёрся в MaxTierCap, растёт
	-- всего ×1.30 за ребёрт (Config.Rebirth.LateCostGrowth). Кривые
	-- расходятся, и в лейте ОДНА суточная выплата сейфа перекрывала целый
	-- ребёрт. Считано на реальных числах:
	--   Eclipse   (lvl 10, мутация ×3) = 9.85e13 за 24 ч, ребёрт №6 = 8.07e13
	--   Infinitum (lvl 10, мутация ×3) = 3.45e14 за 24 ч, ребёрт №12 = 3.90e14
	-- То есть игрок жал ОДНУ кнопку раз в сутки и получал ребёрт, полностью
	-- минуя активную петлю (шахта → тележка → банк). Это обесценивало и
	-- прокачку, и PvP, и комбо-множитель разом.
	--
	-- КАК РАБОТАЕТ. Накопление в PassiveIncomeService:Accrue не уходит выше
	-- SafeCapPercentOfRebirth × (цена СЛЕДУЮЩЕГО ребёрта этого игрока).
	-- Потолок ПЕРСОНАЛЬНЫЙ и растёт вместе с игроком сам: цена ребёрта
	-- считается через DataService:GetRebirthCost, то есть уже включает и
	-- Config.Economy.ProgressionSlowdown, и денежные пассы игрока. Отдельно
	-- пересчитывать при каждом ребалансе ничего не нужно.
	--
	-- ПОЧЕМУ ИМЕННО ДОЛЯ, А НЕ ФИКСИРОВАННОЕ ЧИСЛО. Фиксированный потолок
	-- пришлось бы переписывать после каждой правки цен, и он всё равно
	-- ломался бы на разных стадиях игры: 10 млрд — это целое состояние на
	-- T5 и пыль на T10. Доля держит один и тот же СМЫСЛ на всей дистанции:
	-- «сейф — ощутимая помощь к ребёрту, но никогда не сам ребёрт».
	--
	-- 0.55 = сейф закрывает максимум 55% следующего ребёрта, остальные 45%
	-- игрок обязан отвезти тележкой. Ставь меньше, если сейф всё ещё
	-- ощущается сильнее активной игры; больше — если наоборот, возвраты
	-- перестали радовать. Значение 0 полностью выключает потолок (прежнее
	-- поведение), 1.0 = ровно один ребёрт за одну выплату.
	--
	-- ЧТО ЭТО ЗНАЧИТ НА ПРАКТИКЕ при 0.55: полностью заполненный сейф — это
	-- чуть больше половины ребёрта. То есть возврат после суток отсутствия
	-- ощущается как крупный подарок (половина цели закрыта одной кнопкой),
	-- но вторую половину всё равно приходится возить тележкой, и активная
	-- петля остаётся обязательной. Для сравнения: ДО потолка одна суточная
	-- выплата в лейте перекрывала ребёрт ЦЕЛИКОМ и с запасом.
	SafeCapPercentOfRebirth = 0, -- v3: выключено (ребёрт теперь дешёвый, потолок резал пассивку в ноль)

	--------------------------------------------------------------------------
	-- ЦЕЛЕВОЕ ВРЕМЯ ЗАПОЛНЕНИЯ СЕЙФА (гибридный потолок).
	--
	-- ПРОБЛЕМА С ЧИСТЫМ "% ОТ РЕБЁРТА": время заполнения плавает от игрока к
	-- игроку — у кого-то 40 минут, у кого-то сутки, — поэтому обещать в UI
	-- конкретное "через 5 часов" было нечестно.
	--
	-- РЕШЕНИЕ: потолок сейфа теперь МИНИМУМ из двух ограничений:
	--   1) доход_в_минуту × 60 × SafeCapTargetHours — держит одно и то же
	--      ОЩУЩЕНИЕ времени у всех игроков, на любом тире;
	--   2) SafeCapPercentOfRebirth × цена_ребёрта — старый защитный потолок,
	--      который не даёт лейту одной выплатой перекрывать целый ребёрт
	--      (см. развёрнутое обоснование выше).
	-- Берём МЕНЬШЕЕ: для большинства игроков сработает пункт 1 (честные
	-- 5 часов), а на позднем тире, где доход уже космический, сработает
	-- пункт 2 и утащит потолок ниже — экономика остаётся защищённой.
	SafeCapTargetHours = 3,

	--------------------------------------------------------------------------
	-- ТРЕТИЙ ОГРАНИЧИТЕЛЬ СЕЙФА: «сколько это рейсов».
	--
	-- ЗАЧЕМ ЕЩЁ ОДИН. Двух прежних не хватало на РАННЕЙ игре, и это видно
	-- только если посчитать. Рейс на тире 1 занимает ~50 секунд, а сейф
	-- копит 5 часов — то есть полный сейф новичка равен примерно 265
	-- полным рейсам. Ограничитель «% от ребёрта» там не срабатывает вообще
	-- (цена ребёрта на старте астрономическая по сравнению с его доходом),
	-- поэтому новичок, отошедший на вечер, возвращался к сумме, которая
	-- разом перепрыгивала ему несколько тиров шахты. На тире 9 та же
	-- механика даёт всего ~9 рейсов — то есть смысл сейфа был совершенно
	-- разным на разных стадиях игры.
	--
	-- Этот потолок выражен в ЕДИНИЦАХ САМОЙ ИГРЫ: «полный сейф ≈ N хороших
	-- рейсов», и потому означает одно и то же на любом тире. 25 подобрано
	-- так, чтобы на тирах 4+ он вообще не срабатывал (там и так выходит
	-- 9-28 рейсов) и подрезал только ранний перекос.
	--
	-- 0 или nil выключает этот ограничитель, оставляя два прежних.
	SafeCapTripEquivalent = 0, -- v4: выключено — потолок сейфа только по времени (SafeCapTargetHours)

	-- БОНУС ЗА ПОЛНЫЙ СЕЙФ. Раньше не было разницы между "забрал в
	-- процессе" и "дождался полного" — сумма всё равно упиралась в потолок.
	-- Теперь забор РОВНО когда сейф полон (не раньше) даёт +25% к сумме —
	-- это и есть обещанное "через 5 часов — много денег", а не просто
	-- урезанная капель. 0 или nil выключает бонус.
	SafeFullBonusMultiplier = 1.25,

	-- ГЛОБАЛЬНЫЙ МНОЖИТЕЛЬ ПАССИВНОГО ДОХОДА С РУДЫ (тик в минуту).
	-- Раньше цифра на табличке подиума росла заметным темпом каждую минуту —
	-- ощущалось как отдельный источник дохода наравне с активной шахтой.
	-- Урезано вдвое: капает медленнее и незаметнее, а весь смысл сейфа
	-- переносится на разовую крупную выплату раз в SafeCapTargetHours часов
	-- (см. выше), а не на ежеминутный тикер.
	-- Общий рубильник силы пассивного дохода. Раньше стоял 0.5, потому что
	-- сами числа IncomePerMinute были заведомо завышены и их резали здесь.
	-- Теперь доход считается по формуле, которая изначально откалибрована
	-- по реальному доходу рейса (см. src/shared/OreIncome.lua) — резать
	-- нечего, множитель нейтральный. Крути ЕГО, если после теста весь
	-- пассивный доход целиком кажется сильным или слабым: он трогает все
	-- 40 руд разом и не ломает соотношения между ними.
	-- РЕБАЛАНС ЭКОНОМИКИ v2 (по прямому запросу — "кристаллы/пассивный
	-- доход слишком сильные, прогрессия должна идти за счёт шахтёрства").
	-- Подиумный доход больше НЕ считается по таблице IncomePerMinute на
	-- руду (это и разгоняло экономику само по себе — см. OreIncome.lua).
	-- Теперь это простая, честная и легко читаемая формула:
	--   доход/мин = PassiveIncomePercentOfCart × стоимость ПОЛНОЙ тележки
	--               на тире игрока × бонус уровня руды (мелкий) × мутация
	--   → копится в сейф, включая оффлайн (существующая механика сейфа,
	--     см. PassiveIncomeService/BankService — не тронута).
	-- 0.05 = ровно "+5% от продажи всей тележки", как и просили. Если
	-- по тесту это всё ещё много — крути только эту строку, не формулу.
	PassiveIncomePercentOfCart = 0.05, -- legacy (v3 использует CartShare кристалла, см. OreIncome.PerMinute)
	PassiveIncomeMultiplier = 1, -- v3: общий рубильник поверх CartShare -- доп. глобальный рубильник "максимально занерфить" поверх процента — эффективно ~2.5% в минуту устоявшегося дохода от полной тележки

	-- СБРОС КОЛЛЕКЦИИ ЖЕОД/РУД ПРИ РЕБЁРТЕ. По ТЗ автор сам не был
	-- уверен, оставить или нет — оставлено ВЫКЛЮЧЕННЫМ по умолчанию
	-- (коллекция — это прогресс, который приятно копить между ребёртами).
	-- Включить: поставить true — DataService/RebirthService должны при
	-- ребёрте чистить data.GeodeCollection и data.InstalledGeodeOre (это
	-- ещё предстоит подключить в RebirthService:Perform, см. ROADMAP.md).
	ResetCollectionOnRebirth = false,

	-- ВТОРАЯ ТАБЛИЧКА НАД ПОДИУМОМ (название руды + доход + мутации).
	--
	-- Выключена по прямому запросу. Над самим кристаллом теперь висит
	-- отдельная подпись "$X/SEC" (см. IncomeLabel в PassiveIncomeService),
	-- и эта табличка стала её дублем: она повторяла тот же доход, только
	-- в минутах, добавляла название и список мутаций — и всё это вторым
	-- слоем поверх модели кристалла, загораживая его.
	--
	-- Флаг влияет ТОЛЬКО на подиум с УСТАНОВЛЕННЫМ кристаллом. На пустом
	-- подиуме табличка ("NO ORE INSTALLED") показывается всегда,
	-- независимо от этого значения: там нечего дублировать, а без неё
	-- подиум выглядел бы безымянной тумбой.
	--
	-- true вернёт прежнее поведение — код надписи никуда не делся и
	-- продолжает исправно формироваться.
	ShowPodiumStatusLabel = false,

	-- Как часто сервер перерисовывает табличку сейфа с таймером «до
	-- заполнения» (см. PassiveIncomeService:_startSafeTimerLoop). Секунды.
	-- Мельче 1 не имеет смысла: таймер показывается в часах/минутах.
	SafeTimerRefresh = 1,

