	--------------------------------------------------------------------------------
	-- 3D-ПОСТАНОВКА ОТКРЫТИЯ (по ТЗ: "камера отдаляется так, чтобы было
	-- видно и жеоду на наковальне, и игрока... удар молотком... 2-3 раза,
	-- ФОВ подскакивает как пружинка... после раскола жеода прокручивается
	-- и уменьшается, дроп разлетается кривыми, камера возвращается").
	-- ВАЖНО: экономика (что именно выпало) считается ТОЛЬКО сервером,
	-- как и раньше (см. GeodeService:OpenGeode, не тронут) — вся эта
	-- секция чисто визуальная, на CLIENT (см. GeodeUI.client.lua),
	-- разыгрывается ПОВЕРХ уже существующего 2D-тап-цикла, не вместо
	-- него: то же количество тапов (CrackTapCount выше), тот же момент
	-- отправки запроса серверу (последний засчитанный тап).
	--------------------------------------------------------------------------------
	-- ID анимации удара молотком (Humanoid). 0 — анимация не проигрывается
	-- (только перемещение/камера), пока не вставишь свой AnimationId (по
	-- ТЗ — "я просто вставлю айди анимки").
	HammerAnimationId = 0,

	-- Камера: радиус/высота орбиты вокруг игрока (по прямому запросу —
	-- "камера отдаётся и вращается вокруг игрока медленно") и скорость
	-- перехода FOV в начале.
	CameraBackOffset = 12, -- радиус орбиты
	CameraUpOffset = 7,    -- высота камеры над игроком на орбите
	CameraDollySeconds = 1.1,
	CameraFOVDefault = 70,
	CameraFOVCracking = 64, -- чуть уже во время ударов — фокус на жеоде

	-- Скорость вращения камеры вокруг игрока (радиан/сек) — по прямому
	-- запросу ("камера отдаётся и вращается вокруг игрока медленно").
	CameraOrbitSpeed = 0.35,

	-- FOV-"пружинка" на каждый засчитанный удар (см. ТЗ "резко но
	-- плавно") — тот же приём, что и у мини-игры шахты (см.
	-- Config.MineExpedition.HitFOVKick).
	HitFOVKick = -5,
	HitFOVKickSeconds = 0.2,

	-- Раскалывание (по прямому запросу — "будто ломается или трескается
	-- с партами вокруг"): сколько осколков разлетается от декоративной
	-- жеоды в момент раскола, чисто визуально.
	ShatterPieceCount = 7,
	ShatterFlightSeconds = 0.4,

	-- Разлёт дропа после раскола: сколько декоративных "капель" лута
	-- разлетается (не больше реального числа наград — если наград
	-- меньше, разлетается ровно столько, сколько есть), высота дуги
	-- полёта, время полёта, радиус разброса точек приземления вокруг
	-- игрока, и сколько секунд камера ждёт перед тем, как окончательно
	-- вернуться игроку в руки.
	--
	-- ПО ПРЯМОМУ ЗАПРОСУ ("сделай разлёт сильно привлекательнее") —
	-- капли теперь разлетаются НАМНОГО дальше (было 7 студов радиус,
	-- стало 16), НЕМНОГО медленнее и плавнее (время полёта 0.55 → 0.85,
	-- дуга выше — 6 → 9, так медленный полёт не выглядит вялым), и на
	-- приземлении слегка "приплющиваются" пружинкой (см. LandingSquash*
	-- ниже и spawnScatterDrop в GeodeUI.client.lua) — секунду шире и
	-- ниже, чем обычно, потом плавно назад к нормальной форме.
	ScatterMaxDrops = 8,
	ScatterArcHeight = 9,
	ScatterFlightSeconds = 0.85,
	ScatterRadius = 16,
	-- "Приплющивание" при приземлении — доля от нормального размера по
	-- вертикали/горизонтали в момент удара (0.6 = на 40% ниже и на 25%
	-- шире, чем обычно) и сколько секунд занимает пружинка туда-обратно.
	LandingSquashVertical = 0.6,
	LandingSquashHorizontal = 1.25,
	LandingSquashSeconds = 0.35,
	CameraReturnSeconds = 0.9,
	-- Через сколько секунд после раскола камера возвращается игроку
	-- В ЛЮБОМ случае, даже если не все капли лута ещё собраны — чтобы
	-- нельзя было залипнуть в катсцене, гоняясь за последней каплей.
	CameraReturnTimeout = 6,
}

--------------------------------------------------------------------------------
-- ВРЕМЕННЫЕ БАФФЫ ИЗ ЖЕОД (см. ТЗ, Config.Geodes.BuffChance выше и
-- BuffService.lua — там же подробно расписано, где именно каждый бафф
-- применяется). Amount — бонус СВЕРХ 1.0 для Money/Speed/Damage (0.5 =
-- +50%, здесь везде 1.0 = "х2", как и просили), и прямая ДОБАВКА к удаче
-- для Luck (см. комментарий в BuffService.lua про то, почему удача не
-- множится). Durations — пул длительностей в секундах, на каждый бафф
-- роллится случайно одна из них (по ТЗ: "на минуту, 5 минут").
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------
-- ИНВЕНТАРЬ (рюкзак + хотбар + кирки/скины)
--
-- ПРАВИЛА, согласованные напрямую:
--   • Руда подбирается ПРОСТО НАСТУПАНИЕМ на неё (не нужен промпт).
--   • Куда попадёт: тележка В РУКАХ → в тележку; иначе → в рюкзак.
--     (См. InventoryService:TryPickup — одна точка правды на оба случая.)
--   • Продавать можно И из рюкзака, И из тележки.
--   • Рюкзак защищён: при смерти игрока выпадает только DeathDropFraction
--     (25%) СЛУЧАЙНЫХ предметов, остальное остаётся.
--   • Слоты: BaseSlots + ExtraPouch.BonusSlots (+12), а InfinitePouch
--     снимает лимит вовсе.
--   • Хотбар: центральный слот ВСЕГДА кирка (клавиша F), по бокам —
--     обычные слоты 1..6 под руду; выбранная руда берётся в руки, над ней
--     висит её редкость. Зажать ЛКМ на другом игроке с рудой в руках —
--     подарить (см. GiftHoldSeconds).
--------------------------------------------------------------------------------
Config.Inventory = {
	BaseSlots = 24,        -- базовая вместимость рюкзака (стопки, см. StackSize)
	-- СТАРТОВЫЙ РЮКЗАК — пока не куплена первая тележка (Data.CartUnlocked).
	-- Держит в честных рамках продажу руды из рюкзака (см.
	-- Config.Bank.InventorySellEnabled): руками можно донести немного, а не
	-- заменить этим рейс тележкой. Расширяется до BaseSlots автоматически в
	-- момент покупки тележки (см. InventoryService:GetSlotCount).
	StarterSlots = 5,
	StackSize = 99,        -- сколько одинаковых предметов лежит в одной ячейке
	PickupRadius = 7.5,    -- стадов: насколько близко надо подойти, чтобы "наступить" на руду (было 4.5 — увеличено на ~65%)
	PickupCooldown = 0.08, -- сек между подборами, чтобы куча не всасывалась одним кадром
	-- Перелив ВСЕЙ руды в свою тележку, когда игрок ближе Config.Cart.
	-- DepositDistance к ней: по одному куску раз в столько секунд.
	CartAutoDepositInterval = 0.08,

	-- 25% случайного лута выпадает при смерти (по прямому запросу — рюкзак
	-- "по сути защищённая штука"). Остальное сохраняется.
	DeathDropFraction = 0.25,
	-- v10: при смерти руда реально падает на землю — не больше этого числа
	-- кусков, крутятся на месте и ждут, пока их подберут.
	DeathDropMaxItems = 5,
	DeathDropSpinSpeed = 2.5,

	-- Хотбар: 6 обычных слотов + центральный слот кирки (F).
	HotbarSlots = 6,
	PickaxeKey = Enum.KeyCode.F,

	-- Держать ЛКМ на игроке столько секунд, чтобы подарить ему предмет из
	-- руки. Достаточно долго, чтобы не дарить случайно в толпе.
	GiftHoldSeconds = 1.2,
	GiftMaxDistance = 18,

	-- Ярлык редкости над рудой в руках.
	HeldRarityBillboardHeight = 2.4,
}

--------------------------------------------------------------------------------
-- СКИНЫ КИРОК — небольшие баффы, чтобы у выбитых скинов был смысл (по
-- прямому запросу). Складываются с характеристиками самой кирки; скины
-- НЕ заменяют тир кирки, только слегка его подкручивают, поэтому бонусы
-- намеренно маленькие — скин не должен обгонять апгрейд.
--
-- Ключи = имена скинов из Config.Skins (см. ниже по файлу). Скин, не
-- перечисленный здесь, просто не даёт бонуса — это не ошибка.
--------------------------------------------------------------------------------
