-- БАФФЫ.
--
-- Множители добычи ("1.5x mining") убраны как неликвид: они ускоряли то,
-- что игрок и так делает, и на результат ролла не влияли никак — то есть
-- не меняли НИЧЕГО интересного. Их место заняли баффы, которые влияют
-- на то, ЧТО выпадает:
--
--   Luck           — сдвигает ролл руды к редким слотам тира;
--   MutationPotion — поднимает шанс мутаций выше, чем у обычной руды
--                    (см. MutationRoll.Roll → rollMultiplier);
--   Money/Speed    — оставлены, они честно полезны и понятны.
--
-- Description — текст всплывающей подсказки в панели баффов (см.
-- client/BuffBar.client.lua): игрок должен понимать, что именно ему дали.
Config.Buffs = {
	Order = { "Luck", "MutationPotion", "Money", "Speed" }, -- дроп жеод; Damage сюда не входит
	-- Урон — только из зелья торговца (Config.Potions), из жеод не падает;
	-- запись нужна панели бафов (BuffBar) для иконки и подписи.
	Damage = {
		DisplayName = "2X DAMAGE",
		Amount = 1.0,
		Rarity = "Rare",
		ImageId = 0,
		IconText = "DMG",
		Color = Color3.fromRGB(255, 90, 70),
		Description = "Doubles your pickaxe damage.",
	},
	Durations = { 60, 300 },

	Luck = {
