Config.Boulders = {
	--------------------------------------------------------------------------
	-- ВАЛУНЫ НА СВОЕЙ БАЗЕ (см. RockService:SetupPlot).
	--
	-- Обычные валуны стоят по карте на точках workspace.RubbleBoulderSpawnPoints
	-- и общие для всех. Эти — ЛИЧНЫЕ: по одному на каждый маркер
	-- BoulderMarkerN внутри PlotTemplate (обычный BasePart, как MineMarker;
	-- код прячет его сам). Именно они держат вход в шахту в начале игры и
	-- остаются на базе навсегда как способ добыть руду, не заходя внутрь.
	--
	-- ТИР. Растёт вместе с шахтой, НО никогда не уходит дальше, чем на
	-- Config.BoulderGame.MaxDiffWithPickaxe от кирки игрока. Без этой
	-- привязки база вставала бы намертво: валун на 2+ тира выше кирки
	-- физически не ломается ничем, кроме динамита (см. boulderHitsNeeded в
	-- RockService), и игрок с прокачанной шахтой, но отставшей киркой
	-- оставался бы с двумя вечными камнями у входа.
	--
	-- ДРОП. Денег НЕ дают вообще (в отличие от карты) — только руду своего
	-- тира и иногда жеоду. Причина простая: на первом тире обычный валун
	-- роняет сразу ~$67 (RewardMoneyByTier ниже), то есть новичок получал
	-- бы деньги на починку шахты, ни разу не дойдя до банка — и шаг
