--------------------------------------------------------------------------------
-- ЭКОНОМИКА v3: ДЕНЕЖНЫЙ ДРОП ЖЕОД И ВАЛУНОВ — в «полных тележках».
-- Раньше суммы были абсолютными и росли x10 за тип (как цены апгрейдов,
-- а не как доход): Crystal-жеода на старте давала до ~19 тележек, а на
-- поздних тирах денежный дроп почти ничего не значил. Теперь каждая сумма
-- = доля полной тележки пещеры, к которой относится жеода/валун
-- (Config.CartValue), поэтому награда одинаково ощутима на любом этапе.
-- Меняешь щедрость — правь только эти коэффициенты.
--------------------------------------------------------------------------------
local function niceMoney(value)
	value = math.max(1, value)
	if value < 100 then return math.max(1, math.floor(value + 0.5)) end
	local step = 10 ^ (math.floor(math.log10(value)) - 1)
	return math.floor(value / step + 0.5) * step
end

-- Естественный тир тележки для пещеры (9 тележек на 15 пещер) — для оценок.
function Config.NaturalCartTierForCave(cave)
	return math.clamp(1 + math.floor((cave - 1) * (#Config.CartTiers - 1) / (#Config.MineTiers - 1) + 0.5), 1, #Config.CartTiers)
end
-- Какой тип жеоды «родной» для пещеры: 10 типов растянуты на 15 пещер.
function Config.GeodeTypeIndexForCave(cave)
	cave = math.clamp(math.floor(tonumber(cave) or 1), 1, #Config.MineTiers)
	return math.clamp(1 + math.floor((cave - 1) * (#Config.Geodes.Order - 1) / (#Config.MineTiers - 1) + 0.5), 1, #Config.Geodes.Order)
end

Config.Geodes.MoneyInCarts = { 0.4, 1, 3 } -- малый / средний / джекпот
for index, geodeType in Config.Geodes.Order do
	local info = Config.Geodes.Types[geodeType]
	if info then
		-- Первая пещера, где этот тип жеоды становится «родным».
		local cave = #Config.MineTiers
		for candidate = 1, #Config.MineTiers do
			if Config.GeodeTypeIndexForCave(candidate) >= index then
				cave = candidate
				break
			end
		end
		local base = Config.CartValue(cave, Config.NaturalCartTierForCave(cave))
		info.Money = {}
		for slot, carts in Config.Geodes.MoneyInCarts do
			info.Money[slot] = niceMoney(base * carts)
		end
	end
end

-- 9-тировые шкалы (валуны, гоблины = тир кирки/тележки) → пещера 1..15.
function Config.CaveForNineTier(tier)
	tier = math.clamp(math.floor(tonumber(tier) or 1), 1, 9)
	return math.clamp(1 + math.floor((tier - 1) * (#Config.MineTiers - 1) / 8 + 0.5), 1, #Config.MineTiers)
end
-- Обратное: пещера → 9-тировая шкала (для гоблинов).
function Config.NineTierForCave(cave)
	cave = math.clamp(math.floor(tonumber(cave) or 1), 1, #Config.MineTiers)
	return math.clamp(1 + math.floor((cave - 1) * 8 / (#Config.MineTiers - 1) + 0.5), 1, 9)
end

-- v20: 0.6 → 0.25 — валуны давали за 10–15 сек больше, чем рейс в шахту.
Config.Boulders.MoneyInCarts = 0.25
-- v20: потолок одного ролла денег — доля полной тележки ТЕКУЩЕЙ пещеры
-- игрока. Не даёт фармить валуны намного выше своей пещеры (кирка дешевле
-- шахты). На «своих» тирах потолок почти не срабатывает.
Config.Boulders.MoneyCapInCarts = 0.5
Config.Boulders.RewardMoneyByTier = {}
for tier = 1, 9 do
	-- 9 тиров валунов (= тир кирки) растянуты на 15 пещер.
	local cave = math.clamp(1 + math.floor((tier - 1) * (#Config.MineTiers - 1) / 8 + 0.5), 1, #Config.MineTiers)
	Config.Boulders.RewardMoneyByTier[tier] = niceMoney(Config.CartValue(cave, Config.NaturalCartTierForCave(cave)) * Config.Boulders.MoneyInCarts)
end

--------------------------------------------------------------------------------
-- ЭКОНОМИКА v4: ПАССИВКА P1 — у каждого кристалла СВОЙ фиксированный доход.
--
-- Доход кристалла больше не зависит от тиров игрока. Он считается один раз
-- здесь от «родной» пещеры кристалла (где его жеода/валун становится
-- обычной находкой):
--   $/мин = Share × Config.IncomePerMinute(родная пещера, её тележка)
--           × Config.Economy.RealIncomeFactor
-- Share: руды жеоды 1/2/3 = GeodeShares, руды валунов = BoulderShare.
-- Сверху OreIncome.PerMinute домножает уровень ячейки, мутацию, перк
-- Safe Income и пасс 2x Safe Income. Сейф копит максимум
-- SafeCapTargetHours (3 ч).
--------------------------------------------------------------------------------
Config.Economy.RealIncomeFactor = 0.75 -- реальный игрок ≈ 75% идеального дохода (не каждая тележка на x3)
Config.Geodes.GeodeShares = { 0.16, 0.24, 0.34 }
Config.Geodes.BoulderShare = 0.40
Config.Geodes.BoulderOreOrder = { "Rubblegem", "Ironflake", "Coalheart", "Duskstone", "VerdantCore", "Emberite", "Frostvein", "Wyrmglass", "UmbralShard", "Titanheart" }

local function passiveBase(cave, share)
	local value = share * Config.IncomePerMinute(cave, Config.NaturalCartTierForCave(cave)) * Config.Economy.RealIncomeFactor
	return niceMoney(value)
end
for index, geodeType in Config.Geodes.Order do
	local info = Config.Geodes.Types[geodeType]
	if info then
		local cave = #Config.MineTiers
		for candidate = 1, #Config.MineTiers do
			if Config.GeodeTypeIndexForCave(candidate) >= index then
				cave = candidate
				break
			end
		end
		for slot, oreId in info.Ores or {} do
			local ore = Config.Geodes.Ores[oreId]
			if ore then
				ore.HomeCave = cave
				ore.BaseIncomePerMinute = passiveBase(cave, Config.Geodes.GeodeShares[math.clamp(slot, 1, #Config.Geodes.GeodeShares)])
				ore.IncomePerMinute = ore.BaseIncomePerMinute
			end
		end
	end
end
for index, oreId in Config.Geodes.BoulderOreOrder do
	local ore = Config.Geodes.Ores[oreId]
	if ore then
		local cave = math.clamp(1 + math.floor((index - 1) * (#Config.MineTiers - 1) / (#Config.Geodes.BoulderOreOrder - 1) + 0.5), 1, #Config.MineTiers)
		ore.HomeCave = cave
		ore.BaseIncomePerMinute = passiveBase(cave, Config.Geodes.BoulderShare)
		ore.IncomePerMinute = ore.BaseIncomePerMinute
	end
end

-- ВОСКЛИЦАТЕЛЬНЫЙ ЗНАК НАД ЦЕЛЬЮ АКТИВНОГО КВЕСТА (см. QuestMarker.client.lua).
-- Строится из партов через PlaceholderFactory.QuestMarker() — как и всё
-- остальное в проекте, заменяется своей моделью: положи Model с именем
-- "QuestMarker" в ReplicatedStorage/Assets, и код возьмёт её вместо
-- плейсхолдера.
--
-- Знак показывается ТОЛЬКО у квестов, у которых есть конкретный объект в
-- мире (см. таблицу Targets ниже). У счётных квестов вроде "заработай 100K"
-- или "продай пять тележек" никакой одной точки на карте нет, и знак для них
-- намеренно не рисуется — маркер должен что-то значить, а не висеть всегда.
Config.QuestMarker = {
	Enabled = true,
	Height = 5.5,            -- на сколько студов знак висит над целью
	BobAmplitude = 0.35,     -- амплитуда покачивания вверх-вниз, студы
	BobPeriod = 2.6,         -- период покачивания, секунды
	SpinPeriod = 6.0,        -- полный оборот вокруг своей оси, секунды
	Color = Color3.fromRGB(255, 215, 90),
	MaxVisibleDistance = 2000,
	RefreshInterval = 1.0,    -- как часто перепроверяем цель в мире
	-- v16: НАВИГАЦИЯ (client/QuestMarker.client.lua): трейл от ног до цели
	-- (тот же луч, что в обучении — Config.Tutorial.Trail*), знак над
	-- целью, расстояние, шеврон у ног, стрелка на краю экрана, если цель вне
	-- кадра. Ближе ArriveDistance — трейл прячется.
	TrailEnabled = true,
	ArriveDistance = 12,
	-- Цель по метрике — для дейликов и story-квестов без поля Nav.
	MetricTargets = {
		CartSales = "Bank", OreSold = "Bank", Cart70Sales = "Bank", X4Sales = "Bank", FullCartNoLoss = "Bank",
		BouldersBroken = "Boulder", GeodesOpened = "GeodeVault", OresCollected = "Mine", RareOres = "Mine",
		SafeCollected = "GeodeSafe", Upgrades = "UpgradeShopNPC", ChestsOpened = "PlotBase", ItemsPlaced = "PlotBase",
		MerchantBuys = "Merchant", Damage = "NearestPlayer", OreStolen = "NearestPlayer", CombatHits = "NearestPlayer",
		CrystalsGifted = "NearestPlayer", IslandsOwned = "IslandKeeper", PerksBought = "PrestigeCase", Rebirths = "RebirthNPC",
	},
	-- «Зачем» для дейликов по метрике (story-квесты берут своё поле Why).
	MetricWhy = {
		CartSales = "Sell at the bank.", OreSold = "Sell at the bank.", Cart70Sales = "Fill the cart to 70%+, then sell.",
		X4Sales = "A full cart sells at x3.", BouldersBroken = "Boulders glow around the map.", GeodesOpened = "Open geodes at your geode building.",
		OresCollected = "Mine ore in your cave.", RareOres = "Rare ore comes from your cave.", Upgrades = "Talk to the Experienced Miner.",
