--------------------------------------------------------------------------------
-- НАГРАДА ЗА FAVORITE + ЛАЙК ИГРЫ (см. src/server/Services/LikeRewardService.lua +
-- src/client/LikeRewardUI.client.lua) — окно с подарком, который "открывается"
-- на экране и предлагает добавить игру в избранное И лайкнуть её за скин +
-- жеоды. Независимо от Config.GroupReward ниже (своя награда, свой скин,
-- своя жеода, свой флаг "забрано" — DataService.LikeRewardClaimed).
--
-- ВАЖНО: у Roblox нет API, чтобы скрипт проверил, лайкнул ли игрок игру, или
-- программно открыл меню лайка — это ограничение платформы, не баг. Кнопка
-- Favorite настоящая (AvatarEditorService:PromptSetFavorite), а Like —
-- визуальное подтверждение "по доверию" (жмёт 👍 в самом окне, потом жмёт
-- "CLAIM"). Так делает подавляющее большинство игр с такой механикой на
-- Roblox — альтернативы через официальный API нет.
--------------------------------------------------------------------------------
-- v16: ТАБЛО ЦЕЛЕЙ ПО ЛАЙКАМ (server/Services/LikeGoalService.lua).
-- Число лайков игра прочитать не может (у Roblox нет такого API для
-- скриптов) — CurrentLikes обновляешь сам и публикуешь игру. Табло стоит
-- у спавна: Workspace/LikeGoalBoard (Part — на его лицевую сторону Front
-- кладётся SurfaceGui). Нет детали — табло ставится рядом с SpawnLocation.
--   Kind = "Code"  — на табло открывается промокод (Config.PromoCodes);
--   Kind = "Event" — ивент для всех: Money (×Multiplier к продаже) или
--                    Luck (как пасс 2x Luck). EndsAt = "YYYY-MM-DD" (UTC)
--                    или nil — пока не выключишь.
Config.LikeGoals = {
	Enabled = true,
	CurrentLikes = 0,
	Title = "👍 LIKE GOALS",
	Subtitle = "Like the game to unlock rewards for EVERYONE!",
	Goals = {
		{ Likes = 50,  Kind = "Code",  Code = "LIKES50", Text = "Secret code: free Rare Chest" },
		{ Likes = 100, Kind = "Event", Event = "Money", Multiplier = 2, Text = "x2 MONEY event", EndsAt = nil },
		{ Likes = 350, Kind = "Event", Event = "Luck", Multiplier = 2, Text = "x2 LUCK event", EndsAt = nil },
		{ Likes = 1000, Kind = "Text", Text = "New cave update!" },
	},
}

