-- ВТОРОЕ ОКНО-ПОДАРОК (см. src/server/Services/GroupRewardService.lua +
-- src/client/GroupRewardUI.client.lua) — та же анимация подарка, что и у
-- Config.LikeReward, но просит ДВА ДРУГИХ действия: лайкнуть игру И
-- вступить в группу (Config.LikeReward выше — про Favorite + лайк), за
-- отдельную независимую награду (свой скин, своя жеода, свой флаг "забрано"
-- — см. DataService.GroupRewardClaimed, никак не связан с LikeRewardClaimed).
-- У Group Join есть настоящий нативный промпт Roblox
-- (GroupService:PromptJoinAsync, появился в декабре 2025), у "лайка" как
-- обычно нет — см. подробный комментарий у Config.LikeReward выше, та же
-- логика тут (кнопка Like — чисто визуальное подтверждение на доверии).
--------------------------------------------------------------------------------
Config.GroupReward = {
	Enabled = true,
	-- v16 (G1): участник группы получает +IncomeBonus к продаже руды, пока
	-- состоит в группе (проверка при входе — GetGroupsAsync, и по кнопке),
