--------------------------------------------------------------------------------
-- МОНЕТКИ ПРИ ПРОДАЖЕ (см. BankService:spawnCoinBurst) — настоящие 3D-монетки
-- в мире (а не плоская 2D-анимация по экрану), в стиле Fortnite: выскакивают
-- рядом с игроком в момент оплаты, с лёгким зелёным трейлом, и тут же
-- залетают в игрока.
--------------------------------------------------------------------------------
Config.CoinFx = {
	-- МОНЕТКИ v3 — считаются на КЛИЕНТЕ (client/SellFx.client.lua), сервер
	-- шлёт только "откуда и сколько" (BankService:SpawnCoinBurst).
	-- КВАДРАТНЫЕ золотые плитки: вылетают фонтаном, кувыркаются, отскакивают
	-- от земли, короткая пауза — и магнитом к игроку, со звоном по нарастающей.
	--
	-- ПРОИЗВОДИТЕЛЬНОСТЬ: одна деталь на монету, все монеты двигаются одним
	-- workspace:BulkMoveTo за кадр, пул деталей, потолок MaxActive на экране
	-- и слияние частых россыпей (MergeWindow) — продажа целой тележки больше
	-- не заваливает кадр сотнями деталей.
	CoinColor = Color3.fromRGB(255, 196, 40),  -- читают и другие эффекты (гоблины, валуны)
	CoinSize = Vector3.new(0.9, 0.9, 0.18),    -- квадратная плитка: X/Y — сторона, Z — толщина
	MinCoins = 4,
	MaxCoins = 12,
	CoinsPerWeight = 1,       -- +монет за каждое начисление в окне дебаунса (Weight)
	MaxActive = 40,           -- потолок монет на экране одновременно
