-- Items — карточки магазина. Passes = геймпассы (покупаются один раз,
-- эффект навсегда — см. Config.GamePasses), Deals = разовые покупки
-- (деньги/расходники — см. Config.DevProducts/Config.Protection). ProductId
-- у каждой карточки НЕ дублирует число руками — берётся прямо из
-- Config.GamePasses/Config.DevProducts/Config.Protection ниже по тексту, то
-- есть Id прописываешь ОДИН раз (там, где заведён сам геймпасс/девпродукт),
-- а карточка сама подтягивает актуальное значение. Поля карточки:
--   Title       — надпись на карточке
--   PriceRobux  — цифра на кнопке цены — ЧИСТО ДЕКОРАТИВНЫЙ текст (реальную
--                 цену Roblox покажет сам в системном окне покупки после
--                 клика) — правь на то число Robux, которое реально
--                 поставишь в Creator Dashboard, просто чтобы карточка не
--                 врала игроку до клика.
--   ImageId     — числовой ID картинки (0 = картинки нет, обычный цветной
--                 прямоугольник со знаком "?" вместо неё)
--   ProductType — "GamePass" или "DevProduct" (откуда брать реальный Id)
--   ProductId   — 0, пока сам геймпасс/девпродукт ещё не создан в Creator
--                 Dashboard (см. Config.GamePasses/Config.DevProducts/
--                 Config.Protection выше по файлу — впиши Id ТУДА, сюда
--                 ничего вписывать не нужно, подтянется само). Пока 0 —
--                 клик по карточке просто предупредит в консоли и НИЧЕГО
--                 не купит (безопасно).
--   Badge       — необязательная плашка в углу карточки ("NEW" и т.п.),
--                 nil/"" — плашка скрыта.
--   GrantMoney  — ТОЛЬКО для СВОИХ НОВЫХ карточек с ProductType =
--                 "DevProduct", которых ещё нет ни в Config.DevProducts, ни
--                 в Config.Protection (готовые Money Pack'и/щит ниже в этом
--                 ProductId уже сами знают, что выдавать — см.
--                 MonetizationService:ProcessReceipt, GrantMoney им не
--                 нужен). Добавишь СВОЮ карточку сверх этих десяти — тогда
--                 GrantMoney и пригодится.
--------------------------------------------------------------------------------
-- Подпись денежной карточки магазина СЧИТАЕТСЯ ИЗ САМОЙ СУММЫ, а не пишется
-- руками. Раньше Title был константной строкой ("$250K Cash") рядом с
-- Amount = 250000 в Config.DevProducts — две независимые копии одного числа,
-- которые при любой правке баланса разъезжались, и магазин начинал обещать
-- одну сумму, а выдавать другую. Для платного товара это уже не косметика.
--
-- Отдельная локальная функция, а не NumberFormat.abbreviate: Config не
-- должен ничего требовать (require) — его самого требуют почти все модули
-- проекта, и любая зависимость отсюда рискует замкнуть цикл загрузки.
local function cashLabel(amount)
	amount = tonumber(amount) or 0
	local function trim(value, suffix)
		-- 6.5 → "6.5", 300.0 → "300" (без болтающегося ".0")
		local text = ("%.1f"):format(value)
		text = text:gsub("%.0$", "")
		return "$" .. text .. suffix .. " Cash"
	end
	if amount >= 1e12 then return trim(amount / 1e12, "T") end
	if amount >= 1e9 then return trim(amount / 1e9, "B") end
	if amount >= 1e6 then return trim(amount / 1e6, "M") end
	if amount >= 1e3 then return trim(amount / 1e3, "K") end
	return "$" .. ("%d"):format(amount) .. " Cash"
end

