--------------------------------------------------------------------------------
-- КНОПКИ БЫСТРОГО ДОСТУПА К ГЕЙМПАССАМ (ScreenGui "GamepassQuickBar", см.
-- tools/BuildAllUI.lua) — маленький ряд иконок рядом с хотбаром/
-- кнопкой щита. Клик по кнопке сразу открывает системное окно покупки
-- этого геймпасса (Config.GamePasses[Key].Id) — БЕЗ похода в общий
-- магазин. Если пасс уже куплен — кнопка подсвечивается золотым и клик
-- по ней ничего не открывает (см. CustomCartUI.client.lua, читает
-- атрибут игрока "Owns_"..Key, см. MonetizationService).
--
-- ПОКАЗЫВАЕТСЯ ПО ОДНОЙ КНОПКЕ ЗА РАЗ, ВРЕМЕНАМИ — не постоянный ряд из
-- 5+1 кнопок (мешал бы обзору/бою), а редкая "реклама" одного случайного
-- ещё не купленного пасса (или разового девпродукта из DevProductAd ниже,
-- он не "куплен раз навсегда" — участвует в ротации всегда): появилась
-- (с лёгкой тряской — ShakeDuration — чтобы привлечь взгляд) на
-- ShowDuration секунд → если за это время НЕ купили, укатывается вниз
-- (RollDownOffset, крутится при этом) и исчезает → пауза HideDuration
-- секунд → снова появляется (другая, случайно). Если все геймпассы уже
-- куплены — ничего не показывается (девпродукт всё равно продолжает
-- участвовать в ротации, ему "куплен" не бывает).
--------------------------------------------------------------------------------
Config.QuickBar = {
	StaticPassIcons = false,
	Passes = {
		{ Key = "DoubleCash", Emoji = "💰", ImageId = 0 },
		{ Key = "DoubleLuck", Emoji = "🍀", ImageId = 0 },
		{ Key = "OreMagnet", Emoji = "🧲", ImageId = 0 },
		{ Key = "ExtraPouch", Emoji = "🎒", ImageId = 0 },
		{ Key = "GeodeMaster", Emoji = "🪨", ImageId = 0 },
		{ Key = "DemolitionExpert", Emoji = "🧨", ImageId = 0 },
		{ Key = "CartGuard", Emoji = "🛡️", ImageId = 0 },
		{ Key = "FastSmelter", Emoji = "⚡", ImageId = 0 },
		{ Key = "RocketPickaxe", Emoji = "🚀", ImageId = 0 },
		{ Key = "DoubleSafe", Emoji = "🏦", ImageId = 0 },
	},

	-- Отдельная реклама РАЗОВОГО товара (девпродукт, не геймпасс) — тот же
	-- ProductId, что и у карточки "ShieldExtensionDeal" в Config.Shop.Items
	-- (Config.Protection.PaidProductId), просто ещё и всплывает в этой
	-- быстрой ротации, а не только лежит в магазине.
	DevProductAd = {
		Key = "ShieldExtension",
		Emoji = "🛡️+",
		ImageId = 0,
		Title = ("Shield +%ds"):format(Config.Protection.PaidDuration),
	},

	-- "СКИП РЕБЁРТА" (см. Config.DevProducts.RebirthSkip) — В ОТЛИЧИЕ от
	-- остальных кнопок здесь, продукт не один фиксированный: цена растёт
	-- по номеру ребёрта игрока (GetRebirths+1), клиент сам выбирает нужный
	-- индекс RebirthSkip в момент клика (см. CustomCartUI.client.lua).
	-- ПОКАЗЫВАЕТСЯ ТОЛЬКО КОНТЕКСТНО (принудительно, как GoldenShield/
	-- FastMining) — когда у игрока прокачаны все 3 ветки до тир-капа, но не
	-- хватает денег на сам ребёрт (см. RebirthService — атрибут
	-- "NeedsRebirthSkip"). В обычную случайную ротацию НЕ участвует: показ
	-- ради показа не имеет смысла, если ребёрт всё равно не готов.
	RebirthSkipAd = {
		Key = "RebirthSkip",
		Emoji = "♻️",
		ImageId = 0,
		Title = "Prestige Skip",
	},

	ShowDuration = 30,     -- сколько секунд подряд видна ОДНА кнопка, прежде чем укатится вниз, если её не купили
	HideDuration = 45,     -- пауза (кнопок нет вообще) между показами
	ShakeDuration = 0.5,   -- сколько длится лёгкая тряска при появлении кнопки
	RollDownOffset = 140,  -- на сколько пикселей вниз укатывается кнопка, если её не купили за ShowDuration
	HintImageId = 0, -- изображение вместо "?" над quick-bar кнопкой
	OwnedImageId = 0, -- изображение вместо галочки купленного пасса
}

--------------------------------------------------------------------------------
-- РЕФЕРАЛЬНАЯ СИСТЕМА — бонус к деньгам за друзей (настоящих Roblox-друзей,
-- не отдельных инвайт-кодов), которые находятся на ТОМ ЖЕ сервере прямо
-- сейчас. Считается сервером через Player:IsFriendsWith при каждом входе/
-- выходе игрока (см. MonetizationService:RecomputeReferralGraph) — приходить
-- заново не нужно, эффект живой весь сеанс, пока друг в сервере.
--
-- Множитель НЕЗАВИСИМ от платных x2/x4/x6/x8 геймпассов
-- (MonetizationService:GetCashMultiplier) и умножается на него, а не
-- складывается — так покупка кэш-пасса не "съедает" честно заработанный
-- реферальный бонус и наоборот.
--
-- MoneyMultiplierPerFriend — на сколько вырастает множитель за КАЖДОГО
-- друга (аддитивно между собой, чтобы не улетать в космос при большой
-- пачке друзей): 1 друг → x2, 2 друга → x3, при MoneyMultiplierPerFriend=1.
-- MaxFriends — потолок учитываемых друзей одновременно.
--
-- PromptInterval — раз во сколько секунд каждому игроку показывается
-- Toast-напоминание "пригласи друзей" (см. MonetizationService — обычный
-- Services.NotifyService:Show, тот же тост, что и у "не хватает денег" и
-- т.п., с кнопкой-действием "Invite", открывающей системное окно
-- приглашения). Не показывается, пока игрок уже играет с максимумом
-- учитываемых друзей (MaxFriends) — рекламировать уже нечего.
--------------------------------------------------------------------------------
Config.Referral = {
	MoneyMultiplierPerFriend = 1.0,
	MaxFriends = 3,
	PromptInterval = 360, -- 6 минут
}

