	-- за сессию, а не за календарь. Поэтому ничего не хранится в профиле —
	-- отметки о выданных ступенях живут в памяти сервера, и обмануть их
	-- перезаходом бессмысленно (перезаход обнуляет и таймер).
	--
	-- Seconds — сколько надо наиграть; порядок строго по возрастанию.
