--------------------------------------------------------------------------------
-- СООБЩЕНИЕ В ЧАТ О ЗАХОДЕ ИГРОКА
--
-- Зачем это не косметика: часть квестов (Config.Quests, поле RequiresPlayers)
-- физически не проходится в одиночку и на пустом сервере скрыта — см.
-- QuestService. Строка «X joined the server» — это одновременно и сигнал
-- «сервер ожил», и объяснение, откуда вдруг взялись новые квесты, которых
-- минуту назад не было.
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------
-- ЗАГРУЗКА ПЕРЕД КАТСЦЕНОЙ
--
-- ЧТО БЫЛО. LoadingScreen ждал ContentProvider:PreloadAsync по ВСЕМУ
-- game:GetDescendants() — до 15 секунд — и только потом разрешал катсцене
-- стартовать. Плюс до этого ждал участок (5 сек) и стабилизацию билбордов
-- (2 сек). В худшем случае игрок смотрел в ЧЁРНЫЙ ЭКРАН 22 секунды, потом
-- ещё ~10 секунд катсцену, и только затем получал управление.
--
-- ПОЧЕМУ ЭТО ДОРОГО. По измерениям индустрии каждая секунда не-геймплея в
-- первые минуты стоит примерно 2-3% новой когорты, а обязательная
-- 15-секундная катсцена — около 5% всех новых игроков ещё до первого
-- нажатия. Чёрный экран стоит столько же, но не даёт вообще ничего взамен.
--
-- ЧТО СТАЛО. Предзагрузка больше НЕ БЛОКИРУЕТ: она уходит в фон и
-- продолжается уже во время катсцены. Ждём только короткое окно
-- CriticalWaitSeconds, чтобы успели прилететь ближайшие ассеты сцены.
-- Roblox и так дорисовывает недогруженные текстуры по мере готовности —
-- ради этого держать игрока в черноте лишние 15 секунд смысла нет.
--------------------------------------------------------------------------------
Config.Loading = {
	-- Сколько ждать перед стартом катсцены. Не «сколько грузить» — грузиться
	-- продолжает в фоне, — а именно сколько игрок смотрит в черноту.
	CriticalWaitSeconds = 1.5,

	-- Аварийный потолок на фоновую предзагрузку: поток не должен жить вечно,
	-- если PreloadAsync где-то залип на битом ассете.
	BackgroundTimeout = 30,
}

Config.JoinAnnounce = {
	Enabled = true,
	-- Первого игрока на сервере объявлять некому — сообщение увидел бы он
	-- сам, про самого себя, в пустом мире. Начинаем со второго.
	MinPlayers = 2,
	NameColor = Color3.fromRGB(120, 220, 255),
	TextColor = Color3.fromRGB(215, 220, 230),
	JoinSuffix = " joined the server",
}

--------------------------------------------------------------------------------
-- ЭКРАН ВОЗВРАЩЕНИЯ («ПОКА ТЕБЯ НЕ БЫЛО»)
--
-- Один экран вместо четырёх разрозненных всплывашек. Раньше офлайн-доход
-- сейфа приходил отдельным тостом через 6 секунд после захода
-- (PassiveIncomeService:SetupPlot), стрик жил в своём меню, а офлайн-руды не
-- было вовсе — игрок не собирал эти события в одно «меня тут ждали».
--------------------------------------------------------------------------------
Config.ReturnScreen = {
	Enabled = true,
	-- Не показывать, если игрока не было меньше этого времени: перезаход
	-- из-за краша/телепорта не должен открывать торжественный экран.
	MinOfflineSeconds = 300, -- 5 минут
	-- Задержка перед показом: у клиента ~6000 строк UI, и слушатель
	-- появляется не мгновенно (та же причина, по которой старый тост сейфа
	-- ждал 6 секунд). Плюс экран не должен налезать на конец катсцены.
	ShowDelay = 2.0,
	-- Сколько секунд экран висит сам, если игрок не нажал кнопку.
	AutoCloseAfter = 20,
	Title = "WHILE YOU WERE AWAY",
	ButtonText = "COLLECT ALL",
}

Config.Debug = {
	-- Показывает полупрозрачный ПАРАЛЛЕЛЕПИПЕД перед атакующим при каждом
	-- взмахе киркой — теперь это ТОЧНАЯ визуализация реальной геометрии
	-- попадания (см. Config.Combat.HitboxSize/HitboxForwardOffset и
	-- findVictim в CombatService), не просто прикидка для VFX. ОТКЛЮЧЕНО
	-- по умолчанию — это чисто отладочный визуал для проверки хитбоксов
	-- при разработке, в релизе игроки его видеть не должны. Включай сам
	-- обратно (true), только если нужно снова что-то проверить руками.
	ShowCombatHitbox = false,
	CombatHitboxLifetime = 0.6,

	-- ПРИНУДИТЕЛЬНО показывать баннер стартового пака справа посередине
	-- экрана, игнорируя все три обычных условия (новый ли игрок, не истекло
	-- ли окно OfferWindowSeconds, не куплен ли пак уже).
	--
	-- Нужен именно для ПРОВЕРКИ: на своём аккаунте, который уже играл, все
	-- три условия ложны (FirstJoinedAt в далёком прошлом, окно давно
	-- закрыто), поэтому баннера не видно — и это легко спутать с тем, что
	-- он "сломан". Включи на время проверки, перед релизом верни false.
	-- ВЫКЛЮЧЕНО. Стояло true — а это значит, что баннер платного пака
	-- показывался В ПРОДЕ вообще всем подряд: и тем, кто играет полгода
	-- (окно OfferWindowSeconds давно истекло), и после того, как окно
	-- закрылось. Куплённым игрокам он и раньше не показывался (проверка
	-- StarterPackClaimed стоит первой и forceOffer её не обходит), но
	-- «вечное срочное предложение» у старых игроков — это ровно тот вид
	-- давления, который убивает доверие к магазину.
	--
	-- Вдобавок флаг теперь физически не может утечь в релиз: см.
	-- StarterPackUI.client.lua — forceOffer учитывается ТОЛЬКО в Studio
	-- (RunService:IsStudio()). Даже если оставить здесь true и опубликовать,
	-- живые игроки этого не увидят.
	ForceStarterPackOffer = false,
}

