-- клиенте, если маркеров нет вообще — см. CustomCartUI.client.lua). Вся
-- математика — там же (единственный клиентский скрипт в проекте). Поворот
-- и растяжение руки считаются ТОЧНО, без сглаживания и без верхнего предела
-- растяжения — рука должна быть прицеплена к тележке идеально всегда, без
-- зазоров, поэтому тут нет числовых настроек на подкрутку.
