--------------------------------------------------------------------------------
-- ОСТРОВА ПРОГРЕССИИ (см. server/Services/IslandService.lua,
-- client/IslandUI.client.lua, ISLANDS_GUIDE.md).
--
-- Наковальня жеод, подиум кристалла с сейфом, плавильня и ребёрт — ПОКУПКИ
-- у НПС в центре мира (Island Keeper). Покупка поднимает из-под земли
-- рядом с участком игрока свой остров.
--   Anvil   — наковальня: открытие жеод.
--   Income  — подиум кристалла + сейф (пассивный доход).
--   Smelter — плавильня: ОДНА руда → слиток той же руды с теми же
--             мутациями, цена × ValueMultiplier.
-- Ребёрт открывается только когда куплены ВСЕ острова из RebirthRequires.
--
-- ГДЕ СТОИТ ОСТРОВ. В PlotTemplate кладёшь деталь-маркер (имя — PlotMarker
-- ниже). PrimaryPart твоего макета острова встанет РОВНО в этот маркер —
-- позицией и поворотом. Поворот можно задать без Rotate: рядом деталь
-- "<ИмяМаркера>Look" — маркер "смотрит" на неё. Нет маркера — остров
-- встаёт в ряд позади участка (BehindDistance/Spacing).
--
-- КАК ВЫГЛЯДИТ ОСТРОВ. Макет — Model в ReplicatedStorage.Assets (имя —
-- Model ниже) с НАЗНАЧЕННЫМ PrimaryPart. Всё внутри (земля, декор, мосты
-- к участку) — твоё, код ничего не добавляет. Внутри макета —
-- маркеры построек (детали, лежащие НА поверхности; постройка встаёт на
-- нижнюю грань маркера, "<Имя>Look" — куда постройка смотрит лицом):
--   Anvil:   StationMarker            — наковальня (Assets/GeodeBuilding)
--   Income:  PodiumMarker, SafeMarker — подиум (Assets/GeodePodium) и сейф (Assets/GeodeSafe)
--   Smelter: StationMarker            — плавильня (Assets/Smelter, промпт на детали "Mouth")
-- Нет макета — строится простой остров-плейсхолдер (без мостов).
--
-- Прочие ассеты: Ingot_<КлючРуды> или общий "Ingot" — модель слитка
-- (общий перекрашивается в цвет руды); IslandKeeperNPC — модель НПС.
-- Место НПС: workspace.IslandKeeperMarker (+ IslandKeeperMarkerLook),
-- иначе рядом с банком (KeeperOffset).
--------------------------------------------------------------------------------
Config.Islands = {
	Enabled = true,
	Order = { "Anvil", "Income", "Smelter" },
	RebirthRequires = { "Anvil", "Income", "Smelter" },

	-- Старые игроки не должны терять то, чем уже пользовались: кто открывал
	-- жеоды / ставил кристалл — получает Anvil+Income бесплатно, у кого уже
	-- есть ребёрты — получает все острова. Выполняется один раз на профиль.
	GrandfatherExistingPlayers = true,

	Definitions = {
		Anvil = {
			DisplayName = "Anvil Island",
			Description = "Unlocks geode opening. Crack geodes to find crystals.",
			Tagline = "OPEN GEODES HERE",
			-- Что даёт — строки на экране выбранного улучшения у НПС.
			Perks = { "Open geodes from your vault", "Find crystals for your Income Island", "Needed for Prestige" },
			Cost = 250, -- v3: доступна сразу после первых рейсов
			Color = Color3.fromRGB(120, 170, 255),
			Icon = "⚒",
			Model = "Island_Anvil",          -- макет в ReplicatedStorage.Assets
			PlotMarker = "IslandAnvilMarker", -- маркер в PlotTemplate
		},
		Income = {
			DisplayName = "Income Island",
			Description = "Crystal podium + money safe. Your crystal earns money even while you're offline.",
			Tagline = "CRYSTAL INCOME + MONEY SAFE",
			Perks = { "Put a crystal on the podium", "It earns money — even offline", "Collect the cash from the safe", "Needed for Prestige" },
			Cost = 1500, -- v3
			Requires = "Anvil",
			Color = Color3.fromRGB(95, 230, 130),
			Icon = "$",
			Model = "Island_Income",
			PlotMarker = "IslandIncomeMarker",
		},
		Smelter = {
			DisplayName = "Smelter Island",
			Description = "Smelt ore into ingots worth x10. Rarer ore takes longer — up to 10 minutes.",
			Tagline = "SMELT ORE INTO x10 INGOTS",
			Perks = { "Ore → ingot worth x10", "Keeps the ore and its mutations", "Upgrade to smelt up to 5 ores at once", "Needed for Prestige" },
			Cost = 5000, -- v3: к пещере 3-4, до первого ребёрта
			Color = Color3.fromRGB(255, 140, 60),
			Icon = "🔥",
			Model = "Island_Smelter",
			PlotMarker = "IslandSmelterMarker",
		},
	},

	-- Подписи над островами. Их видит ТОЛЬКО владелец (рисует его клиент,
	-- см. IslandUI). LabelHeight — на сколько студов ВЫШЕ верхней точки
	-- острова висит подпись: высоко, чтобы читалась, когда смотришь в небо.
	LabelHeight = 45,
	LabelMaxDistance = 1500,

	-- Раскладка по умолчанию, если маркеров в PlotTemplate нет (в системе
	-- координат участка: -Z смотрит на банк, "позади участка" — это +Z).
	BehindDistance = 16,
	Spacing = 24,
	Radius = 10,           -- радиус площадки у острова-плейсхолдера
	RiseSeconds = 3.2,     -- сколько остров выезжает из-под земли
	RiseDepth = 16,        -- минимум; остров всегда уходит под землю целиком

	-- НПС в центре мира.
	KeeperName = "Island Keeper",
	KeeperOffset = Vector3.new(-30, 0, 0), -- от банка, если нет IslandKeeperMarker
	KeeperPromptDistance = 12,

	Smelter = {
		-- Уровни печи: [1] — сразу после покупки острова, дальше — улучшения
		-- в карточке плавильни у Island Keeper. Slots — сколько руды плавится
		-- ОДНОВРЕМЕННО, SpeedMultiplier — множитель времени (меньше = быстрее).
		-- Каждый уровень — СВОЙ вид печи (Assets/Smelter_Level<N>, иначе
		-- плейсхолдер уровня) и катсцена "старая сжимается → новая вырастает".
		-- Слиток всё так же переплавляется только ОДИН раз.
		Levels = {
			{ Name = "Clay Furnace", Slots = 1, SpeedMultiplier = 1.0 },
			{ Name = "Brick Furnace", Slots = 2, SpeedMultiplier = 0.95, Cost = 25000 },
			{ Name = "Iron Forge", Slots = 3, SpeedMultiplier = 0.9, Cost = 150000 },
			{ Name = "Magma Foundry", Slots = 5, SpeedMultiplier = 0.85, Cost = 800000 },
		},
		-- Время плавки растёт с редкостью: от MinSeconds у самой простой руды
		-- до MaxSeconds у самой редкой (позиция в Config.OreChain). TimeCurve
		-- > 1 — простая руда плавится заметно быстрее, долго ждать приходится
		-- именно за редкую (за которую x20 и стоит ждать).
		MinSeconds = 60,
		MaxSeconds = 600,
		TimeCurve = 1.4,
		ValueMultiplier = 10, -- v3: было x20 — слиток ещё и идёт через комбо тележки, x20 обесценивал рейсы
		ReadyText = "SMELT SUCCESSFUL!",
		PromptDistance = 10,
	},
}


