-- 4) МИНИ-ИГРА ВАЛУНОВ ---------------------------------------------------------
-- Первый удар киркой по валуну открывает панель справа от него: бегунок
-- ходит вверх-вниз, клик = удар с оценкой (Промах/Хорошо/Идеально).
-- Сколько ударов нужно — по разнице «тир валуна − тир кирки».
Config.BoulderGame = {
	Enabled = true,
	-- v14: ТЯЖЁЛЫЕ УДАРЫ. Кликов меньше (2/3/5 вместо 3/5/10), но каждый
	-- удар — событие: замах → хитстоп → FOV-панч → тряска → трещины.
	-- Сила удара зависит от попадания (GradePower): PERFECT бьёт вдвое
	-- сильнее обычного, поэтому идеальная серия ломает валун быстрее.
	HitsByDiff = { [-1] = 2, [0] = 3, [1] = 5 }, -- ≤ -2 → 1 удар без мини-игры
	InstantBelowDiff = -2,   -- валун на 2+ тира слабее — ломается с одного удара
	MaxDiffWithPickaxe = 1,  -- на 2+ тира сильнее — только динамитом
	StrikeCooldown = 0.95,   -- сек между ударами: замах+удар+откат должны доиграть
	GradePower = { Miss = 0.55, Good = 1, Perfect = 2 }, -- множитель прогресса удара
	-- Задержка от клика до «контакта» кирки с камнем. Сервер применяет урон
	-- ровно через это время, клиент в этот момент даёт хитстоп/FOV/тряску.
	ImpactDelay = 0.32,
	WindupFovDelta = -4,     -- FOV на замахе (отрицательное — наезд)
	HitStop = { Miss = 0.03, Good = 0.07, Perfect = 0.12 }, -- стоп-кадр на контакте, сек
	-- Замедление анимации персонажа во время удара (множитель скорости):
	-- замах → стоп-кадр (HitStop) → разгон → финальный удар почти замирает.
	AnimSlow = { Windup = 0.45, Recover = 0.55, RecoverSeconds = 0.2, Final = 0.15 },
	-- v20: после замедления анимация НЕ обрывается и не «щёлкает» обратно:
	-- плавно разгоняется до CatchUp (догоняет потерянное время), держит его
	-- CatchUpSeconds и мягко возвращается к обычной скорости за SettleSeconds.
	AnimRamp = { RampSeconds = 0.12, CatchUp = 1.3, CatchUpSeconds = 0.25, SettleSeconds = 0.2 },
	FovKick = { Miss = 2, Good = 7, Perfect = 12 },
	CameraShake = { Miss = 0.15, Good = 0.45, Perfect = 0.8 }, -- студы
	-- Финальный удар: слоу-мо (камера «замирает» и наезжает) перед разлётом.
	FinalPause = 0.55,
	FinalFovDelta = -14,
	-- Стадии трещин (подсветка изнутри): порог прогресса → яркость.
	CrackStages = { 0.25, 0.5, 0.75 },
	-- Анимация тяжёлого замаха (необязательно, 0 = обычный взмах кирки).
	StrikeAnimationId = 0,
	-- Серия PERFECT подряд: с Streak.Min — доп. ролл лута и бонус к шансу
	-- реликвии (RelicBonusPerStreak за каждый PERFECT сверх Min).
	Streak = { Min = 2, ExtraRolls = 1, RelicBonusPerStreak = 0.25 },
	RunnerCyclesPerSecond = 0.5, -- полных проходов бегунка вверх-вниз в секунду (v9: медленнее)
	RunnerSpeedPerTier = 0.03,   -- валун тяжелее → бегунок быстрее
	GoodWidth = 0.36,        -- доли высоты полосы (v9: шире — проще попасть)
	PerfectWidth = 0.12,
	Grades = { Miss = 0, Good = 0.6, Perfect = 1 },
	-- Итог = средняя оценка всех своих ударов по этому валуну.
	Results = {
		{ Min = 0.85, Label = "PERFECT BREAK!", MoneyMult = 1.3, ExtraRolls = 1, ChestMult = 2.5, Color = Color3.fromRGB(255, 215, 80) }, -- v20: MoneyMult было 1.6
		{ Min = 0.5,  Label = "GOOD BREAK",     MoneyMult = 1.0, ExtraRolls = 0, ChestMult = 1.0, Color = Color3.fromRGB(120, 255, 150) },
		{ Min = 0,    Label = "ROUGH BREAK",    MoneyMult = 0.6, ExtraRolls = 0, ChestMult = 0.5, Color = Color3.fromRGB(200, 200, 210) },
	},
	SessionRange = 24,       -- дальше отошёл — мини-игра закрывается
	SessionIdleTimeout = 10,
	LatencyWindow = 0.6,     -- сервер сверяет позицию бегунка за это окно (пинг)
	Tolerance = 0.05,
	UiVersion = 2, -- v9: карточка дропа в билдере
}

