-- v14 — КАТСЦЕНА ЖЕОДЫ (client/GeodeUI.client.lua)
--
-- Игрок встаёт перед наковальней лицом к ней, в правой руке — молот
-- (ReplicatedStorage.Assets.GeodeHammer: Model/Part/Tool; ручка — часть
-- "Handle" или PrimaryPart, опционально Attachment "Grip"). Каждый клик
-- = один взмах анимацией Config.Geodes.HammerAnimationId (НЕ в цикле).
-- Контакт молота с жеодой — по маркеру анимации ImpactMarker, а если его
-- нет — через ImpactDelay. На каждом контакте FOV «панчит» сильнее
-- предыдущего, камера трясётся, жеода трескается. Последний удар — слоу-мо,
-- вспышка, раскол.
--------------------------------------------------------------------------------
Config.GeodeCutscene = {
