-- v14 — ТОТЕМЫ, ДЕКОР И РЕЛИКВИИ НА БАЗЕ (см. BaseDecorService, PlaceableCatalog)
--
-- Всё лежит в ОБЫЧНОМ инвентаре (data.Gear, вкладки TOTEMS/DECOR/RELICS).
-- Взял в руку → призрак следует за курсором (R — поворот), клик —
-- поставить. Только на землю своего участка (shared/GroundCheck), сколько
-- угодно штук. Поднять — ЗАЖАТЬ E у предмета (PickupHoldDuration) →
-- обратно в инвентарь. Позиции хранятся относительно участка.
--
-- ТОТЕМЫ (тиры 1..10, баффы действуют, пока тотем стоит на базе; ставить
-- можно сколько угодно, суммарный эффект ограничен потолками Caps):
--   Fortune — удача +2% за тир (T1 +2% ... T10 +20%);
--   Ember   — доход с продажи +1% за тир (T10 = +10%);
--   Quake   — базовые валуны респавнятся быстрее: −6% времени за тир;
--   Prism   — шанс ОДНОЙ конкретной мутации ×(1 + 15% за тир).
--------------------------------------------------------------------------------
Config.Placeables = {
	MinSpacing = 2.2,
	GridStep = 0.5,
	RotateStep = 45,
	PickupHoldDuration = 1.2,
	PlaceRange = 60,            -- как далеко от игрока можно ставить
	-- v14.4: ставить можно на ЛЮБУЮ поверхность участка. На поверхности
	-- положе UprightSlope (градусы) предмет стоит вертикально, на более
	-- крутой (стена, склон, потолок) — прилипает к ней по нормали.
	UprightSlope = 40,
	-- Территория участка = весь прямоугольник PlotTemplate + этот запас, стадов.
	PlotMargin = 1,
	Caps = { Luck = 0.5, Income = 0.5, BoulderRespawn = 0.7, Mutation = 2.0 },
	TierRarity = { "Common", "Common", "Uncommon", "Uncommon", "Rare", "Rare", "Epic", "Epic", "Legendary", "Mythic" },
	TierColors = {
		Color3.fromRGB(190, 190, 190), Color3.fromRGB(215, 215, 215),
		Color3.fromRGB(110, 230, 120), Color3.fromRGB(80, 210, 100),
		Color3.fromRGB(90, 170, 255), Color3.fromRGB(60, 130, 255),
		Color3.fromRGB(190, 100, 255), Color3.fromRGB(160, 60, 240),
		Color3.fromRGB(255, 190, 50), Color3.fromRGB(255, 70, 100),
	},
	-- v4: ЦЕНЫ ФИКСИРОВАННЫЕ. Цена тотема = TierPrices[тир] × PriceMult типа.
	-- Тир «привязан» к пещере (TierHomeCave): цена тира ≈ 6 минут дохода в
	-- его родной пещере. Торговец показывает тотемы тиров [свой-1 … свой+1],
	-- где «свой» — TotemTierForCave(пещера игрока).
	TierPrices = { 280, 580, 1900, 2800, 8200, 27000, 41000, 110000, 190000, 430000 },
	TierHomeCave = { 1, 2, 4, 5, 7, 9, 10, 12, 13, 15 },
	TotemTypes = {
		Fortune = { DisplayName = "Fortune Totem", Icon = "🍀", Color = Color3.fromRGB(110, 235, 120), Effect = "Luck",           PerTier = 0.02, PriceMult = 1.0, Asset = "Totem_Fortune" },
		Ember   = { DisplayName = "Ember Totem",   Icon = "🔥", Color = Color3.fromRGB(255, 130, 50),  Effect = "Income",         PerTier = 0.01, PriceMult = 1.5, Asset = "Totem_Ember" },
		Quake   = { DisplayName = "Quake Totem",   Icon = "🪨", Color = Color3.fromRGB(170, 140, 110), Effect = "BoulderRespawn", PerTier = 0.06, PriceMult = 0.8, Asset = "Totem_Quake" },
		Prism   = { DisplayName = "Prism Totem",   Icon = "🔮", Color = Color3.fromRGB(200, 120, 255), Effect = "Mutation",       PerTier = 0.15, PriceMult = 1.2, Asset = "Totem_Prism" },
	},
	TotemOrder = { "Fortune", "Ember", "Quake", "Prism" },
	-- На какие мутации продаются Prism-тотемы (по одному виду на мутацию).
	PrismMutations = { "Frozen", "Toxic", "Void", "Electric", "Molten", "Golden", "Prismatic", "Celestial" },
	-- v4: сколько РАЗНЫХ тотемов каждого тира катается в стоке за цикл.
	-- Игрок видит тиры своего диапазона (±1) → до 3 × TotemsPerTier карточек.
	TotemsPerTier = 2,
	TierWeights = { 30, 22, 15, 11, 8, 5.5, 3.5, 2.5, 1.5, 1 }, -- legacy, v4 не использует
	-- ДЕКОР — без эффектов, чисто для красоты. Asset — своя модель в
	-- ReplicatedStorage.Assets (пивот у основания), иначе плейсхолдер.
	Decor = {
		IronLantern    = { DisplayName = "Iron Lantern",    Icon = "🏮", Rarity = "Common",    Price = 400,  Asset = "Decor_IronLantern" },
		CrystalLantern = { DisplayName = "Crystal Lantern", Icon = "💡", Rarity = "Uncommon",  Price = 2000,  Asset = "Decor_CrystalLantern" },
		OreBarrel      = { DisplayName = "Ore Barrel",      Icon = "🛢", Rarity = "Common",    Price = 600,  Asset = "Decor_OreBarrel" },
		CrystalCluster = { DisplayName = "Crystal Cluster", Icon = "💎", Rarity = "Rare",      Price = 20000,  Asset = "Decor_CrystalCluster" },
		MinerStatue    = { DisplayName = "Miner Statue",    Icon = "🗿", Rarity = "Epic",      Price = 80000, Asset = "Decor_MinerStatue" },
		MoleStatue     = { DisplayName = "Golden Mole Statue", Icon = "🏆", Rarity = "Legendary", Price = 400000, Asset = "Decor_MoleStatue" },
		PlushMole      = { DisplayName = "Plush Mole",      Icon = "🧸", Rarity = "Rare",      Price = 6000,  Asset = "Decor_PlushMole" },
	},
	DecorOrder = { "IronLantern", "OreBarrel", "CrystalLantern", "PlushMole", "CrystalCluster", "MinerStatue", "MoleStatue" },
	DecorWeights = { IronLantern = 30, OreBarrel = 25, CrystalLantern = 18, PlushMole = 12, CrystalCluster = 9, MinerStatue = 4, MoleStatue = 2 },
}

--------------------------------------------------------------------------------
-- v14 — РЕЛИКВИИ-ТРОФЕИ (см. BaseDecorService)
--
-- Сверхредкий дроп из валунов (и гарантированный — из Золотого валуна).
-- Каждая реликвия получает ГЛОБАЛЬНЫЙ серийный номер (DataStore, общий для
-- всех серверов): «Crowned Mole Skull #14». Ставится на базе на постамент
-- с табличкой «найдено: ИМЯ». Пока стоит — даёт небольшой бонус к доходу
-- (IncomeBonus), поэтому выбор «держать или продать» — настоящий.
--
-- Падают ТОЛЬКО с валунов и из сундуков (ChestMultiplier), не продаются и
-- не покупаются. Лежат в инвентаре (вкладка RELICS), ставятся на базу
-- сколько угодно, как тотемы.
--
-- Своя модель: ReplicatedStorage.Assets.<Asset> — Model с PrimaryPart
-- (или частью "Root"), пивот у основания. Все ParticleEmitter, Attachment,
-- Beam, Light внутри сохраняются как есть.
--------------------------------------------------------------------------------
Config.Relics = {
	Order = { "GoldenPickaxeTrophy", "CrownedMoleSkull", "DragonEggFossil", "HeartOfTheMountain" },
	Types = {
		GoldenPickaxeTrophy = { DisplayName = "Golden Pickaxe Trophy", Icon = "🏆", Rarity = "Epic",      Chance = 1 / 5000,   IncomeBonus = 0.02, Color = Color3.fromRGB(255, 205, 70),  Asset = "Relic_GoldenPickaxeTrophy" },
		CrownedMoleSkull    = { DisplayName = "Crowned Mole Skull",    Icon = "💀", Rarity = "Legendary", Chance = 1 / 20000,  IncomeBonus = 0.04, Color = Color3.fromRGB(240, 230, 200), Asset = "Relic_CrownedMoleSkull" },
		DragonEggFossil     = { DisplayName = "Dragon Egg Fossil",     Icon = "🥚", Rarity = "Mythic",    Chance = 1 / 75000,  IncomeBonus = 0.07, Color = Color3.fromRGB(255, 90, 60),   Asset = "Relic_DragonEggFossil" },
		HeartOfTheMountain  = { DisplayName = "Heart of the Mountain", Icon = "❤️‍🔥", Rarity = "Secret",    Chance = 1 / 250000, IncomeBonus = 0.12, Color = Color3.fromRGB(255, 60, 140),  Asset = "Relic_HeartOfTheMountain", GlobalAnnounce = true },
	},
	RarityColors = { Secret = Color3.fromRGB(255, 60, 140) },
	TierChanceBonus = 0.06,        -- +6% к шансу за каждый тир валуна выше первого
	PlotBoulderMultiplier = 0.5,   -- личные валуны на базе — вдвое реже
	PerfectMultiplier = 1.5,       -- PERFECT BREAK
	-- Золотой валун: гарантированная реликвия тому, кто добил, по этим весам.
	GoldenWeights = { GoldenPickaxeTrophy = 70, CrownedMoleSkull = 24, DragonEggFossil = 5.2, HeartOfTheMountain = 0.8 },
	-- Сундуки: множитель к базовым шансам реликвии по редкости сундука.
	ChestMultiplier = { Common = 1, Rare = 2.5, Epic = 6, Legendary = 15 },
	SerialDataStore = "RelicSerials_v1",
}

