-- v14 — ЗОЛОТОЙ ВАЛУН (событие, см. RockService:_startGoldenBoulder)
--
-- Раз в 15–25 минут один из валунов на карте становится золотым: светится,
-- виден издалека, анонс всему серверу. Ударов нужно в HitsMultiplier раз
-- больше, прогресс общий — за него идёт гонка. Каждый, кто бил, получает
-- лут с множителем денег MoneyMult; тот, кто ДОБИЛ, — гарантированную
-- реликвию (Config.Relics.GoldenWeights), остальные — шанс ContributorRelicChance.
--------------------------------------------------------------------------------
Config.GoldenBoulder = {
	Enabled = true,
	FirstDelay = 5 * 60,
	IntervalMin = 15 * 60,
	IntervalMax = 25 * 60,
	LifetimeSeconds = 5 * 60,      -- не добили — золото гаснет, валун становится обычным
	HitsMultiplier = 2.5,
	MoneyMult = 5,
	ExtraRolls = 2,
	ContributorRelicChance = 0.15,
	Color = Color3.fromRGB(255, 200, 40),
	BeamHeight = 120,
}

