-- кирка из Pool (только из тех, у кого есть ассет). Ушедшая не возвращается
-- CooldownCycles циклов. Сток — 1 на игрока. Никогда не выпадает из жеод.
-- Если ни у одной кирки из Pool ещё нет ассета — берётся FallbackPool.
Config.Merchant.Limited = {
