	FallbackPool = { "TungTungStick", "BigMole", "GoldSword", "GoldKunai" },
	PriceByRarity = { Rare = 120000, Epic = 400000, Legendary = 1500000, Mythic = 5000000 }, -- v4: фиксированные
}
do
	local defs = Config.Skins.Definitions
	defs.LimitedSunforge     = { Kind = "Pickaxe", DisplayName = "Sunforge Pickaxe",  Rarity = "Legendary", AssetName = "Skin_Pickaxe_Sunforge",     ImageId = 0, NpcExclusive = true, MerchantLimited = true }
	defs.LimitedAbyssal      = { Kind = "Pickaxe", DisplayName = "Abyssal Pick",      Rarity = "Mythic",    AssetName = "Skin_Pickaxe_Abyssal",      ImageId = 0, NpcExclusive = true, MerchantLimited = true }
	defs.LimitedCandyCane    = { Kind = "Pickaxe", DisplayName = "Candy Cane Pick",   Rarity = "Epic",      AssetName = "Skin_Pickaxe_CandyCane",    ImageId = 0, NpcExclusive = true, MerchantLimited = true }
