	defs.LimitedPrismBreaker = { Kind = "Pickaxe", DisplayName = "Prism Breaker",     Rarity = "Mythic",    AssetName = "Skin_Pickaxe_PrismBreaker", ImageId = 0, NpcExclusive = true, MerchantLimited = true }
