--------------------------------------------------------------------------------
-- v18: УНИКАЛЬНЫЙ ЛУТ. У каждого источника своя «профессия», его дроп больше
-- нигде не выпадает (кроме денег):
--   ЖЕОДЫ   — недра земли: кристаллы на подиум, деньги, ЭССЕНЦИИ МУТАЦИЙ
--             (наносятся на кристалл подиума), СЕРДЦЕ ЖЕОДЫ (след. жеода ×3).
--             Скинов и баффов в жеодах больше нет.
--   СУНДУКИ — сокровища: деньги, ПИРАТСКИЕ СКИНЫ (только из сундуков),
--             АМУЛЕТЫ (эффекты, которых нет у зелий), очко престижа.
--             Жеод, динамита и баффов в сундуках больше нет.
-- Шансы считает shared/DropTables.lua — ОДИН модуль и для сервера (ролл),
-- и для окна шансов (client/DropPreviewUI), поэтому показанное = реальное.
--------------------------------------------------------------------------------

-- ЖЕОДЫ: доли категорий (одинаковые для всех типов жеод).
Config.Geodes.Drops = {
	Crystal = 0.55,  -- кристалл на подиум (поровну между Ores типа)
	Money = 0.33,    -- делится 70/25/5 между Money[1..3]
	Essence = 0.11,  -- эссенция мутации (пул — Essence.ByGeode)
	Heart = 0.01,    -- сердце жеоды
}
Config.Geodes.MoneySplit = { 0.70, 0.25, 0.05 }
Config.Geodes.BuffChance = 0 -- баффы из жеод убраны

-- ЭССЕНЦИИ МУТАЦИЙ. Лежат в инвентаре (снаряжение "Essence_<Мутация>").
-- Подходишь к своему подиуму с установленным кристаллом → промпт
-- «APPLY ESSENCE» → кристалл получает эту мутацию (новая ячейка коллекции,
-- доход × множитель мутации). Держишь эссенцию в руке — наносится она,
-- иначе самая редкая из имеющихся, которой у кристалла ещё нет.
Config.Geodes.Essence = {
	MaxPerCrystal = 2, -- сколько мутаций максимум может быть на одном кристалле
	-- Пул по типу жеоды: { мутация, вес }. Чем дороже жеода — тем редкие мутации.
	ByGeode = {
		Stone       = { { "Mossy", 70 },    { "Rusty", 30 } },
		Crystal     = { { "Cracked", 70 },  { "Frozen", 30 } },
		Amber       = { { "Frozen", 60 },   { "Soaked", 40 } },
		Topaz       = { { "Soaked", 60 },   { "Toxic", 40 } },
		Jade        = { { "Toxic", 60 },    { "Void", 40 } },
		Onyx        = { { "Void", 60 },     { "Electric", 40 } },
		Aurora      = { { "Electric", 55 }, { "Molten", 45 } },
		Nebula      = { { "Molten", 55 },   { "Sanguine", 30 }, { "Golden", 15 } },
		Quasar      = { { "Golden", 55 },   { "Radiant", 35 },  { "Glitched", 10 } },
		Singularity = { { "Radiant", 50 },  { "Prismatic", 35 }, { "Celestial", 15 } },
	},
}

-- СЕРДЦЕ ЖЕОДЫ: копится в профиле; следующая открытая жеода даёт Rewards наград.
Config.Geodes.Heart = { Rewards = 3, DisplayName = "Geode Heart", Icon = "💖", Color = Color3.fromRGB(255, 90, 170) }

-- Скины из жеод больше НЕ выпадают.
for geodeType in Config.Skins.DropChance do
	Config.Skins.DropChance[geodeType] = 0
end

-- АМУЛЕТЫ (charms) — только из сундуков. Работают как зелья: лежат в
-- инвентаре, берёшь в руку и жмёшь — активируются. Эффекты уникальные:
--   Midas Touch      — 5 мин: каждая добытая руда на 1 вариацию лучше (I→II→III);
--   Mutation Magnet  — следующие 5 руд из шахты гарантированно с мутацией;
--   Double Haul      — 5 мин: из шахты вылетает вдвое больше руды.
Config.Potions.Types.Charm_Midas = { Buff = "MidasTouch", Amount = 1, Seconds = 300, DisplayName = "Midas Touch Charm", Icon = "🪙", Color = Color3.fromRGB(255, 205, 60), Charm = true, Rarity = "Rare" }
Config.Potions.Types.Charm_Magnet = { Buff = "MutationMagnet", Amount = 5, Seconds = 600, DisplayName = "Mutation Magnet Charm", Icon = "🧲", Color = Color3.fromRGB(215, 120, 255), Charm = true, Rarity = "Epic" }
Config.Potions.Types.Charm_DoubleHaul = { Buff = "DoubleHaul", Amount = 1, Seconds = 300, DisplayName = "Double Haul Charm", Icon = "⛏", Color = Color3.fromRGB(90, 220, 255), Charm = true, Rarity = "Legendary" }
Config.Charms = {
	Order = { "Charm_Midas", "Charm_Magnet", "Charm_DoubleHaul" },
	-- Вес амулета внутри категории «амулет» по редкости сундука.
	Weights = {
		Common    = { Charm_Midas = 80, Charm_Magnet = 18, Charm_DoubleHaul = 2 },
		Rare      = { Charm_Midas = 60, Charm_Magnet = 30, Charm_DoubleHaul = 10 },
		Epic      = { Charm_Midas = 45, Charm_Magnet = 35, Charm_DoubleHaul = 20 },
		Legendary = { Charm_Midas = 30, Charm_Magnet = 38, Charm_DoubleHaul = 32 },
	},
}
for _, key in Config.Charms.Order do
	table.insert(Config.Potions.Order, key)
end
Config.Buffs.MidasTouch = {
	DisplayName = "MIDAS TOUCH", Amount = 1, Rarity = "Rare", ImageId = 0, IconText = "MT",
	Color = Color3.fromRGB(255, 205, 60), Description = "Every ore you mine rolls one variation higher (I → II → III).",
}
Config.Buffs.MutationMagnet = {
	DisplayName = "MUTATION MAGNET", Amount = 5, Rarity = "Epic", ImageId = 0, IconText = "MG",
	Color = Color3.fromRGB(215, 120, 255), Description = "Your next mined ores are guaranteed to have a mutation.",
}
Config.Buffs.DoubleHaul = {
	DisplayName = "DOUBLE HAUL", Amount = 1, Rarity = "Legendary", ImageId = 0, IconText = "x2",
	Color = Color3.fromRGB(90, 220, 255), Description = "Mines eject twice as much ore.",
}

-- ПИРАТСКИЙ КЛАД — скины кирок ТОЛЬКО из сундуков. Chests — из каких
-- сундуков выпадает. Своя модель: ReplicatedStorage.Assets.<AssetName>
-- (Tool или Model с Handle); пока её нет — сервер собирает простую модель
-- сам (shared/ProceduralSkins.lua), поэтому скины работают сразу.
do
	local defs = Config.Skins.Definitions
	local function pirate(id, name, rarity, chests)
		defs[id] = { Kind = "Pickaxe", DisplayName = name, Rarity = rarity, AssetName = "Skin_Pickaxe_" .. id, ImageId = 0, Chests = chests, Procedural = true, Set = "Pirate" }
	end
	pirate("RustyShovel",        "Rusty Shovel",          "Common",    { Common = true, Rare = true })
	pirate("BonePick",           "Bone Pick",             "Common",    { Common = true, Rare = true })
	pirate("AnchorPick",         "Anchor Pick",           "Rare",      { Common = true, Rare = true, Epic = true })
	pirate("PirateHook",         "Pirate Hook",           "Rare",      { Rare = true, Epic = true })
	pirate("KrakenTentacle",     "Kraken Tentacle",       "Epic",      { Rare = true, Epic = true, Legendary = true })
	pirate("SkeletonKey",        "Skeleton Key",          "Epic",      { Epic = true, Legendary = true })
	pirate("GoldenTrident",      "Golden Trident",        "Legendary", { Epic = true, Legendary = true })
	pirate("DoubloonAxe",        "Doubloon Axe",          "Legendary", { Legendary = true })
	pirate("CursedCaptainBlade", "Cursed Captain's Blade","Mythic",    { Legendary = true })
end
Config.SkinBuffs.RustyShovel        = { Boulder = 0.10, ChestLuck = 0.05, Speed = -0.04 }
Config.SkinBuffs.BonePick           = { Damage = 0.10, Stagger = 0.06, Luck = -0.03 }
Config.SkinBuffs.AnchorPick         = { Stagger = 0.18, Toughness = 0.10, Speed = -0.06 }
Config.SkinBuffs.PirateHook         = { ChestLuck = 0.15, Speed = 0.05, Toughness = -0.08 }
Config.SkinBuffs.KrakenTentacle     = { Mutation = 0.15, Stagger = 0.15, Money = -0.05 }
Config.SkinBuffs.SkeletonKey        = { ChestLuck = 0.25, Luck = 0.08, Damage = -0.10 }
Config.SkinBuffs.GoldenTrident      = { Money = 0.12, Damage = 0.20, Speed = -0.06 }
Config.SkinBuffs.DoubloonAxe        = { Money = 0.18, ChestLuck = 0.15, Toughness = -0.12 }
Config.SkinBuffs.CursedCaptainBlade = { Luck = 0.18, Mutation = 0.20, Money = 0.08, Toughness = -0.20 }

-- СУНДУКИ: новый лут. Rolls — сколько наград за открытие. Skin — пул
-- скинов с Chests[редкость]; вес скина внутри пула — SkinRarityWeights.
-- Дубль скина превращается в деньги (DuplicateCarts полных тележек).
Config.Chests.SkinRarityWeights = { Common = 50, Uncommon = 40, Rare = 30, Epic = 14, Legendary = 5, Mythic = 1 }
Config.Chests.DuplicateCarts = { Common = 1, Rare = 2, Epic = 3.5, Legendary = 6 }
