-- v19: ВАЛУНЫ — ПЛАШКА ХП, ЦИФРЫ УРОНА, ВИНЬЕТКА (client/BoulderHitFX).
-- Плашка в стиле The Forge: тёмная подложка, имя слева, ХП справа, полоса с
-- белым «хвостом» урона. Видна рядом с камнем или после удара. Кольцо из
-- партов над камнем и старый билборд «BOULDER LV» убраны.
-- Имя: атрибут DisplayName на модели валуна (если задан в Studio), иначе
-- DisplayNames[тир].
Config.BoulderHitFx = {
	Enabled = true,
	DisplayNames = { "Mossy Pebble", "Icy Pebble", "Rough Stone", "Copper Rock", "Granite Chunk", "Crystal Boulder", "Obsidian Slab", "Magma Boulder", "Void Monolith" },
	ShowDistance = 55,     -- v19.5: ближе — плашка видна всегда (как старый билборд валуна)
	HitShowSeconds = 4,    -- после удара видна столько секунд
	MaxDistance = 70,
	PlateColor = Color3.fromRGB(14, 14, 18),
	-- v20: ТРЯСКА ВАЛУНА на каждый удар (видят все игроки): толчок от
	-- бьющего → пружина обратно с перелётом → затухание.
	--   Push — сдвиг (студы), Tilt — наклон (градусы) при силе удара 1;
	--   Frequency — частота пружины (рад/с), Damping — затухание, Duration — сек.
	Wobble = { Enabled = true, Push = 0.45, Tilt = 9, Frequency = 22, Damping = 7.5, Duration = 0.7 },
	-- Виньетка по краям экрана на удар: цвет и непрозрачность у края (0..1).
	Vignette = {
		-- v19.1: вспышка только в момент удара, не больше 10% видимости.
		Miss = { Color = Color3.fromRGB(255, 255, 255), Alpha = 0.05 },
		Good = { Color = Color3.fromRGB(255, 255, 255), Alpha = 0.08 },
		Perfect = { Color = Color3.fromRGB(255, 205, 70), Alpha = 0.10 },
		Dynamite = { Color = Color3.fromRGB(255, 150, 60), Alpha = 0.10 },
		Final = { Color = Color3.fromRGB(255, 245, 225), Alpha = 0.10 },
		MaxAlpha = 0.10, -- потолок для любых значений выше
		Seconds = 0.12,  -- за сколько гаснет
	},
}

-- v20: цена престижа — в масштабе дохода пещеры, где его делают (Config.NumberGrowth).
if Config.Prestige and Config.Prestige.CostBase then
	Config.Prestige.CostBase = Config.NiceNumber(Config.Prestige.CostBase * Config.CaveNumberScale(Config.Prestige.MinCave or 8))
	Config.Prestige.CostMax = Config.NiceNumber((Config.Prestige.CostMax or 1e15) * Config.CaveNumberScale(#Config.MineTiers))
end

return Config
